insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','ez',1,1,'E aconteceu no trigésimo ano, no quarto mês, no quinto dia do mês, que estando eu no meio dos cativos, junto ao rio Quebar, se abriram os céus, e eu tive visões de Deus.'),
('acf','ez',1,2,'No quinto dia do mês, no quinto ano do cativeiro do rei Jeoiaquim,'),
('acf','ez',1,3,'Veio expressamente a palavra do Senhor a Ezequiel, filho de Buzi, o sacerdote, na terra dos caldeus, junto ao rio Quebar, e ali esteve sobre ele a mão do Senhor.'),
('acf','ez',1,4,'Olhei, e eis que um vento tempestuoso vinha do norte, uma grande nuvem, com um fogo revolvendo-se nela, e um resplendor ao redor, e no meio dela havia uma coisa, como de cor de âmbar, que saía do meio do fogo.'),
('acf','ez',1,5,'E do meio dela saía a semelhança de quatro seres viventes. E esta era a sua aparência: tinham a semelhança de homem.'),
('acf','ez',1,6,'E cada um tinha quatro rostos, como também cada um deles quatro asas.'),
('acf','ez',1,7,'E os seus pés eram pés direitos; e as plantas dos seus pés como a planta do pé de uma bezerra, e luziam como a cor de cobre polido.'),
('acf','ez',1,8,'E tinham mãos de homem debaixo das suas asas, aos quatro lados; e assim todos quatro tinham seus rostos e suas asas.'),
('acf','ez',1,9,'Uniam-se as suas asas uma à outra; não se viravam quando andavam, e cada qual andava continuamente em frente.'),
('acf','ez',1,10,'E a semelhança dos seus rostos era como o rosto de homem; e do lado direito todos os quatro tinham rosto de leão, e do lado esquerdo todos os quatro tinham rosto de boi; e também tinham rosto de águia todos os quatro.'),
('acf','ez',1,11,'Assim eram os seus rostos. As suas asas estavam estendidas por cima; cada qual tinha duas asas juntas uma a outra, e duas cobriam os corpos deles.'),
('acf','ez',1,12,'E cada qual andava para adiante de si; para onde o espírito havia de ir, iam; não se viravam quando andavam.'),
('acf','ez',1,13,'E, quanto à semelhança dos seres viventes, o seu aspecto era como ardentes brasas de fogo, com uma aparência de lâmpadas; o fogo subia e descia por entre os seres viventes, e o fogo resplandecia, e do fogo saíam relâmpagos;'),
('acf','ez',1,14,'E os seres viventes corriam, e voltavam, à semelhança de um clarão de relâmpago.'),
('acf','ez',1,15,'E vi os seres viventes; e eis que havia uma roda sobre a terra junto aos seres viventes, uma para cada um dos quatro rostos.'),
('acf','ez',1,16,'O aspecto das rodas, e a obra delas, era como a cor de berilo; e as quatro tinham uma mesma semelhança; e o seu aspecto, e a sua obra, era como se estivera uma roda no meio de outra roda.'),
('acf','ez',1,17,'Andando elas, andavam pelos seus quatro lados; não se viravam quando andavam.'),
('acf','ez',1,18,'E os seus aros eram tão altos, que faziam medo; e estas quatro tinham as suas cambotas cheias de olhos ao redor.'),
('acf','ez',1,19,'E, andando os seres viventes, andavam as rodas ao lado deles; e, elevando-se os seres viventes da terra, elevavam-se também as rodas.'),
('acf','ez',1,20,'Para onde o espírito queria ir, eles iam; para onde o espírito tinha de ir; e as rodas se elevavam defronte deles, porque o espírito do ser vivente estava nas rodas.'),
('acf','ez',1,21,'Andando eles, andavam elas e, parando eles, paravam elas e, elevando-se eles da terra, elevavam-se também as rodas defronte deles; porque o espírito do ser vivente estava nas rodas.'),
('acf','ez',1,22,'E sobre as cabeças dos seres viventes havia uma semelhança de firmamento, com a aparência de cristal terrível, estendido por cima, sobre as suas cabeças.'),
('acf','ez',1,23,'E debaixo do firmamento estavam as suas asas direitas uma em direção à outra; cada um tinha duas, que lhe cobriam o corpo de um lado; e cada um tinha outras duas asas, que os cobriam do outro lado.'),
('acf','ez',1,24,'E, andando eles, ouvi o ruído das suas asas, como o ruído de muitas águas, como a voz do Onipotente, um tumulto como o estrépito de um exército; parando eles, abaixavam as suas asas.'),
('acf','ez',1,25,'E ouviu-se uma voz vinda do firmamento, que estava por cima das suas cabeças; parando eles, abaixavam as suas asas.'),
('acf','ez',1,26,'E por cima do firmamento, que estava por cima das suas cabeças, havia algo semelhante a um trono que parecia de pedra de safira; e sobre esta espécie de trono havia uma figura semelhante a de um homem, na parte de cima, sobre ele.'),
('acf','ez',1,27,'E vi-a como a cor de âmbar, como a aparência do fogo pelo interior dele ao redor, desde o aspecto dos seus lombos, e daí para cima; e, desde o aspecto dos seus lombos e daí para baixo, vi como a semelhança de fogo, e um resplendor ao redor dele.'),
('acf','ez',1,28,'Como o aspecto do arco que aparece na nuvem no dia da chuva, assim era o aspecto do resplendor em redor. Este era o aspecto da semelhança da glória do Senhor; e, vendo isto, caí sobre o meu rosto, e ouvi a voz de quem falava.'),
('acf','ez',2,1,'E disse-me: Filho do homem, põe-te em pé, e falarei contigo.'),
('acf','ez',2,2,'Então entrou em mim o Espírito, quando ele falava comigo, e me pôs em pé, e ouvi o que me falava.'),
('acf','ez',2,3,'E disse-me: Filho do homem, eu te envio aos filhos de Israel, às nações rebeldes que se rebelaram contra mim; eles e seus pais transgrediram contra mim até este mesmo dia.'),
('acf','ez',2,4,'E os filhos são de semblante duro, e obstinados de coração; eu te envio a eles, e lhes dirás: Assim diz o Senhor DEUS.'),
('acf','ez',2,5,'E eles, quer ouçam quer deixem de ouvir (porque eles são casa rebelde), hão de saber, contudo, que esteve no meio deles um profeta.'),
('acf','ez',2,6,'E tu, ó filho do homem, não os temas, nem temas as suas palavras; ainda que estejam contigo sarças e espinhos, e tu habites entre escorpiões, não temas as suas palavras, nem te assustes com os seus semblantes, porque são casa rebelde.'),
('acf','ez',2,7,'Mas tu lhes dirás as minhas palavras, quer ouçam quer deixem de ouvir, pois são rebeldes.'),
('acf','ez',2,8,'Mas tu, ó filho do homem, ouve o que eu te falo, não sejas rebelde como a casa rebelde; abre a tua boca, e come o que eu te dou.'),
('acf','ez',2,9,'Então vi, e eis que uma mão se estendia para mim, e eis que nela havia um rolo de livro.'),
('acf','ez',2,10,'E estendeu-o diante de mim, e ele estava escrito por dentro e por fora; e nele estavam escritas lamentações, e suspiros e ais.'),
('acf','ez',3,1,'Depois me disse: Filho do homem, come o que achares; come este rolo, e vai, fala à casa de Israel.'),
('acf','ez',3,2,'Então abri a minha boca, e me deu a comer o rolo.'),
('acf','ez',3,3,'E disse-me: Filho do homem, dá de comer ao teu ventre, e enche as tuas entranhas deste rolo que eu te dou. Então o comi, e era na minha boca doce como o mel.'),
('acf','ez',3,4,'E disse-me ainda: Filho do homem, vai, entra na casa de Israel, e dize-lhe as minhas palavras.'),
('acf','ez',3,5,'Porque tu não és enviado a um povo de estranha fala, nem de língua difícil, mas à casa de Israel;'),
('acf','ez',3,6,'Nem a muitos povos de estranha fala, e de língua difícil, cujas palavras não possas entender; se eu aos tais te enviara, certamente te dariam ouvidos.'),
('acf','ez',3,7,'Mas a casa de Israel não te quererá dar ouvidos, porque não me querem dar ouvidos a mim; pois toda a casa de Israel é de fronte obstinada e dura de coração.'),
('acf','ez',3,8,'Eis que fiz duro o teu rosto contra os seus rostos, e forte a tua fronte contra a sua fronte.'),
('acf','ez',3,9,'Fiz como diamante a tua fronte, mais forte do que a pederneira; não os temas, pois, nem te assombres com os seus rostos, porque são casa rebelde.'),
('acf','ez',3,10,'Disse-me mais: Filho do homem, recebe no teu coração todas as minhas palavras que te hei de dizer, e ouve-as com os teus ouvidos.'),
('acf','ez',3,11,'Eia, pois, vai aos do cativeiro, aos filhos do teu povo, e lhes falarás e lhes dirás: Assim diz o Senhor DEUS, quer ouçam quer deixem de ouvir.'),
('acf','ez',3,12,'E levantou-me o Espírito, e ouvi por detrás de mim uma voz de grande estrondo, que dizia: Bendita seja a glória do SENHOR, desde o seu lugar.'),
('acf','ez',3,13,'E ouvi o ruído das asas dos seres viventes, que tocavam umas nas outras, e o ruído das rodas defronte deles, e o sonido de um grande estrondo.'),
('acf','ez',3,14,'Então o espírito me levantou, e me levou; e eu me fui amargurado, na indignação do meu Espírito; porém a mão do SENHOR era forte sobre mim.'),
('acf','ez',3,15,'E fui a Tel-Abibe, aos do cativeiro, que moravam junto ao rio Quebar, e eu morava onde eles moravam; e fiquei ali sete dias, pasmado no meio deles.'),
('acf','ez',3,16,'E sucedeu que, ao fim de sete dias, veio a palavra do Senhor a mim, dizendo:'),
('acf','ez',3,17,'Filho do homem: Eu te dei por atalaia sobre a casa de Israel; e tu da minha boca ouvirás a palavra e avisá-los-ás da minha parte.'),
('acf','ez',3,18,'Quando eu disser ao ímpio: Certamente morrerás; e tu não o avisares, nem falares para avisar o ímpio acerca do seu mau caminho, para salvar a sua vida, aquele ímpio morrerá na sua iniqüidade, mas o seu sangue, da tua mão o requererei.'),
('acf','ez',3,19,'Mas, se avisares ao ímpio, e ele não se converter da sua impiedade e do seu mau caminho, ele morrerá na sua iniqüidade, mas tu livraste a tua alma.'),
('acf','ez',3,20,'Semelhantemente, quando o justo se desviar da sua justiça, e cometer a iniqüidade, e eu puser diante dele um tropeço, ele morrerá: porque tu não o avisaste, no seu pecado morrerá; e suas justiças, que tiver praticado, não serão lembradas, mas o seu sangue, da tua mão o requererei.'),
('acf','ez',3,21,'Mas, avisando tu o justo, para que não peque, e ele não pecar, certamente viverá; porque foi avisado; e tu livraste a tua alma.'),
('acf','ez',3,22,'E a mão do Senhor estava sobre mim ali, e ele me disse: Levanta-te, e sai ao vale, e ali falarei contigo.'),
('acf','ez',3,23,'E levantei-me, e saí ao vale, e eis que a glória do Senhor estava ali, como a glória que vi junto ao rio Quebar; e caí sobre o meu rosto.'),
('acf','ez',3,24,'Então entrou em mim o Espírito, e me pôs em pé, e falou comigo, e me disse: Entra, encerra-te dentro da tua casa.'),
('acf','ez',3,25,'E quanto a ti, ó filho do homem, eis que porão cordas sobre ti, e te ligarão com elas; não sairás, pois, ao meio deles.'),
('acf','ez',3,26,'E eu farei que a tua língua se pegue ao teu paladar, e ficarás mudo, e não lhes servirás de repreendedor; porque eles são casa rebelde.'),
('acf','ez',3,27,'Mas, quando eu falar contigo, abrirei a tua boca, e lhes dirás: Assim diz o Senhor DEUS: Quem ouvir ouça, e quem deixar de ouvir, deixe; porque eles são casa rebelde.'),
('acf','ez',4,1,'Tu, pois, ó filho do homem, toma um tijolo, e pô-lo-ás diante de ti, e grava nele a cidade de Jerusalém.'),
('acf','ez',4,2,'E põe contra ela um cerco, e edifica contra ela uma fortificação, e levanta contra ela uma trincheira, e põe contra ela arraiais, e põe-lhe aríetes em redor.'),
('acf','ez',4,3,'E tu toma uma sertã de ferro, e põe-na por muro de ferro entre ti e a cidade; e dirige para ela o teu rosto, e assim será cercada, e a cercarás; isto servirá de sinal à casa de Israel.'),
('acf','ez',4,4,'Tu também deita-te sobre o teu lado esquerdo, e põe a iniqüidade da casa de Israel sobre ele; conforme o número dos dias que te deitares sobre ele, levarás as suas iniqüidades.'),
('acf','ez',4,5,'Porque eu já te tenho fixado os anos da sua iniqüidade, conforme o número dos dias, trezentos e noventa dias; e levarás a iniqüidade da casa de Israel.'),
('acf','ez',4,6,'E, quando tiveres cumprido estes dias, tornar-te-ás a deitar sobre o teu lado direito, e levarás a iniqüidade da casa de Judá quarenta dias; um dia te dei para cada ano.'),
('acf','ez',4,7,'Dirigirás, pois, o teu rosto para o cerco de Jerusalém, com o teu braço descoberto, e profetizarás contra ela.'),
('acf','ez',4,8,'E eis que porei sobre ti cordas; assim tu não te voltarás de um lado para o outro, até que cumpras os dias do teu cerco.'),
('acf','ez',4,9,'E tu, toma trigo, e cevada, e favas, e lentilhas, e milho e aveia, e coloca-os numa vasilha, e faze deles pão; conforme o número dos dias que tu te deitares sobre o teu lado, trezentos e noventa dias, comerás disso.'),
('acf','ez',4,10,'E a tua comida, que hás de comer, será do peso de vinte siclos por dia; de tempo em tempo a comerás.'),
('acf','ez',4,11,'Também beberás a água por medida, a saber, a sexta parte de um him; de tempo em tempo beberás.'),
('acf','ez',4,12,'E o que comeres será como bolos de cevada, e cozê-los-ás sobre o esterco que sai do homem, diante dos olhos deles.'),
('acf','ez',4,13,'E disse o Senhor: Assim comerão os filhos de Israel o seu pão imundo, entre os gentios para onde os lançarei.'),
('acf','ez',4,14,'Então disse eu: Ah! Senhor DEUS! Eis que a minha alma não foi contaminada, pois desde a minha mocidade até agora, nunca comi daquilo que morrer de si mesmo, ou que é despedaçado por feras; nem carne abominável entrou na minha boca.'),
('acf','ez',4,15,'E disse-me: Vê, dei-te esterco de vacas, em lugar de esterco de homem; e sobre ele prepararás o teu pão.'),
('acf','ez',4,16,'Disse-me ainda: Filho do homem, eis que eu quebrarei o sustento de pão em Jerusalém, e comerão o pão por peso, e com ansiedade; e a água beberão por medida, e com espanto;'),
('acf','ez',4,17,'Para que lhes falte o pão e a água, e se espantem uns com os outros, e se consumam nas suas iniqüidades.'),
('acf','ez',5,1,'E tu, ó filho do homem, toma uma faca afiada, como navalha de barbeiro, e a farás passar pela tua cabeça e pela tua barba; então tomarás uma balança de peso, e repartirás os cabelos.'),
('acf','ez',5,2,'Uma terça parte queimarás no fogo, no meio da cidade, quando se cumprirem os dias do cerco; então tomarás outra terça parte, e feri-la-ás com uma faca ao redor dela; e a outra terça parte espalharás ao vento; porque desembainharei a espada atrás deles.'),
('acf','ez',5,3,'Também tomarás dali um pequeno número, e atá-los-ás nas bordas do teu manto.'),
('acf','ez',5,4,'E ainda destes tomarás alguns, e os lançarás no meio do fogo e os queimarás a fogo; e dali sairá um fogo contra toda a casa de Israel.'),
('acf','ez',5,5,'Assim diz o Senhor DEUS: Esta é Jerusalém; coloquei-a no meio das nações e das terras que estão ao redor dela.'),
('acf','ez',5,6,'Ela, porém, mudou em impiedade os meus juízos, mais do que as nações, e os meus estatutos mais do que as terras que estão ao redor dela; porque rejeitaram os meus juízos e os meus estatutos, e não andaram neles.'),
('acf','ez',5,7,'Portanto assim diz o Senhor DEUS: Porque multiplicastes mais do que as nações, que estão ao redor de vós, e não andastes nos meus estatutos, nem guardastes os meus juízos, nem ainda procedestes segundo os juízos das nações que estão ao redor de vós;'),
('acf','ez',5,8,'Por isso assim diz o Senhor DEUS: Eis que eu, sim eu, estou contra ti; e executarei juízos no meio de ti aos olhos das nações.'),
('acf','ez',5,9,'E farei em ti o que nunca fiz, e o que jamais farei, por causa de todas as tuas abominações.'),
('acf','ez',5,10,'Portanto os pais comerão a seus filhos no meio de ti, e os filhos comerão a seus pais; e executarei em ti juízos, e tudo o que restar de ti, espalharei a todos os ventos.'),
('acf','ez',5,11,'Portanto, como eu vivo, diz o Senhor DEUS, certamente, porquanto profanaste o meu santuário com todas as tuas coisas detestáveis, e com todas as tuas abominações, também eu te diminuirei, e o meu olho não te perdoará, nem também terei piedade.'),
('acf','ez',5,12,'Uma terça parte de ti morrerá de peste, e se consumirá de fome no meio de ti; e outra terça parte cairá à espada em redor de ti; e a outra terça parte espalharei a todos os ventos, e desembainharei a espada atrás deles.'),
('acf','ez',5,13,'Assim se cumprirá a minha ira, e satisfarei neles o meu furor, e me consolarei; e saberão que eu, o Senhor, tenho falado no meu zelo, quando eu cumprir neles o meu furor.'),
('acf','ez',5,14,'E pôr-te-ei em desolação, e por objeto de opróbrio entre as nações que estão em redor de ti, aos olhos de todos os que passarem.'),
('acf','ez',5,15,'E será objeto de opróbrio e blasfêmia, instrução e espanto às nações que estão em redor de ti, quando eu executar em ti juízos com ira, e com furor, e com terríveis castigos. Eu, o Senhor, falei.'),
('acf','ez',5,16,'Quando eu enviar as malignas flechas da fome contra eles, que servirão para destruição, as quais eu mandarei para vos destruir, então aumentarei a fome sobre vós, e vos quebrarei o sustento do pão.'),
('acf','ez',5,17,'E enviarei sobre vós a fome, e as feras que te desfilharão; e a peste e o sangue passarão por ti; e trarei a espada sobre ti. Eu, o Senhor, falei.'),
('acf','ez',6,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',6,2,'Filho do homem, dirige o teu rosto para os montes de Israel, e profetiza contra eles.'),
('acf','ez',6,3,'E dirás: Montes de Israel, ouvi a palavra do Senhor DEUS: Assim diz o Senhor DEUS aos montes, aos outeiros, aos ribeiros e aos vales: Eis que eu, sim eu, trarei a espada sobre vós, e destruirei os vossos lugares altos.'),
('acf','ez',6,4,'E serão assolados os vossos altares, e quebradas as vossas imagens do sol e derrubarei os vossos mortos, diante dos vossos ídolos.'),
('acf','ez',6,5,'E porei os cadáveres dos filhos de Israel diante dos seus ídolos; e espalharei os vossos ossos em redor dos vossos altares.'),
('acf','ez',6,6,'Em todos os vossos lugares habitáveis, as cidades serão destruídas, e os lugares altos assolados; para que os vossos altares sejam destruídos e assolados, e os vossos ídolos se quebrem e se acabem, e as vossas imagens sejam cortadas, e desfeitas as vossas obras.'),
('acf','ez',6,7,'E os mortos cairão no meio de vós, para que saibais que eu sou o Senhor.'),
('acf','ez',6,8,'Porém deixarei um remanescente, para que tenhais entre as nações alguns que escaparem da espada, quando fordes espalhados pelas terras.'),
('acf','ez',6,9,'Então os que dentre vós escaparem se lembrarão de mim entre as nações para onde foram levados em cativeiro; porquanto me quebrantei por causa do seu coração corrompido, que se desviou de mim, e por causa dos seus olhos, que andaram se corrompendo após os seus ídolos; e terão nojo de si mesmos, por causa das maldades que fizeram em todas as suas abominações.'),
('acf','ez',6,10,'E saberão que eu sou o Senhor, e que não disse debalde que lhes faria este mal.'),
('acf','ez',6,11,'Assim diz o Senhor DEUS: Bate com a mão, e bate com o teu pé, e dize: Ah! Por todas as grandes abominações da casa de Israel! Porque cairão à espada, e de fome, e de peste.'),
('acf','ez',6,12,'O que estiver longe morrerá de peste, e o que está perto cairá à espada; e o que restar e ficar cercado morrerá de fome; assim cumprirei o meu furor sobre eles.'),
('acf','ez',6,13,'Então sabereis que eu sou o Senhor, quando os seus mortos estiverem no meio dos seus ídolos, em redor dos seus altares, em todo o outeiro alto, em todos os cumes dos montes, e debaixo de toda a árvore verde, e debaixo de todo o carvalho frondoso, no lugar onde ofereciam cheiro suave a todos os seus ídolos.'),
('acf','ez',6,14,'E estenderei a minha mão sobre eles, e farei a terra desolada, e mais devastada do que o deserto do lado de Dibla, em todas as suas habitações; e saberão que eu sou o Senhor.'),
('acf','ez',7,1,'Depois veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',7,2,'E tu, ó filho do homem, assim diz o Senhor DEUS acerca da terra de Israel: Vem o fim, o fim vem sobre os quatro cantos da terra.'),
('acf','ez',7,3,'Agora vem o fim sobre ti, e enviarei sobre ti a minha ira, e te julgarei conforme os teus caminhos, e trarei sobre ti todas as tuas abominações.'),
('acf','ez',7,4,'E não te poupará o meu olho, nem terei piedade de ti, mas porei sobre ti os teus caminhos, e as tuas abominações estarão no meio de ti; e sabereis que eu sou o Senhor.'),
('acf','ez',7,5,'Assim diz o Senhor DEUS: Um mal, eis que um só mal vem.'),
('acf','ez',7,6,'Vem o fim, o fim vem, despertou-se contra ti; eis que vem.'),
('acf','ez',7,7,'A manhà vem para ti, ó habitante da terra. Vem o tempo; chegado é o dia da turbação, e não mais o sonido de alegria dos montes.'),
('acf','ez',7,8,'Agora depressa derramarei o meu furor sobre ti, e cumprirei a minha ira contra ti, e te julgarei conforme os teus caminhos, e porei sobre ti todas as tuas abominações.'),
('acf','ez',7,9,'E não te poupará o meu olho, nem terei piedade de ti; conforme os teus caminhos, assim te punirei, e as tuas abominações estarão no meio de ti; e sabereis que eu, o Senhor, é que firo.'),
('acf','ez',7,10,'Eis aqui o dia, eis que vem; veio a manhà, já floresceu a vara, já reverdeceu a soberba.'),
('acf','ez',7,11,'A violência se levantou em vara de impiedade; nada restará deles, nem da sua multidão, nem do seu rumor, nem haverá lamentação por eles.'),
('acf','ez',7,12,'Vem o tempo, é chegado o dia; o que compra não se alegre, e o que vende não se entristeça; porque a ira ardente está sobre toda a multidão deles.'),
('acf','ez',7,13,'Porque o que vende não tornará a possuir o que vendeu, ainda que esteja entre os viventes; porque a visão, sobre toda a sua multidão, não tornará para trás, nem ninguém fortalecerá a sua vida com a sua iniqüidade.'),
('acf','ez',7,14,'Já tocaram a trombeta, e tudo prepararam, mas não há quem vá à peleja, porque a minha ardente ira está sobre toda a sua multidão.'),
('acf','ez',7,15,'Fora está a espada, e dentro a peste e a fome; o que estiver no campo morrerá à espada, e o que estiver na cidade a fome e a peste o consumirão.'),
('acf','ez',7,16,'E escaparão os que fugirem deles, mas estarão pelos montes, como pombas dos vales, todos gemendo, cada um por causa da sua iniqüidade.'),
('acf','ez',7,17,'Todas as mãos se enfraquecerão, e todos os joelhos serão débeis como água.'),
('acf','ez',7,18,'E cingir-se-ão de sacos, e o terror os cobrirá; e sobre todos os rostos haverá vergonha, e sobre todas as suas cabeças, calva.'),
('acf','ez',7,19,'A sua prata lançarão pelas ruas, e o seu ouro será removido; nem a sua prata nem o seu ouro os poderá livrar no dia do furor do Senhor; eles não fartarão a sua alma, nem lhes encherão o estômago, porque isto foi o tropeço da sua iniqüidade.'),
('acf','ez',7,20,'E a glória do seu ornamento ele a pôs em magnificência, mas eles fizeram nela imagens das suas abominações e coisas detestáveis; por isso eu lha tenho feito coisa imunda.'),
('acf','ez',7,21,'E entregá-la-ei por presa, na mão dos estrangeiros, e aos ímpios da terra por despojo; e a profanarão.'),
('acf','ez',7,22,'E desviarei deles o meu rosto, e profanarão o meu lugar oculto; porque entrarão nele saqueadores, e o profanarão.'),
('acf','ez',7,23,'Faze uma cadeia, porque a terra está cheia de crimes de sangue, e a cidade está cheia de violência.'),
('acf','ez',7,24,'E farei vir os piores dentre os gentios e possuirão as suas casas; e farei cessar a arrogância dos fortes, e os seus lugares santos serão profanados.'),
('acf','ez',7,25,'Vem a destruição; eles buscarão a paz, mas não há nenhuma.'),
('acf','ez',7,26,'Miséria sobre miséria virá, e se levantará rumor sobre rumor; então buscarão do profeta uma visão, mas do sacerdote perecerá a lei e dos anciãos o conselho.'),
('acf','ez',7,27,'O rei lamentará, e o príncipe se vestirá de desolação, e as mãos do povo da terra se conturbarão; conforme o seu caminho lhes farei, e conforme os seus merecimentos os julgarei; e saberão que eu sou o Senhor.'),
('acf','ez',8,1,'Sucedeu, pois, no sexto ano, no sexto mês, no quinto dia do mês, estando eu assentado na minha casa, e os anciãos de Judá assentados diante de mim, que ali a mão do Senhor DEUS caiu sobre mim.'),
('acf','ez',8,2,'E olhei, e eis uma semelhança como o aspecto de fogo; desde o aspecto dos seus lombos, e daí para baixo, era fogo; e dos seus lombos e daí para cima como o aspecto de um resplendor como a cor de âmbar.'),
('acf','ez',8,3,'E estendeu a forma de uma mão, e tomou-me pelos cabelos da minha cabeça; e o Espírito me levantou entre a terra e o céu, e levou-me a Jerusalém em visões de Deus, até à entrada da porta do pátio de dentro, que olha para o norte, onde estava o assento da imagem do ciúmes, que provoca ciúmes.'),
('acf','ez',8,4,'E eis que a glória do Deus de Israel estava ali, conforme o aspecto que eu tinha visto no vale.'),
('acf','ez',8,5,'E disse-me: Filho do homem, levanta agora os teus olhos para o caminho do norte. E levantei os meus olhos para o caminho do norte, e eis que ao norte da porta do altar, estava esta imagem de ciúmes na entrada.'),
('acf','ez',8,6,'E disse-me: Filho do homem, vês tu o que eles estão fazendo? As grandes abominações que a casa de Israel faz aqui, para que me afaste do meu santuário? Mas ainda tornarás a ver maiores abominações.'),
('acf','ez',8,7,'E levou-me à porta do átrio; então olhei, e eis que havia um buraco na parede.'),
('acf','ez',8,8,'E disse-me: Filho do homem, cava agora naquela parede. E cavei na parede, e eis que havia uma porta.'),
('acf','ez',8,9,'Então me disse: Entra, e vê as malignas abominações que eles fazem aqui.'),
('acf','ez',8,10,'E entrei, e olhei, e eis que toda a forma de répteis, e animais abomináveis, e de todos os ídolos da casa de Israel, estavam pintados na parede em todo o redor.'),
('acf','ez',8,11,'E estavam em pé diante deles setenta homens dos anciãos da casa de Israel, e Jaazanias, filho de Safã, em pé, no meio deles, e cada um tinha na mão o seu incensário; e subia uma espessa nuvem de incenso.'),
('acf','ez',8,12,'Então me disse: Viste, filho do homem, o que os anciãos da casa de Israel fazem nas trevas, cada um nas suas câmaras pintadas de imagens? Pois dizem: O Senhor não nos vê; o Senhor abandonou a terra.'),
('acf','ez',8,13,'E disse-me: Ainda tornarás a ver maiores abominações, que estes fazem.'),
('acf','ez',8,14,'E levou-me à entrada da porta da casa do Senhor, que está do lado norte, e eis que estavam ali mulheres assentadas chorando a Tamuz.'),
('acf','ez',8,15,'E disse-me: Vês isto, filho do homem? Ainda tornarás a ver abominações maiores do que estas.'),
('acf','ez',8,16,'E levou-me para o átrio interior da casa do Senhor, e eis que estavam à entrada do templo do Senhor, entre o pórtico e o altar, cerca de vinte e cinco homens, de costas para o templo do Senhor, e com os rostos para o oriente; e eles, virados para o oriente adoravam o sol.'),
('acf','ez',8,17,'Então me disse: Vês isto, filho do homem? Há porventura coisa mais leviana para a casa de Judá, do que tais abominações, que fazem aqui? Havendo enchido a terra de violência, tornam a irritar-me; e ei-los a chegar o ramo ao seu nariz.'),
('acf','ez',8,18,'Por isso também eu os tratarei com furor; o meu olho não poupará, nem terei piedade; ainda que me gritem aos ouvidos com grande voz, contudo não os ouvirei.'),
('acf','ez',9,1,'Então me gritou aos ouvidos com grande voz, dizendo: Fazei chegar os intendentes da cidade, cada um com as suas armas destruidoras na mão.'),
('acf','ez',9,2,'E eis que vinham seis homens a caminho da porta superior, que olha para o norte, e cada um com a sua arma destruidora na mão, e entre eles um homem vestido de linho, com um tinteiro de escrivão à sua cintura; e entraram, e se puseram junto ao altar de bronze.'),
('acf','ez',9,3,'E a glória do Deus de Israel se levantou de sobre o querubim, sobre o qual estava, indo até a entrada da casa; e clamou ao homem vestido de linho, que tinha o tinteiro de escrivão à sua cintura.'),
('acf','ez',9,4,'E disse-lhe o Senhor: Passa pelo meio da cidade, pelo meio de Jerusalém, e marca com um sinal as testas dos homens que suspiram e que gemem por causa de todas as abominações que se cometem no meio dela.'),
('acf','ez',9,5,'E aos outros disse ele, ouvindo eu: Passai pela cidade após ele, e feri; não poupe o vosso olho, nem vos compadeçais.'),
('acf','ez',9,6,'Matai velhos, jovens, virgens, meninos e mulheres, até exterminá-los; mas a todo o homem que tiver o sinal não vos chegueis; e começai pelo meu santuário. E começaram pelos homens mais velhos que estavam diante da casa.'),
('acf','ez',9,7,'E disse-lhes: Contaminai a casa e enchei os átrios de mortos; saí. E saíram, e feriram na cidade.'),
('acf','ez',9,8,'Sucedeu, pois, que, havendo-os ferido, e ficando eu sozinho, caí sobre a minha face, e clamei, e disse: Ah! Senhor DEUS! dar-se-á caso que destruas todo o restante de Israel, derramando a tua indignação sobre Jerusalém?'),
('acf','ez',9,9,'Então me disse: A maldade da casa de Israel e de Judá é grandíssima, e a terra se encheu de sangue e a cidade se encheu de perversidade; porque dizem: O Senhor abandonou a terra, e o Senhor não vê.'),
('acf','ez',9,10,'Pois, também, quanto a mim, não poupará o meu olho, nem me compadecerei; sobre a cabeça deles farei recair o seu caminho.'),
('acf','ez',9,11,'Eis que o homem que estava vestido de linho, a cuja cintura estava o tinteiro, tornou com a resposta, dizendo: Fiz como me mandaste.'),
('acf','ez',10,1,'Depois olhei, e eis que no firmamento, que estava por cima da cabeça dos querubins, apareceu sobre eles uma como pedra de safira, semelhante a forma de um trono.'),
('acf','ez',10,2,'E falou ao homem vestido de linho, dizendo: Vai por entre as rodas, até debaixo do querubim, e enche as tuas mãos de brasas acesas dentre os querubins e espalha-as sobre a cidade. E ele entrou à minha vista.'),
('acf','ez',10,3,'E os querubins estavam ao lado direito da casa, quando entrou aquele homem; e uma nuvem encheu o átrio interior.'),
('acf','ez',10,4,'Então se levantou a glória do Senhor de sobre o querubim indo para a entrada da casa; e encheu-se a casa de uma nuvem, e o átrio se encheu do resplendor da glória do Senhor.'),
('acf','ez',10,5,'E o ruído das asas dos querubins se ouviu até ao átrio exterior, como a voz do Deus Todo-Poderoso, quando fala.'),
('acf','ez',10,6,'Sucedeu, pois, que, dando ele ordem ao homem vestido de linho, dizendo: Toma fogo dentre as rodas, dentre os querubins, entrou ele, e parou junto às rodas.'),
('acf','ez',10,7,'Então estendeu um querubim a sua mão dentre os querubins para o fogo que estava entre os querubins; e tomou dele, e o pôs nas mãos do que estava vestido de linho; o qual o tomou, e saiu.'),
('acf','ez',10,8,'E apareceu nos querubins uma semelhança de mão de homem debaixo das suas asas.'),
('acf','ez',10,9,'Então olhei, e eis quatro rodas junto aos querubins, uma roda junto a um querubim, e outra roda junto a outro querubim; e o aspecto das rodas era como a cor da pedra de berilo.'),
('acf','ez',10,10,'E, quanto ao seu aspecto, as quatro tinham uma mesma semelhança; como se estivesse uma roda no meio de outra roda.'),
('acf','ez',10,11,'Andando estes, andavam para os quatro lados deles; não se viravam quando andavam, mas para o lugar para onde olhava a cabeça, para esse seguiam; não se viravam quando andavam.'),
('acf','ez',10,12,'E todo o seu corpo, as suas costas, as suas mãos, as suas asas e as rodas, as rodas que os quatro tinham, estavam cheias de olhos ao redor.'),
('acf','ez',10,13,'E, quanto às rodas, ouvindo eu, se lhes gritava: Roda!'),
('acf','ez',10,14,'E cada um tinha quatro rostos; o rosto do primeiro era rosto de querubim, e o rosto do segundo, rosto de homem, e do terceiro era rosto de leão, e do quarto, rosto de águia.'),
('acf','ez',10,15,'E os querubins se elevaram ao alto; estes são os mesmos seres viventes que vi junto ao rio Quebar.'),
('acf','ez',10,16,'E, andando os querubins, andavam as rodas juntamente com eles; e, levantando os querubins as suas asas, para se elevarem de sobre a terra, também as rodas não se separavam deles.'),
('acf','ez',10,17,'Parando eles, paravam elas; e, elevando-se eles elevavam-se elas, porque o espírito do ser vivente estava nelas.'),
('acf','ez',10,18,'Então saiu a glória do Senhor de sobre a entrada da casa, e parou sobre os querubins.'),
('acf','ez',10,19,'E os querubins alçaram as suas asas, e se elevaram da terra aos meus olhos, quando saíram; e as rodas os acompanhavam; e cada um parou à entrada da porta oriental da casa do Senhor; e a glória do Deus de Israel estava em cima, sobre eles.'),
('acf','ez',10,20,'Estes são os seres viventes que vi debaixo do Deus de Israel, junto ao rio Quebar, e conheci que eram querubins.'),
('acf','ez',10,21,'Cada um tinha quatro rostos e cada um quatro asas, e a semelhança de mãos de homem debaixo das suas asas.'),
('acf','ez',10,22,'E a semelhança dos seus rostos era a dos rostos que eu tinha visto junto ao rio Quebar, o aspecto deles, e eles mesmos; cada um andava para diante do seu rosto.'),
('acf','ez',11,1,'Então me levantou o Espírito, e me levou à porta oriental da casa do SENHOR, a qual olha para o oriente; e eis que estavam à entrada da porta vinte e cinco homens; e no meio deles vi a Jaazanias, filho de Azur, e a Pelatias, filho de Benaia, príncipes do povo.'),
('acf','ez',11,2,'E disse-me: Filho do homem, estes são os homens que maquinam perversidade, e dão mau conselho nesta cidade.'),
('acf','ez',11,3,'Os quais dizem: Não está próximo o tempo de edificar casas; esta cidade é o caldeirão, e nós a carne.'),
('acf','ez',11,4,'Portanto, profetiza contra eles; profetiza, ó filho do homem.'),
('acf','ez',11,5,'Caiu, pois, sobre mim o Espírito do Senhor, e disse-me: Fala: Assim diz o Senhor: Assim haveis falado, ó casa de Israel, porque, quanto às coisas que vos sobem ao espírito, eu as conheço.'),
('acf','ez',11,6,'Multiplicastes os vossos mortos nesta cidade, e enchestes as suas ruas de mortos.'),
('acf','ez',11,7,'Portanto, assim diz o Senhor DEUS: Vossos mortos, que deitastes no meio dela, esses são a carne e ela é o caldeirão; a vós, porém, vos tirarei do meio dela.'),
('acf','ez',11,8,'Temestes a espada, e a espada trarei sobre vós, diz o Senhor DEUS.'),
('acf','ez',11,9,'E vos farei sair do meio dela, e vos entregarei na mão de estrangeiros, e exercerei os meus juízos entre vós.'),
('acf','ez',11,10,'Caireis à espada, e nos confins de Israel vos julgarei; e sabereis que eu sou o Senhor.'),
('acf','ez',11,11,'Esta cidade não vos servirá de caldeirão, nem vós servireis de carne no meio dela; nos confins de Israel vos julgarei.'),
('acf','ez',11,12,'E sabereis que eu sou o Senhor, porque não andastes nos meus estatutos, nem cumpristes os meus juízos; antes fizestes conforme os juízos dos gentios que estão ao redor de vós.'),
('acf','ez',11,13,'E aconteceu que, profetizando eu, morreu Pelatias, filho de Benaia; então caí sobre o meu rosto, e clamei com grande voz, e disse: Ah! Senhor DEUS! Porventura darás tu fim ao remanescente de Israel?'),
('acf','ez',11,14,'Então veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',11,15,'Filho do homem, teus irmãos, sim, teus irmãos, os homens de teu parentesco, e toda a casa de Israel, todos eles são aqueles a quem os habitantes de Jerusalém disseram: Apartai-vos para longe do Senhor; esta terra nos foi dada em possessão.'),
('acf','ez',11,16,'Portanto, dize: Assim diz o Senhor DEUS: Ainda que os lancei para longe entre os gentios, e ainda que os espalhei pelas terras, todavia lhes serei como um pequeno santuário, nas terras para onde forem.'),
('acf','ez',11,17,'Portanto, dize: Assim diz o Senhor DEUS: Hei de ajuntar-vos do meio dos povos, e vos recolherei das terras para onde fostes lançados, e vos darei a terra de Israel.'),
('acf','ez',11,18,'E virão ali, e tirarão dela todas as suas coisas detestáveis e todas as suas abominações.'),
('acf','ez',11,19,'E lhes darei um só coração, e um espírito novo porei dentro deles; e tirarei da sua carne o coração de pedra, e lhes darei um coração de carne;'),
('acf','ez',11,20,'Para que andem nos meus estatutos, e guardem os meus juízos, e os cumpram; e eles me serão por povo, e eu lhes serei por Deus.'),
('acf','ez',11,21,'Mas, quanto àqueles cujo coração andar conforme o coração das suas coisas detestáveis, e as suas abominações, farei recair nas suas cabeças o seu caminho, diz o Senhor DEUS.'),
('acf','ez',11,22,'Então os querubins elevaram as suas asas, e as rodas os acompanhavam; e a glória do Deus de Israel estava em cima sobre eles.'),
('acf','ez',11,23,'E a glória do Senhor se alçou desde o meio da cidade; e se pôs sobre o monte que está ao oriente da cidade.'),
('acf','ez',11,24,'Depois o Espírito me levantou, e me levou à Caldéia, para os do cativeiro, em visão, pelo Espírito de Deus; e subiu de sobre mim a visão que eu tinha tido.'),
('acf','ez',11,25,'E falei aos do cativeiro todas as coisas que o Senhor me havia mostrado.'),
('acf','ez',12,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',12,2,'Filho do homem, tu habitas no meio da casa rebelde, que tem olhos para ver e não vê, e tem ouvidos para ouvir e não ouve; porque eles são casa rebelde.'),
('acf','ez',12,3,'Tu, pois, ó filho do homem, prepara mobílias para mudares, e de dia muda aos olhos deles; e do teu lugar mudarás para outro lugar aos olhos deles; bem pode ser que reparem nisso, ainda que eles são casa rebelde.'),
('acf','ez',12,4,'Aos olhos deles, pois, tirarás para fora, de dia, as tuas mobílias, como quem vai mudar; então tu sairás de tarde aos olhos deles, como quem sai mudando para o cativeiro.'),
('acf','ez',12,5,'Faze para ti, à vista deles, uma abertura na parede, e tira-as para fora, por ali.'),
('acf','ez',12,6,'Aos olhos deles, nos seus ombros, às escuras as tirarás, e cobrirás o teu rosto, para que não vejas a terra; porque te dei por sinal à casa de Israel.'),
('acf','ez',12,7,'E fiz assim, como se me deu ordem; as minhas mobílias tirei para fora de dia, como mobílias do cativeiro; então à tarde fiz, com a mão, uma abertura na parede; às escuras as tirei para fora, e nos meus ombros as levei, aos olhos deles.'),
('acf','ez',12,8,'E, pela manhã, veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',12,9,'Filho do homem, porventura não te disse a casa de Israel, aquela casa rebelde: Que fazes tu?'),
('acf','ez',12,10,'Dize-lhes: Assim diz o Senhor DEUS: Esta carga refere-se ao príncipe em Jerusalém, e a toda a casa de Israel, que está no meio dela.'),
('acf','ez',12,11,'Dize: Eu sou o vosso sinal. Assim como eu fiz, assim se lhes fará a eles; irão para o exílio em cativeiro.'),
('acf','ez',12,12,'E o príncipe que está no meio deles levará aos ombros as mobílias, e às escuras sairá; farão uma abertura na parede para as tirarem por ela; o seu rosto cobrirá, para que com os seus olhos não veja a terra.'),
('acf','ez',12,13,'Também estenderei a minha rede sobre ele, e será apanhado no meu laço; e o levarei à babilônia, à terra dos caldeus, e contudo não a verá, ainda que ali morrerá.'),
('acf','ez',12,14,'E a todos os ventos espalharei os que estiverem ao redor dele para seu socorro, e a todas as suas tropas; e desembainharei a espada atrás deles.'),
('acf','ez',12,15,'Assim saberão que eu sou o Senhor, quando eu os dispersar entre as nações e os espalhar pelas terras.'),
('acf','ez',12,16,'Mas deles deixarei ficar alguns poucos, escapos da espada, da fome, e da peste, para que contem todas as suas abominações entre as nações para onde forem; e saberão que eu sou o Senhor.'),
('acf','ez',12,17,'Então veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',12,18,'Filho do homem, o teu pão comerás com tremor, e a tua água beberás com estremecimento e com receio.'),
('acf','ez',12,19,'E dirás ao povo da terra: Assim diz o Senhor DEUS acerca dos habitantes de Jerusalém, na terra de Israel: O seu pão comerão com receio, e a sua água beberão com susto, pois a sua terra será despojada de sua abundância, por causa da violência de todos os que nela habitam.'),
('acf','ez',12,20,'E as cidades habitadas serão devastadas, e a terra se tornará em desolação; e sabereis que eu sou o Senhor.'),
('acf','ez',12,21,'E veio ainda a mim a palavra do Senhor, dizendo:'),
('acf','ez',12,22,'Filho do homem, que provérbio é este que vós tendes na terra de Israel, dizendo: Prolongar-se-ão os dias, e perecerá toda a visão?'),
('acf','ez',12,23,'Portanto, dize-lhes: Assim diz o Senhor DEUS: Farei cessar este provérbio, e já não se servirão mais dele em Israel; mas dize-lhes: Os dias estão próximos e o cumprimento de toda a visão.'),
('acf','ez',12,24,'Porque não haverá mais alguma visão vã, nem adivinhação lisonjeira, no meio da casa de Israel.'),
('acf','ez',12,25,'Porque eu, o SENHOR, falarei, e a palavra que eu falar se cumprirá; não será mais adiada; porque em vossos dias, ó casa rebelde, falarei uma palavra e a cumprirei, diz o Senhor DEUS.'),
('acf','ez',12,26,'Veio mais a mim a palavra do Senhor, dizendo:'),
('acf','ez',12,27,'Filho do homem, eis que os da casa de Israel dizem: A visão que este tem é para muitos dias, e ele profetiza de tempos que estão longe.'),
('acf','ez',12,28,'Portanto dize-lhes: Assim diz o Senhor DEUS: Não será mais adiada nenhuma das minhas palavras; e a palavra que falei se cumprirá, diz o Senhor DEUS.'),
('acf','ez',13,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',13,2,'Filho do homem, profetiza contra os profetas de Israel que profetizam, e dize aos que só profetizam de seu coração: Ouvi a palavra do Senhor;'),
('acf','ez',13,3,'Assim diz o Senhor DEUS: Ai dos profetas loucos, que seguem o seu próprio espírito e que nada viram!'),
('acf','ez',13,4,'Os teus profetas, ó Israel, são como raposas nos desertos.'),
('acf','ez',13,5,'Não subistes às brechas, nem reparastes o muro para a casa de Israel, para estardes firmes na peleja no dia do Senhor.'),
('acf','ez',13,6,'Viram vaidade e adivinhação mentirosa os que dizem: O Senhor disse; quando o Senhor não os enviou; e fazem que se espere o cumprimento da palavra.'),
('acf','ez',13,7,'Porventura não tivestes visão de vaidade, e não falastes adivinhação mentirosa, quando dissestes: O Senhor diz, sendo que eu tal não falei?'),
('acf','ez',13,8,'Portanto assim diz o Senhor DEUS: Como tendes falado vaidade, e visto a mentira, portanto eis que eu sou contra vós, diz o Senhor DEUS.'),
('acf','ez',13,9,'E a minha mão será contra os profetas que vêem vaidade e que adivinham mentira; não estarão na congregação do meu povo, nem nos registros da casa de Israel se escreverão, nem entrarão na terra de Israel; e sabereis que eu sou o Senhor DEUS.'),
('acf','ez',13,10,'Porquanto, sim, porquanto andam enganando o meu povo, dizendo: Paz, não havendo paz; e quando um edifica uma parede, eis que outros a cobrem com argamassa não temperada;'),
('acf','ez',13,11,'Dize aos que a cobrem com argamassa não temperada que ela cairá. Haverá uma grande pancada de chuva, e vós, ó pedras grandes de saraiva, caireis, e um vento tempestuoso a fenderá.'),
('acf','ez',13,12,'Ora, eis que, caindo a parede, não vos dirão: Onde está a argamassa com que a cobristes?'),
('acf','ez',13,13,'Portanto assim diz o Senhor DEUS: Fendê-la-ei no meu furor com vento tempestuoso, e chuva de inundar haverá na minha ira, e grandes pedras de saraiva na minha indignação, para a consumir.'),
('acf','ez',13,14,'E derrubarei a parede que cobristes com argamassa não temperada, e darei com ela por terra, e o seu fundamento se descobrirá; assim cairá, e perecereis no meio dela, e sabereis que eu sou o Senhor.'),
('acf','ez',13,15,'Assim cumprirei o meu furor contra a parede, e contra os que a cobriram com argamassa não temperada; e vos direi: Já não há parede, nem existem os que a cobriram;'),
('acf','ez',13,16,'Os profetas de Israel, que profetizam acerca de Jerusalém, e vêem para ela visão de paz, não havendo paz, diz o Senhor DEUS.'),
('acf','ez',13,17,'E tu, ó filho do homem, dirige o teu rosto contra as filhas do teu povo, que profetizam de seu coração, e profetiza contra elas,'),
('acf','ez',13,18,'E dize: Assim diz o Senhor DEUS: Ai das que cosem almofadas para todas as axilas, e que fazem véus para as cabeças de pessoas de toda a estatura, para caçarem as almas! Porventura caçareis as almas do meu povo, e as almas guardareis em vida para vós?'),
('acf','ez',13,19,'E vós me profanastes entre o meu povo, por punhados de cevada, e por pedaços de pão, para matardes as almas que não haviam de morrer, e para guardardes em vida as almas que não haviam de viver, mentindo assim ao meu povo que escuta a mentira?'),
('acf','ez',13,20,'Portanto assim diz o Senhor DEUS: Eis aí vou eu contra as vossas almofadas, com que vós ali caçais as almas fazendo-as voar, e as arrancarei de vossos braços, e soltarei as almas, sim, as almas que vós caçais fazendo-as voar.'),
('acf','ez',13,21,'E rasgarei os vossos véus, e livrarei o meu povo das vossas mãos, e nunca mais estará em vossas mãos para ser caçado; e sabereis que eu sou o Senhor.'),
('acf','ez',13,22,'Visto que entristecestes o coração do justo com falsidade, não o havendo eu entristecido; e fortalecestes as mãos do ímpio, para que não se desviasse do seu mau caminho, para conservá-lo em vida.'),
('acf','ez',13,23,'Portanto não vereis mais vaidade, nem mais fareis adivinhações; mas livrarei o meu povo da vossa mão, e sabereis que eu sou o Senhor.'),
('acf','ez',14,1,'E vieram a mim alguns homens dos anciãos de Israel, e se assentaram diante de mim.'),
('acf','ez',14,2,'Então veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',14,3,'Filho do homem, estes homens levantaram os seus ídolos nos seus corações, e o tropeço da sua maldade puseram diante da sua face; devo eu de alguma maneira ser interrogado por eles?'),
('acf','ez',14,4,'Portanto fala com eles, e dize-lhes: Assim diz o Senhor DEUS: Qualquer homem da casa de Israel, que levantar os seus ídolos no seu coração, e puser o tropeço da sua maldade diante da sua face, e vier ao profeta, eu, o SENHOR, vindo ele, lhe responderei conforme a multidão dos seus ídolos;'),
('acf','ez',14,5,'Para que eu possa apanhar a casa de Israel no seu coração, porquanto todos se apartaram de mim para seguirem os seus ídolos.'),
('acf','ez',14,6,'Portanto dize à casa de Israel: Assim diz o Senhor DEUS: Convertei-vos, e tornai-vos dos vossos ídolos; e desviai os vossos rostos de todas as vossas abominações;'),
('acf','ez',14,7,'Porque qualquer homem da casa de Israel, e dos estrangeiros que peregrinam em Israel, que se alienar de mim, e levantar os seus ídolos no seu coração, e puser o tropeço da sua maldade diante do seu rosto, e vier ao profeta, para me consultar por meio dele, eu, o Senhor, lhe responderei por mim mesmo.'),
('acf','ez',14,8,'E porei o meu rosto contra o tal homem, e o assolarei para que sirva de sinal e provérbio, e arrancá-lo-ei do meio do meu povo; e sabereis que eu sou o Senhor.'),
('acf','ez',14,9,'E se o profeta for enganado, e falar alguma coisa, eu, o Senhor, terei enganado esse profeta; e estenderei a minha mão contra ele, e destruí-lo-ei do meio do meu povo Israel.'),
('acf','ez',14,10,'E levarão sobre si o castigo da sua iniqüidade; o castigo do profeta será como o castigo de quem o consultar.'),
('acf','ez',14,11,'Para que a casa de Israel não se desvie mais de mim, nem mais se contamine com todas as suas transgressões; então eles serão o meu povo, e eu lhes serei o seu Deus, diz o Senhor DEUS.'),
('acf','ez',14,12,'Veio ainda a mim a palavra do Senhor, dizendo:'),
('acf','ez',14,13,'Filho do homem, quando uma terra pecar contra mim, se rebelando gravemente, então estenderei a minha mão contra ela, e lhe quebrarei o sustento do pão, e enviarei contra ela fome, e cortarei dela homens e animais.'),
('acf','ez',14,14,'Ainda que estivessem no meio dela estes três homens, Noé, Daniel e Jó, eles pela sua justiça livrariam apenas as suas almas, diz o Senhor DEUS.'),
('acf','ez',14,15,'Se eu fizer passar pela terra as feras selvagens, e elas a desfilharem de modo que fique desolada, e ninguém possa passar por ela por causa das feras;'),
('acf','ez',14,16,'E estes três homens estivessem no meio dela, vivo eu, diz o Senhor DEUS, que nem a filhos nem a filhas livrariam; eles só ficariam livres, e a terra seria assolada.'),
('acf','ez',14,17,'Ou, se eu trouxer a espada sobre aquela terra, e disser: Espada, passa pela terra; e eu cortar dela homens e animais;'),
('acf','ez',14,18,'Ainda que aqueles três homens estivessem nela, vivo eu, diz o Senhor DEUS, que nem filhos nem filhas livrariam, mas somente eles ficariam livres.'),
('acf','ez',14,19,'Ou, se eu enviar a peste sobre aquela terra, e derramar o meu furor sobre ela com sangue, para cortar dela homens e animais,'),
('acf','ez',14,20,'Ainda que Noé, Daniel e Jó estivessem no meio dela, vivo eu, diz o Senhor DEUS, que nem um filho nem uma filha eles livrariam, mas somente eles livrariam as suas próprias almas pela sua justiça.'),
('acf','ez',14,21,'Porque assim diz o Senhor DEUS: Quanto mais, se eu enviar os meus quatro maus juízos, a espada, a fome, as feras, e a peste, contra Jerusalém, para cortar dela homens e feras?'),
('acf','ez',14,22,'Mas eis que alguns fugitivos restarão nela, que serão levados para fora, assim filhos e filhas; eis que eles virão a vós, e vereis o seu caminho e os seus feitos; e ficareis consolados do mal que eu trouxe sobre Jerusalém, e de tudo o que trouxe sobre ela.'),
('acf','ez',14,23,'E sereis consolados, quando virdes o seu caminho e os seus feitos; e sabereis que não fiz sem razão tudo quanto nela tenho feito, diz o Senhor DEUS.'),
('acf','ez',15,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',15,2,'Filho do homem, que mais é a árvore da videira do que qualquer outra árvore, ou do que o sarmento que está entre as árvores do bosque?'),
('acf','ez',15,3,'Toma-se dela madeira para fazer alguma obra? Ou toma-se dela alguma estaca, para que se lhe pendure um vaso?'),
('acf','ez',15,4,'Eis que é lançado no fogo, para ser consumido; ambas as suas extremidades consome o fogo, e o meio dela fica também queimado; serviria porventura para alguma obra?'),
('acf','ez',15,5,'Ora, se estando inteiro, não servia para obra alguma, quanto menos sendo consumido pelo fogo, e, sendo queimado, se faria ainda obra dele?'),
('acf','ez',15,6,'Portanto, assim diz o Senhor DEUS: Como a árvore da videira entre as árvores do bosque, que tenho entregue ao fogo para que seja consumido, assim entregarei os habitantes de Jerusalém.'),
('acf','ez',15,7,'E porei a minha face contra eles; do fogo sairão, mas o fogo os consumirá; e sabereis que eu sou o Senhor, quando tiver posto a minha face contra eles.'),
('acf','ez',15,8,'E tornarei a terra em desolação, porquanto grandemente transgrediram, diz o Senhor DEUS.'),
('acf','ez',16,1,'E veio a mim outra vez a palavra do SENHOR, dizendo:'),
('acf','ez',16,2,'Filho do homem, faze conhecer a Jerusalém as suas abominações.'),
('acf','ez',16,3,'E dize: Assim diz o Senhor DEUS a Jerusalém: A tua origem e o teu nascimento procedem da terra dos cananeus. Teu pai era amorreu, e tua mãe hetéia.'),
('acf','ez',16,4,'E, quanto ao teu nascimento, no dia em que nasceste não te foi cortado o umbigo, nem foste lavada com água para te limpar; nem tampouco foste esfregada com sal, nem envolta em faixas.'),
('acf','ez',16,5,'Não se apiedou de ti olho algum, para te fazer alguma coisa disto, compadecendo-se de ti; antes foste lançada em pleno campo, pelo nojo da tua pessoa, no dia em que nasceste.'),
('acf','ez',16,6,'E, passando eu junto de ti, vi-te a revolver-te no teu sangue, e disse-te: Ainda que estejas no teu sangue, vive; sim, disse-te: Ainda que estejas no teu sangue, vive.'),
('acf','ez',16,7,'Eu te fiz multiplicar como o renovo do campo, e cresceste, e te engrandeceste, e chegaste à grande formosura; avultaram os seios, e cresceu o teu cabelo; mas estavas nua e descoberta.'),
('acf','ez',16,8,'E, passando eu junto de ti, vi-te, e eis que o teu tempo era tempo de amores; e estendi sobre ti a aba do meu manto, e cobri a tua nudez; e dei-te juramento, e entrei em aliança contigo, diz o Senhor DEUS, e tu ficaste sendo minha.'),
('acf','ez',16,9,'Então te lavei com água, e te enxuguei do teu sangue, e te ungi com óleo.'),
('acf','ez',16,10,'E te vesti com roupas bordadas, e te calcei com pele de texugo, e te cingi com linho fino, e te cobri de seda.'),
('acf','ez',16,11,'E te enfeitei com adornos, e te pus braceletes nas mãos e um colar ao redor do teu pescoço.'),
('acf','ez',16,12,'E te pus um pendente na testa, e brincos nas orelhas, e uma coroa de glória na cabeça.'),
('acf','ez',16,13,'E assim foste ornada de ouro e prata, e o teu vestido foi de linho fino, e de seda e de bordados; nutriste-te de flor de farinha, e mel e azeite; e foste formosa em extremo, e foste próspera, até chegares a realeza.'),
('acf','ez',16,14,'E correu de ti a tua fama entre os gentios, por causa da tua formosura, pois era perfeita, por causa da minha glória que eu pusera em ti, diz o Senhor DEUS.'),
('acf','ez',16,15,'Mas confiaste na tua formosura, e te corrompeste por causa da tua fama, e prostituías-te a todo o que passava, para seres dele.'),
('acf','ez',16,16,'E tomaste dos teus vestidos, e fizeste lugares altos pintados de diversas cores, e te prostituíste sobre eles, como nunca sucedera, nem sucederá.'),
('acf','ez',16,17,'E tomaste as tuas jóias de enfeite, que eu te dei do meu ouro e da minha prata, e fizeste imagens de homens, e te prostituíste com elas.'),
('acf','ez',16,18,'E tomaste os teus vestidos bordados, e as cobriste; e o meu azeite e o meu perfume puseste diante delas.'),
('acf','ez',16,19,'E o meu pão que te dei, a flor de farinha, e o azeite e o mel com que eu te sustentava, também puseste diante delas em cheiro suave; e assim foi, diz o Senhor DEUS.'),
('acf','ez',16,20,'Além disto, tomaste a teus filhos e tuas filhas, que me tinhas gerado, e os sacrificaste a elas, para serem consumidos; acaso é pequena a tua prostituição?'),
('acf','ez',16,21,'E mataste a meus filhos, e os entregaste a elas para os fazerem passar pelo fogo.'),
('acf','ez',16,22,'E em todas as tuas abominações, e nas tuas prostituições, não te lembraste dos dias da tua mocidade, quando tu estavas nua e descoberta, e revolvida no teu sangue.'),
('acf','ez',16,23,'E sucedeu, depois de toda a tua maldade (ai, ai de ti! diz o Senhor DEUS),'),
('acf','ez',16,24,'Que edificaste uma abóbada, e fizeste lugares altos em cada rua.'),
('acf','ez',16,25,'A cada canto do caminho edificaste o teu lugar alto, e fizeste abominável a tua formosura, e alargaste os teus pés a todo o que passava, e multiplicaste as tuas prostituições.'),
('acf','ez',16,26,'Também te prostituíste com os filhos do Egito, teus vizinhos grandes de carne, e multiplicaste a tua prostituição para me provocares à ira.'),
('acf','ez',16,27,'Por isso estendi a minha mão sobre ti, e diminuí a tua porção; e te entreguei à vontade das que te odeiam, das filhas dos filisteus, as quais se envergonhavam do teu caminho depravado.'),
('acf','ez',16,28,'Também te prostituíste com os filhos da Assíria, porquanto eras insaciável; e prostituindo-te com eles, nem ainda assim ficaste farta.'),
('acf','ez',16,29,'Antes multiplicaste as tuas prostituições na terra de Canaã até Caldéia, e nem ainda com isso te fartaste.'),
('acf','ez',16,30,'Quão fraco é o teu coração, diz o Senhor DEUS, fazendo tu todas estas coisas, obras de uma meretriz imperiosa!'),
('acf','ez',16,31,'Edificando tu a tua abóbada ao canto de cada caminho, e fazendo o teu lugar alto em cada rua! Nem foste como a meretriz, pois desprezaste a paga;'),
('acf','ez',16,32,'Foste como a mulher adúltera que, em lugar de seu marido, recebe os estranhos.'),
('acf','ez',16,33,'A todas as meretrizes dão paga, mas tu dás os teus presentes a todos os teus amantes; e lhes dás presentes, para que venham a ti de todas as partes, pelas tuas prostituições.'),
('acf','ez',16,34,'Assim que contigo sucede o contrário das outras mulheres nas tuas prostituições, pois ninguém te procura para prostituição; porque, dando tu a paga, e a ti não sendo dada a paga, fazes o contrário.'),
('acf','ez',16,35,'Portanto, ó meretriz, ouve a palavra do Senhor.'),
('acf','ez',16,36,'Assim diz o Senhor DEUS: Porquanto se derramou o teu dinheiro, e se descobriu a tua nudez nas tuas prostituições com os teus amantes, como também com todos os ídolos das tuas abominações, e do sangue de teus filhos que lhes deste;'),
('acf','ez',16,37,'Portanto, eis que ajuntarei a todos os teus amantes, com os quais te deleitaste, como também a todos os que amaste, com todos os que odiaste, e ajuntá-los-ei contra ti em redor, e descobrirei a tua nudez diante deles, para que vejam toda a tua nudez.'),
('acf','ez',16,38,'E julgar-te-ei como são julgadas as adúlteras e as que derramam sangue; e entregar-te-ei ao sangue de furor e de ciúme.'),
('acf','ez',16,39,'E entregar-te-ei nas mãos deles; e eles derrubarão a tua abóbada, e transtornarão os teus altos lugares, e te despirão os teus vestidos, e tomarão as tuas jóias de enfeite, e te deixarão nua e descoberta.'),
('acf','ez',16,40,'Então farão subir contra ti uma multidão, e te apedrejarão, e te traspassarão com as suas espadas.'),
('acf','ez',16,41,'E queimarão as tuas casas a fogo, e executarão juízos contra ti aos olhos de muitas mulheres; e te farei cessar de ser meretriz, e paga não darás mais.'),
('acf','ez',16,42,'Assim satisfarei em ti o meu furor, e os meus ciúmes se desviarão de ti, e me aquietarei, e nunca mais me indignarei.'),
('acf','ez',16,43,'Porquanto não te lembraste dos dias da tua mocidade, e me provocaste à ira com tudo isto, eis que também eu farei recair o teu caminho sobre a tua cabeça, diz o Senhor DEUS, e não mais farás tal perversidade sobre todas as tuas abominações.'),
('acf','ez',16,44,'Eis que todo o que usa de provérbios usará contra ti este provérbio, dizendo: Tal mãe, tal filha.'),
('acf','ez',16,45,'Tu és filha de tua mãe, que tinha nojo de seu marido e de seus filhos; e tu és irmã de tuas irmãs, que tinham nojo de seus maridos e de seus filhos; vossa mãe foi hetéia, e vosso pai amorreu.'),
('acf','ez',16,46,'E tua irmã, a maior, é Samaria, ela e suas filhas, a qual habita à tua esquerda; e a tua irmã menor, que habita à tua mão direita, é Sodoma e suas filhas.'),
('acf','ez',16,47,'Todavia não andaste nos seus caminhos, nem fizeste conforme as suas abominações; mas como se isto fora mui pouco, ainda te corrompeste mais do que elas, em todos os teus caminhos.'),
('acf','ez',16,48,'Vivo eu, diz o Senhor DEUS, que não fez Sodoma, tua irmã, nem ela, nem suas filhas, como fizeste tu e tuas filhas.'),
('acf','ez',16,49,'Eis que esta foi a iniqüidade de Sodoma, tua irmã: Soberba, fartura de pão, e abundância de ociosidade teve ela e suas filhas; mas nunca fortaleceu a mão do pobre e do necessitado.'),
('acf','ez',16,50,'E se ensoberbeceram, e fizeram abominações diante de mim; portanto, vendo eu isto as tirei dali.'),
('acf','ez',16,51,'Também Samaria não cometeu a metade de teus pecados; e multiplicaste as tuas abominações mais do que elas, e justificaste a tuas irmãs, com todas as tuas abominações que fizeste.'),
('acf','ez',16,52,'Tu, também, que julgaste a tuas irmãs, leva a tua vergonha pelos pecados, que cometeste, mais abomináveis do que elas; mais justas são do que tu; envergonha-te logo também, e leva a tua vergonha, pois justificaste a tuas irmãs.'),
('acf','ez',16,53,'Eu, pois, farei voltar os cativos delas; os cativos de Sodoma e suas filhas, e os cativos de Samaria e suas filhas, e os cativos do teu cativeiro dentre elas;'),
('acf','ez',16,54,'Para que leves a tua vergonha, e sejas envergonhada por tudo o que fizeste, dando-lhes tu consolação.'),
('acf','ez',16,55,'Quando tuas irmãs, Sodoma e suas filhas, tornarem ao seu primeiro estado, e também Samaria e suas filhas tornarem ao seu primeiro estado, também tu e tuas filhas tornareis ao vosso primeiro estado.'),
('acf','ez',16,56,'Nem mesmo Sodoma, tua irmã, foi mencionada pela tua boca, no dia da tua soberba,'),
('acf','ez',16,57,'Antes que se descobrisse a tua maldade, como no tempo do desprezo das filhas da Síria, e de todos os que estavam ao redor dela, as filhas dos filisteus, que te desprezavam em redor.'),
('acf','ez',16,58,'A tua perversidade e as tuas abominações tu levarás, diz o Senhor.'),
('acf','ez',16,59,'Porque assim diz o Senhor DEUS: Eu te farei como fizeste, que desprezaste o juramento, quebrando a aliança.'),
('acf','ez',16,60,'Contudo eu me lembrarei da minha aliança, que fiz contigo nos dias da tua mocidade; e estabelecerei contigo uma aliança eterna.'),
('acf','ez',16,61,'Então te lembrarás dos teus caminhos, e te confundirás, quando receberes tuas irmãs maiores do que tu, com as menores do que tu, porque tas darei por filhas, mas não pela tua aliança.'),
('acf','ez',16,62,'Porque eu estabelecerei a minha aliança contigo, e saberás que eu sou o Senhor;'),
('acf','ez',16,63,'Para que te lembres disso, e te envergonhes, e nunca mais abras a tua boca, por causa da tua vergonha, quando eu te expiar de tudo quanto fizeste, diz o Senhor DEUS.'),
('acf','ez',17,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',17,2,'Filho do homem, propõe um enigma, e profere uma parábola para com a casa de Israel.'),
('acf','ez',17,3,'E disse: Assim diz o Senhor DEUS: Uma grande águia, de grandes asas, de plumagem comprida, e cheia de penas de várias cores, veio ao Líbano e levou o mais alto ramo de um cedro.'),
('acf','ez',17,4,'E arrancou a ponta mais alta dos seus renovos, e a levou a uma terra de mercancia; numa cidade de mercadores a pôs.'),
('acf','ez',17,5,'Tomou da semente da terra, e a lançou num solo frutífero; tomando-a, colocou-a junto às muitas águas, plantando-a como salgueiro.'),
('acf','ez',17,6,'E brotou, e tornou-se numa videira muito larga, de pouca altura, virando-se para ela os seus ramos, porque as suas raízes estavam debaixo dela; e tornou-se numa videira, e produzia sarmentos, e brotava renovos.'),
('acf','ez',17,7,'E houve mais uma grande águia, de grandes asas, e cheia de penas; e eis que esta videira lançou para ela as suas raízes, e estendeu para ela os seus ramos, desde as covas do seu plantio, para que a regasse.'),
('acf','ez',17,8,'Num bom campo, junto a muitas águas, estava ela plantada, para produzir ramos, e para dar fruto, a fim de que fosse videira excelente.'),
('acf','ez',17,9,'Dize: Assim diz o Senhor DEUS: Porventura há de prosperar? Não lhe arrancará as suas raízes, e não cortará o seu fruto, para que se seque? Para que sequem todas as folhas de seus renovos, e isto não com grande força, nem muita gente, para arrancá-la pelas suas raízes.'),
('acf','ez',17,10,'Mas, estando plantada, prosperará? Porventura, tocando-lhe vento oriental, de todo não se secará? Nas covas do seu plantio se secará.'),
('acf','ez',17,11,'Então veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',17,12,'Dize agora à casa rebelde: Não sabeis o que significam estas coisas? Dize: Eis que veio o rei de babilônia a Jerusalém, e tomou o seu rei e os seus príncipes, e os levou consigo para babilônia.'),
('acf','ez',17,13,'E tomou um da descendência real, e fez aliança com ele, e o fez prestar juramento; e tomou consigo os poderosos da terra,'),
('acf','ez',17,14,'Para que o reino ficasse humilhado, e não se levantasse, embora, guardando a sua aliança, pudesse subsistir.'),
('acf','ez',17,15,'Mas rebelou-se contra ele, enviando os seus mensageiros ao Egito, para que se lhe mandassem cavalos e muita gente. Porventura prosperará ou escapará aquele que faz tais coisas, ou quebrará a aliança, e ainda escapará?'),
('acf','ez',17,16,'Vivo eu, diz o Senhor DEUS, que no lugar em que habita o rei que o fez reinar, cujo juramento desprezou, e cuja aliança quebrou, sim, com ele no meio de babilônia certamente morrerá.'),
('acf','ez',17,17,'E Faraó, nem com grande exército, nem com uma companhia numerosa, fará coisa alguma com ele em guerra, levantando trincheiras e edificando baluartes, para destruir muitas vidas.'),
('acf','ez',17,18,'Porque desprezou o juramento, quebrando a aliança; eis que ele tinha dado a sua mão; contudo fez todas estas coisas; não escapará.'),
('acf','ez',17,19,'Portanto, assim diz o Senhor DEUS: Vivo eu, que o meu juramento, que desprezou, e a minha aliança, que quebrou, isto farei recair sobre a sua cabeça.'),
('acf','ez',17,20,'E estenderei sobre ele a minha rede, e ficará preso no meu laço; e o levarei a babilônia, e ali entrarei em juízo com ele por causa da rebeldia que praticou contra mim.'),
('acf','ez',17,21,'E todos os seus fugitivos, com todas as suas tropas, cairão à espada, e os que restarem serão espalhados a todo o vento; e sabereis que eu, o Senhor, o disse.'),
('acf','ez',17,22,'Assim diz o Senhor DEUS: Também eu tomarei um broto do topo do cedro, e o plantarei; do principal dos seus renovos cortarei o mais tenro, e o plantarei sobre um monte alto e sublime.'),
('acf','ez',17,23,'No monte alto de Israel o plantarei, e produzirá ramos, e dará fruto, e se fará um cedro excelente; e habitarão debaixo dele aves de toda plumagem, à sombra dos seus ramos habitarão.'),
('acf','ez',17,24,'Assim saberão todas as árvores do campo que eu, o Senhor, abati a árvore alta, elevei a árvore baixa, sequei a árvore verde, e fiz reverdecer a árvore seca; eu, o Senhor, o disse, e o fiz.'),
('acf','ez',18,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',18,2,'Que pensais, vós, os que usais esta parábola sobre a terra de Israel, dizendo: Os pais comeram uvas verdes, e os dentes dos filhos se embotaram?'),
('acf','ez',18,3,'Vivo eu, diz o Senhor DEUS, que nunca mais direis esta parábola em Israel.'),
('acf','ez',18,4,'Eis que todas as almas são minhas; como o é a alma do pai, assim também a alma do filho é minha: a alma que pecar, essa morrerá.'),
('acf','ez',18,5,'Sendo, pois, o homem justo, e praticando juízo e justiça,'),
('acf','ez',18,6,'Não comendo sobre os montes, nem levantando os seus olhos para os ídolos da casa de Israel, nem contaminando a mulher do seu próximo, nem se chegando à mulher na sua separação,'),
('acf','ez',18,7,'Não oprimindo a ninguém, tornando ao devedor o seu penhor, não roubando, dando o seu pão ao faminto, e cobrindo ao nu com roupa,'),
('acf','ez',18,8,'Não dando o seu dinheiro à usura, e não recebendo demais, desviando a sua mão da injustiça, e fazendo verdadeiro juízo entre homem e homem;'),
('acf','ez',18,9,'Andando nos meus estatutos, e guardando os meus juízos, e procedendo segundo a verdade, o tal justo certamente viverá, diz o Senhor DEUS.'),
('acf','ez',18,10,'E se ele gerar um filho ladrão, derramador de sangue, que fizer a seu irmão qualquer destas coisas;'),
('acf','ez',18,11,'E não cumprir todos aqueles deveres, mas antes comer sobre os montes, e contaminar a mulher de seu próximo,'),
('acf','ez',18,12,'Oprimir ao pobre e necessitado, praticar roubos, não tornar o penhor, e levantar os seus olhos para os ídolos, e cometer abominação,'),
('acf','ez',18,13,'E emprestar com usura, e receber demais, porventura viverá? Não viverá. Todas estas abominações ele fez, certamente morrerá; o seu sangue será sobre ele.'),
('acf','ez',18,14,'E eis que também, se ele gerar um filho que veja todos os pecados que seu pai fez e, vendo-os, não cometer coisas semelhantes,'),
('acf','ez',18,15,'Não comer sobre os montes, e não levantar os seus olhos para os ídolos da casa de Israel, e não contaminar a mulher de seu próximo,'),
('acf','ez',18,16,'E não oprimir a ninguém, e não retiver o penhor, e não roubar, der o seu pão ao faminto, e cobrir ao nu com roupa,'),
('acf','ez',18,17,'Desviar do pobre a sua mão, não receber usura e juros, cumprir os meus juízos, e andar nos meus estatutos, o tal não morrerá pela iniqüidade de seu pai; certamente viverá.'),
('acf','ez',18,18,'Seu pai, porque praticou a extorsão, roubou os bens do irmão, e fez o que não era bom no meio de seu povo, eis que ele morrerá pela sua iniqüidade.'),
('acf','ez',18,19,'Mas dizeis: Por que não levará o filho a iniqüidade do pai? Porque o filho procedeu com retidão e justiça, e guardou todos os meus estatutos, e os praticou, por isso certamente viverá.'),
('acf','ez',18,20,'A alma que pecar, essa morrerá; o filho não levará a iniqüidade do pai, nem o pai levará a iniqüidade do filho. A justiça do justo ficará sobre ele e a impiedade do ímpio cairá sobre ele.'),
('acf','ez',18,21,'Mas se o ímpio se converter de todos os pecados que cometeu, e guardar todos os meus estatutos, e proceder com retidão e justiça, certamente viverá; não morrerá.'),
('acf','ez',18,22,'De todas as transgressões que cometeu não haverá lembrança contra ele; pela justiça que praticou viverá.'),
('acf','ez',18,23,'Desejaria eu, de qualquer maneira, a morte do ímpio? diz o Senhor DEUS; Não desejo antes que se converta dos seus caminhos, e viva?'),
('acf','ez',18,24,'Mas, desviando-se o justo da sua justiça, e cometendo a iniqüidade, fazendo conforme todas as abominações que faz o ímpio, porventura viverá? De todas as justiças que tiver feito não se fará memória; na sua transgressão com que transgrediu, e no seu pecado com que pecou, neles morrerá.'),
('acf','ez',18,25,'Dizeis, porém: O caminho do Senhor não é direito. Ouvi agora, ó casa de Israel: Porventura não é o meu caminho direito? Não são os vossos caminhos tortuosos?'),
('acf','ez',18,26,'Desviando-se o justo da sua justiça, e cometendo iniqüidade, morrerá por ela; na iniqüidade, que cometeu, morrerá.'),
('acf','ez',18,27,'Mas, convertendo-se o ímpio da impiedade que cometeu, e procedendo com retidão e justiça, conservará este a sua alma em vida.'),
('acf','ez',18,28,'Pois que reconsidera, e se converte de todas as suas transgressões que cometeu; certamente viverá, não morrerá.'),
('acf','ez',18,29,'Contudo, diz a casa de Israel: O caminho do Senhor não é direito. Porventura não são direitos os meus caminhos, ó casa de Israel? E não são tortuosos os vossos caminhos?'),
('acf','ez',18,30,'Portanto, eu vos julgarei, cada um conforme os seus caminhos, ó casa de Israel, diz o Senhor DEUS. Tornai-vos, e convertei-vos de todas as vossas transgressões, e a iniqüidade não vos servirá de tropeço.'),
('acf','ez',18,31,'Lançai de vós todas as vossas transgressões com que transgredistes, e fazei-vos um coração novo e um espírito novo; pois, por que razão morreríeis, ó casa de Israel?'),
('acf','ez',18,32,'Porque não tenho prazer na morte do que morre, diz o Senhor DEUS; convertei-vos, pois, e vivei.'),
('acf','ez',19,1,'E tu levanta uma lamentação sobre os príncipes de Israel,'),
('acf','ez',19,2,'E dize: Quem foi tua mãe? Uma leoa entre os leões a qual, deitada no meio dos leõezinhos, criou os seus filhotes.'),
('acf','ez',19,3,'E educou um dos seus filhotes, o qual veio a ser leãozinho e aprendeu a apanhar a presa, e devorou homens,'),
('acf','ez',19,4,'E, ouvindo falar dele as nações, foi apanhado na cova delas, e o trouxeram com cadeias à terra do Egito.'),
('acf','ez',19,5,'Vendo, pois, ela que havia esperado muito, e que a sua expectação era perdida, tomou outro dos seus filhotes, e fez dele um leãozinho.'),
('acf','ez',19,6,'Este, pois, andando continuamente no meio dos leões, veio a ser leãozinho, e aprendeu a apanhar a presa, e devorou homens.'),
('acf','ez',19,7,'E conheceu os seus palácios, e destruiu as suas cidades; e assolou-se a terra, e a sua plenitude, ao som do seu rugido.'),
('acf','ez',19,8,'Então se ajuntaram contra ele os povos das províncias ao redor, e estenderam sobre ele a rede, e foi apanhado na cova deles.'),
('acf','ez',19,9,'E com cadeias colocaram-no em uma jaula, e o levaram ao rei de babilônia; fizeram-no entrar nos lugares fortes, para que não se ouvisse mais a sua voz nos montes de Israel.'),
('acf','ez',19,10,'Tua mãe era como uma videira no teu sangue, plantada junto às águas; ela frutificou, e encheu-se de ramos, por causa das muitas águas.'),
('acf','ez',19,11,'E tinha varas fortes para cetros de dominadores, e elevou-se a sua estatura entre os espessos ramos, e foi vista na sua altura com a multidão dos seus ramos.'),
('acf','ez',19,12,'Mas foi arrancada com furor, foi lançada por terra, e o vento oriental secou o seu fruto; quebraram-se e secaram-se as suas fortes varas, o fogo as consumiu,'),
('acf','ez',19,13,'E agora está plantada no deserto, numa terra seca e sedenta.'),
('acf','ez',19,14,'E de uma vara dos seus ramos saiu fogo que consumiu o seu fruto de maneira que nela não há mais vara forte, cetro para dominar. Esta é a lamentação, e servirá de lamentação.'),
('acf','ez',20,1,'E aconteceu, no sétimo ano, no quinto mês, aos dez do mês, que vieram alguns dos anciãos de Israel, para consultarem o SENHOR; e assentaram-se diante de mim.'),
('acf','ez',20,2,'Então veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',20,3,'Filho do homem, fala aos anciãos de Israel, e dize-lhes: Assim diz o Senhor DEUS: Viestes consultar-me? Vivo eu, que não me deixarei ser consultado por vós, diz o Senhor DEUS.'),
('acf','ez',20,4,'Porventura tu os julgarias, julgarias tu, ó filho do homem? Notifica-lhes as abominações de seus pais;'),
('acf','ez',20,5,'E dize-lhes: Assim diz o Senhor DEUS: No dia em que escolhi a Israel, levantei a minha mão para a descendência da casa de Jacó, e me dei a conhecer a eles na terra do Egito, e levantei a minha mão para eles, dizendo: Eu sou o SENHOR vosso Deus;'),
('acf','ez',20,6,'Naquele dia levantei a minha mão para eles, para os tirar da terra do Egito, para uma terra que já tinha previsto para eles, a qual mana leite e mel, e é a glória de todas as terras.'),
('acf','ez',20,7,'Então lhes disse: Cada um lance de si as abominações dos seus olhos, e não vos contamineis com os ídolos do Egito; eu sou o Senhor vosso Deus.'),
('acf','ez',20,8,'Mas rebelaram-se contra mim, e não me quiseram ouvir; ninguém lançava de si as abominações dos seus olhos, nem deixava os ídolos do Egito; então eu disse que derramaria sobre eles o meu furor, para cumprir a minha ira contra eles no meio da terra do Egito.'),
('acf','ez',20,9,'O que fiz, porém, foi por amor do meu nome, para que não fosse profanado diante dos olhos dos gentios, no meio dos quais estavam, a cujos olhos eu me dei a conhecer a eles, para os tirar da terra do Egito.'),
('acf','ez',20,10,'E os tirei da terra do Egito, e os levei ao deserto.'),
('acf','ez',20,11,'E dei-lhes os meus estatutos e lhes mostrei os meus juízos, os quais, cumprindo-os o homem, viverá por eles.'),
('acf','ez',20,12,'E também lhes dei os meus sábados, para que servissem de sinal entre mim e eles; para que soubessem que eu sou o Senhor que os santifica.'),
('acf','ez',20,13,'Mas a casa de Israel se rebelou contra mim no deserto, não andando nos meus estatutos, e rejeitando os meus juízos, os quais, cumprindo-os, o homem viverá por eles; e profanaram grandemente os meus sábados; e eu disse que derramaria sobre eles o meu furor no deserto, para os consumir.'),
('acf','ez',20,14,'O que fiz, porém, foi por amor do meu nome, para que não fosse profanado diante dos olhos dos gentios perante a vista dos quais os fiz sair.'),
('acf','ez',20,15,'E, contudo, eu levantei a minha mão para eles no deserto, para não os deixar entrar na terra que lhes tinha dado, a qual mana leite e mel, e é a glória de todas as terras;'),
('acf','ez',20,16,'Porque rejeitaram os meus juízos, e não andaram nos meus estatutos, e profanaram os meus sábados; porque o seu coração andava após os seus ídolos.'),
('acf','ez',20,17,'Não obstante o meu olho lhes perdoou, e eu não os destruí nem os consumi no deserto.'),
('acf','ez',20,18,'Mas disse eu a seus filhos no deserto: Não andeis nos estatutos de vossos pais, nem guardeis os seus juízos, nem vos contamineis com os seus ídolos.'),
('acf','ez',20,19,'Eu sou o Senhor vosso Deus; andai nos meus estatutos, e guardai os meus juízos, e executai-os.'),
('acf','ez',20,20,'E santificai os meus sábados, e servirão de sinal entre mim e vós, para que saibais que eu sou o Senhor vosso Deus.'),
('acf','ez',20,21,'Mas também os filhos se rebelaram contra mim, e não andaram nos meus estatutos, nem guardaram os meus juízos para os fazer, os quais, cumprindo-os, o homem viverá por eles; eles profanaram os meus sábados; por isso eu disse que derramaria sobre eles o meu furor, para cumprir contra eles a minha ira no deserto.'),
('acf','ez',20,22,'Mas contive a minha mão, e o fiz por amor do meu nome, para que não fosse profanado perante os olhos dos gentios, à vista dos quais os fiz sair.'),
('acf','ez',20,23,'Também levantei a minha mão para eles no deserto, para os espalhar entre os gentios, e os derramar pelas terras,'),
('acf','ez',20,24,'Porque não executaram os meus juízos, e rejeitaram os meus estatutos, e profanaram os meus sábados, e os seus olhos iam após os ídolos de seus pais.'),
('acf','ez',20,25,'Por isso também lhes dei estatutos que não eram bons, juízos pelos quais não haviam de viver;'),
('acf','ez',20,26,'E os contaminei em seus próprios dons, nos quais faziam passar pelo fogo tudo o que abre a madre; para assolá-los para que soubessem que eu sou o Senhor.'),
('acf','ez',20,27,'Portanto fala à casa de Israel, ó filho do homem, e dize-lhe: Assim diz o Senhor DEUS: Ainda até nisto me blasfemaram vossos pais, e que procederam traiçoeiramente contra mim.'),
('acf','ez',20,28,'Porque, havendo-os eu introduzido na terra sobre a qual eu levantara a minha mão, para lha dar, então olharam para todo o outeiro alto, e para toda a árvore frondosa, e ofereceram ali os seus sacrifícios e apresentaram ali a provocação das suas ofertas; puseram ali os seus cheiros suaves, e ali derramaram as suas libações.'),
('acf','ez',20,29,'E eu lhes disse: Que alto é este, aonde vós ides? E seu nome tem sido Bamá até o dia de hoje.'),
('acf','ez',20,30,'Portanto dize à casa de Israel: Assim diz o Senhor DEUS: Contaminai-vos a vós mesmos a maneira de vossos pais? E vos prostituístes com as suas abominações?'),
('acf','ez',20,31,'E, quando ofereceis os vossos dons, e fazeis passar os vossos filhos pelo fogo, não é certo que estais contaminados com todos os vossos ídolos, até este dia? E vós me consultaríeis, ó casa de Israel? Vivo eu, diz o Senhor DEUS, que vós não me consultareis.'),
('acf','ez',20,32,'E o que veio à vossa mente de modo algum sucederá, quando dizeis: Seremos como os gentios, como as outras famílias da terra, servindo ao madeiro e à pedra.'),
('acf','ez',20,33,'Vivo eu, diz o Senhor DEUS, que com mão forte, e com braço estendido, e com indignação derramada, hei de reinar sobre vós.'),
('acf','ez',20,34,'E vos tirarei dentre os povos, e vos congregarei das terras nas quais andais espalhados, com mão forte, e com braço estendido, e com indignação derramada.'),
('acf','ez',20,35,'E vos levarei ao deserto dos povos; e ali face a face entrarei em juízo convosco;'),
('acf','ez',20,36,'Como entrei em juízo com vossos pais, no deserto da terra do Egito, assim entrarei em juízo convosco, diz o Senhor DEUS.'),
('acf','ez',20,37,'Também vos farei passar debaixo da vara, e vos farei entrar no vínculo da aliança.'),
('acf','ez',20,38,'E separarei dentre vós os rebeldes, e os que transgrediram contra mim; da terra das suas peregrinações os tirarei, mas à terra de Israel não voltarão; e sabereis que eu sou o Senhor.'),
('acf','ez',20,39,'Quanto a vós, ó casa de Israel, assim diz o Senhor DEUS; Ide, sirva cada um os seus ídolos, pois que a mim não me quereis ouvir; mas não profaneis mais o meu santo nome com as vossas dádivas e com os vossos ídolos.'),
('acf','ez',20,40,'Porque no meu santo monte, no monte alto de Israel, diz o Senhor DEUS, ali me servirá toda a casa de Israel, toda ela naquela terra; ali me deleitarei neles, e ali requererei as vossas ofertas alçadas, e as primícias das vossas oblações, com todas as vossas coisas santas;'),
('acf','ez',20,41,'Com cheiro suave me deleitarei em vós, quando eu vos tirar dentre os povos e vos congregar das terras em que andais espalhados; e serei santificado em vós perante os olhos dos gentios.'),
('acf','ez',20,42,'E sabereis que eu sou o Senhor, quando eu vos introduzir na terra de Israel, terra pela qual levantei a minha mão para dá-la a vossos pais.'),
('acf','ez',20,43,'E ali vos lembrareis de vossos caminhos, e de todos os vossos atos com que vos contaminastes, e tereis nojo de vós mesmos, por causa de todas as vossas maldades que tendes cometido.'),
('acf','ez',20,44,'E sabereis que eu sou o SENHOR, quando eu proceder para convosco por amor do meu nome; não conforme os vossos maus caminhos, nem conforme os vossos atos corruptos, ó casa de Israel, disse o Senhor DEUS.'),
('acf','ez',20,45,'E veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',20,46,'Filho do homem, dirige o teu rosto para o caminho do sul, e derrama as tuas palavras contra o sul, e profetiza contra o bosque do campo do sul.'),
('acf','ez',20,47,'E dize ao bosque do sul: Ouve a palavra do SENHOR: Assim diz o Senhor DEUS: Eis que acenderei em ti um fogo que em ti consumirá toda a árvore verde e toda a árvore seca; não se apagará a chama flamejante, antes com ela se queimarão todos os rostos, desde o sul até ao norte.'),
('acf','ez',20,48,'E verá toda a carne que eu, o Senhor, o acendi; não se apagará.'),
('acf','ez',20,49,'Então disse eu: Ah! Senhor DEUS! Eles dizem de mim: Não é este um proferidor de parábolas?'),
('acf','ez',21,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',21,2,'Filho do homem, dirige o teu rosto contra Jerusalém, e derrama as tuas palavras sobre os santuários, e profetiza sobre a terra de Israel.'),
('acf','ez',21,3,'E dize à terra de Israel: Assim diz o Senhor: Eis que sou contra ti, e tirarei a minha espada da bainha, e exterminarei do meio de ti o justo e o ímpio.'),
('acf','ez',21,4,'E, por isso que hei de exterminar do meio de ti o justo e o ímpio, a minha espada sairá da sua bainha contra toda a carne, desde o sul até o norte.'),
('acf','ez',21,5,'E saberá toda a carne que eu, o Senhor, tirei a minha espada da bainha; nunca mais voltará a ela.'),
('acf','ez',21,6,'Tu, porém, ó filho do homem, suspira; suspira aos olhos deles, com quebrantamento dos teus lombos e com amargura.'),
('acf','ez',21,7,'E será que, quando eles te disserem: Por que suspiras tu? Dirás: Por causa das novas, porque vêm; e todo o coração desmaiará, e todas as mãos se enfraquecerão, e todo o espírito se angustiará, e todos os joelhos se desfarão em águas; eis que vêm, e se cumprirão, diz o Senhor DEUS.'),
('acf','ez',21,8,'E veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',21,9,'Filho do homem, profetiza, e dize: Assim diz o Senhor: dize: A espada, a espada está afiada e polida.'),
('acf','ez',21,10,'Para grande matança está afiada, para reluzir está polida. Alegrar-nos-emos pois? A vara de meu filho é que despreza todo o madeiro.'),
('acf','ez',21,11,'E foi dada a polir, para ser manejada; esta espada está afiada, e está polida, para ser posta na mão do matador.'),
('acf','ez',21,12,'Grita e geme, ó filho do homem, porque ela será contra o meu povo, contra todos os príncipes de Israel. Estes, juntamente com o meu povo, estão espantados com a espada; bate, pois, na tua coxa.'),
('acf','ez',21,13,'Pois se faz uma prova; e que seria se a espada desprezasse mesmo a vara? Ela não seria mais, diz o Senhor DEUS.'),
('acf','ez',21,14,'Tu, pois, ó filho do homem, profetiza e bate com as mãos uma na outra; e dobre-se a espada até a terceira vez, a espada dos mortos; ela é a espada para a grande matança, que os traspassará até o seu interior.'),
('acf','ez',21,15,'Para que desmaie o coração, e se multipliquem as destruições, contra todas as suas portas, pus a ponta da espada, a que foi feita para reluzir, e está preparada para a matança!'),
('acf','ez',21,16,'Ó espada, une-te, vira-te para a direita; prepara-te, vira-te para a esquerda, para onde quer que o teu rosto se dirigir.'),
('acf','ez',21,17,'E também eu baterei com as minhas mãos uma na outra, e farei descansar a minha indignação; eu, o Senhor, o disse.'),
('acf','ez',21,18,'E veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',21,19,'Tu, pois, ó filho do homem, propõe dois caminhos, por onde venha a espada do rei de babilônia. Ambos procederão de uma mesma terra, e escolhe um lugar; escolhe-o no cimo do caminho da cidade.'),
('acf','ez',21,20,'Um caminho proporás, por onde virá a espada contra Rabá dos filhos de Amom, e contra Judá, em Jerusalém, a fortificada.'),
('acf','ez',21,21,'Porque o rei de babilônia parará na encruzilhada, no cimo dos dois caminhos, para fazer adivinhações; aguçará as suas flechas, consultará as imagens, atentará para o fígado.'),
('acf','ez',21,22,'« sua direita estará a adivinhação sobre Jerusalém, para ordenar aos capitàes, para abrirem a boca, ordenando a matança, para levantarem a voz com júbilo, para pôrem os aríetes contra as portas, para levantarem trincheiras, para edificarem baluartes.'),
('acf','ez',21,23,'Isto será como adivinhação vã, aos olhos daqueles que lhes fizeram juramentos; mas ele se lembrará da iniqüidade, para que sejam apanhados.'),
('acf','ez',21,24,'Portanto assim diz o Senhor DEUS: Visto que me fazeis lembrar da vossa iniqüidade, descobrindo-se as vossas transgressões, aparecendo os vossos pecados em todos os vossos atos; visto que viestes em memória, sereis apanhados com a mão.'),
('acf','ez',21,25,'E tu, ó profano e ímpio príncipe de Israel, cujo dia virá no tempo da extrema iniqüidade,'),
('acf','ez',21,26,'Assim diz o Senhor DEUS: Tira o diadema, e remove a coroa; esta não será a mesma; exalta ao humilde, e humilha ao soberbo.'),
('acf','ez',21,27,'Ao revés, ao revés, ao revés porei aquela coroa, e ela não mais será, até que venha aquele a quem pertence de direito; a ele a darei.'),
('acf','ez',21,28,'E tu, ó filho do homem, profetiza, e dize: Assim diz o Senhor DEUS acerca dos filhos de Amom, e acerca do seu opróbrio; dize pois: A espada, a espada está desembainhada, polida para a matança, para consumir, por estar reluzente;'),
('acf','ez',21,29,'Entretanto te profetizam vaidade, te adivinham mentira, para te porem no pescoço dos ímpios, daqueles que estão mortos, cujo dia veio no tempo da iniqüidade final.'),
('acf','ez',21,30,'Torne a tua espada à sua bainha. No lugar em que foste criado, na terra do teu nascimento, eu te julgarei.'),
('acf','ez',21,31,'E derramarei sobre ti a minha indignação, assoprarei contra ti o fogo do meu furor, entregar-te-ei nas mãos dos homens brutais, inventores de destruição.'),
('acf','ez',21,32,'Ao fogo servirás para ser consumido; o teu sangue estará no meio da terra; já não serás mais lembrado, porque eu, o Senhor, o disse.'),
('acf','ez',22,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',22,2,'Tu, pois, ó filho do homem, porventura julgarás, julgarás a cidade sanguinária? Faze-lhe conhecer, pois, todas as suas abominações.'),
('acf','ez',22,3,'E dize: Assim diz o Senhor DEUS: Ai da cidade que derrama o sangue no meio de si para que venha o seu tempo! Que faz ídolos contra si mesma, para se contaminar!'),
('acf','ez',22,4,'Pelo teu sangue que derramaste te fizeste culpada, e pelos teus ídolos que fabricaste te contaminaste, e fizeste aproximarem-se os teus dias, e tem chegado o fim dos teus anos; por isso eu te fiz o opróbrio das nações e o escárnio de todas as terras.'),
('acf','ez',22,5,'As que estão perto de ti e as que estão longe escarnecerão de ti, infamada, cheia de inquietação.'),
('acf','ez',22,6,'Eis que os príncipes de Israel, cada um conforme o seu poder, estavam em ti para derramarem sangue.'),
('acf','ez',22,7,'Ao pai e à mãe desprezaram em ti; para com o estrangeiro usaram de opressão no meio de ti; ao órfão e à viúva oprimiram em ti.'),
('acf','ez',22,8,'As minhas coisas santas desprezaste, e os meus sábados profanaste.'),
('acf','ez',22,9,'Homens caluniadores se acharam em ti, para derramarem sangue; e em ti sobre os montes comeram; perversidade cometeram no meio de ti.'),
('acf','ez',22,10,'A vergonha do pai descobriram em ti; a que estava imunda, na sua separação, humilharam no meio de ti.'),
('acf','ez',22,11,'Um cometeu abominação com a mulher do seu próximo, outro contaminou abominavelmente a sua nora, e outro humilhou no meio de ti a sua irmã, filha de seu pai.'),
('acf','ez',22,12,'Presentes receberam no meio de ti para derramarem sangue; usura e juros ilícitos tomaste, e usaste de avareza com o teu próximo, oprimindo-o; mas de mim te esqueceste, diz o Senhor DEUS.'),
('acf','ez',22,13,'E eis que bati as mãos contra a avareza que cometeste, e por causa do sangue que houve no meio de ti.'),
('acf','ez',22,14,'Porventura estará firme o teu coração? Porventura estarão fortes as tuas mãos, nos dias em que eu tratarei contigo? Eu, o Senhor, o disse, e o farei.'),
('acf','ez',22,15,'E espalhar-te-ei entre as nações, e dispersar-te-ei pelas terras, e porei termo à tua imundícia.'),
('acf','ez',22,16,'E tu serás profanada em ti mesma aos olhos dos gentios, e saberás que eu sou o Senhor.'),
('acf','ez',22,17,'E veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',22,18,'Filho do homem, a casa de Israel se tornou para mim em escórias; todos eles são bronze, e estanho, e ferro, e chumbo no meio do forno; em escórias de prata se tornaram.'),
('acf','ez',22,19,'Portanto assim diz o Senhor DEUS: Pois que todos vós vos tornastes em escórias, por isso eis que eu vos ajuntarei no meio de Jerusalém.'),
('acf','ez',22,20,'Como se ajuntam a prata, e o bronze, e o ferro, e o chumbo, e o estanho, no meio do forno, para assoprar o fogo sobre eles, a fim de se fundirem, assim vos ajuntarei na minha ira e no meu furor, e ali vos deixarei e fundirei.'),
('acf','ez',22,21,'E congregar-vos-ei, e assoprarei sobre vós o fogo do meu furor; e sereis fundidos no meio dela.'),
('acf','ez',22,22,'Como se funde a prata no meio do forno, assim sereis fundidos no meio dela; e sabereis que eu, o Senhor, derramei o meu furor sobre vós.'),
('acf','ez',22,23,'E veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',22,24,'Filho do homem, dize-lhe: Tu és uma terra que não está purificada; e que não tem chuva no dia da indignação.'),
('acf','ez',22,25,'Conspiração dos seus profetas há no meio dela, como um leão que ruge, que arrebata a presa; eles devoram as almas; tomam tesouros e coisas preciosas, multiplicam as suas viúvas no meio dela.'),
('acf','ez',22,26,'Os seus sacerdotes violentam a minha lei, e profanam as minhas coisas santas; não fazem diferença entre o santo e o profano, nem discernem o impuro do puro; e de meus sábados escondem os seus olhos, e assim sou profanado no meio deles.'),
('acf','ez',22,27,'Os seus príncipes no meio dela são como lobos que arrebatam a presa, para derramarem sangue, para destruírem as almas, para seguirem a avareza.'),
('acf','ez',22,28,'E os seus profetas têm feito para eles cobertura com argamassa não temperada, profetizando vaidade, adivinhando-lhes mentira, dizendo: Assim diz o Senhor DEUS; sem que o SENHOR tivesse falado.'),
('acf','ez',22,29,'Ao povo da terra oprimem gravemente, e andam roubando, e fazendo violência ao pobre e necessitado, e ao estrangeiro oprimem sem razão.'),
('acf','ez',22,30,'E busquei dentre eles um homem que estivesse tapando o muro, e estivesse na brecha perante mim por esta terra, para que eu não a destruísse; porém a ninguém achei.'),
('acf','ez',22,31,'Por isso eu derramei sobre eles a minha indignação; com o fogo do meu furor os consumi; fiz que o seu caminho recaísse sobre a sua cabeça, diz o Senhor DEUS.'),
('acf','ez',23,1,'Veio mais a mim a palavra do SENHOR, dizendo:'),
('acf','ez',23,2,'Filho do homem, houve duas mulheres, filhas de uma mesma mãe.'),
('acf','ez',23,3,'Estas se prostituíram no Egito; prostituíram-se na sua mocidade; ali foram apertados os seus seios, e ali foram apalpados os seios da sua virgindade.'),
('acf','ez',23,4,'E os seus nomes eram: Aolá, a mais velha, e Aolibá, sua irmã; e foram minhas, e tiveram filhos e filhas; e, quanto aos seus nomes, Samaria é Aolá, e Jerusalém é Aolibá.'),
('acf','ez',23,5,'E prostituiu-se Aolá, sendo minha; e enamorou-se dos seus amantes, dos assírios, seus vizinhos,'),
('acf','ez',23,6,'Vestidos de azul, capitàes e magistrados, todos jovens cobiçáveis, cavaleiros montados a cavalo.'),
('acf','ez',23,7,'Assim cometeu ela as suas devassidões com eles, que eram todos a flor dos filhos da Assíria, e com todos os de quem se enamorava; com todos os seus ídolos se contaminou.'),
('acf','ez',23,8,'E as suas prostituições, que trouxe do Egito, não as deixou; porque com ela se deitaram na sua mocidade, e eles apalparam os seios da sua virgindade, e derramaram sobre ela a sua impudicícia.'),
('acf','ez',23,9,'Portanto a entreguei na mão dos seus amantes, na mão dos filhos da Assíria, de quem se enamorara.'),
('acf','ez',23,10,'Estes descobriram a sua vergonha, levaram seus filhos e suas filhas, mas a ela mataram à espada; e tornou-se falada entre as mulheres, e sobre ela executaram os juízos.'),
('acf','ez',23,11,'Vendo isto sua irmã Aolibá, corrompeu o seu imoderado amor mais do que ela, e as suas devassidões foram mais do que as de sua irmã.'),
('acf','ez',23,12,'Enamorou-se dos filhos da Assíria, dos capitàes e dos magistrados seus vizinhos, vestidos com primor, cavaleiros que andam montados em cavalos, todos jovens cobiçáveis.'),
('acf','ez',23,13,'E vi que se tinha contaminado; o caminho de ambas era o mesmo.'),
('acf','ez',23,14,'E aumentou as suas impudicícias, porque viu homens pintados na parede, imagens dos caldeus, pintadas de vermelho;'),
('acf','ez',23,15,'Cingidos de cinto nos seus lombos, e tiaras largas e tingidas nas suas cabeças, todos com parecer de príncipes, semelhantes aos filhos de babilônia em Caldéia, terra do seu nascimento.'),
('acf','ez',23,16,'E enamorou-se deles, ao lançar sobre eles os seus olhos; e lhes mandou mensageiros à Caldéia.'),
('acf','ez',23,17,'Então vieram a ela os filhos de babilônia para o leito dos amores, e a contaminaram com as suas impudicícias; e ela se contaminou com eles; então a sua alma apartou-se deles.'),
('acf','ez',23,18,'Assim pôs a descoberto as suas devassidões, e descobriu a sua vergonha; então a minha alma se apartou dela, como já tinha se apartado a minha alma de sua irmã.'),
('acf','ez',23,19,'Todavia ela multiplicou as suas prostituições, lembrando-se dos dias da sua mocidade, em que se prostituíra na terra do Egito.'),
('acf','ez',23,20,'E enamorou-se dos seus amantes, cuja carne é como a de jumentos, e cujo fluxo é como o de cavalos.'),
('acf','ez',23,21,'Assim trouxeste à memória a perversidade da tua mocidade, quando os do Egito apalpavam os teus seios, por causa dos peitos da tua mocidade.'),
('acf','ez',23,22,'Por isso, ó Aolibá, assim diz o Senhor DEUS: Eis que eu suscitarei contra ti os teus amantes, dos quais se tinha apartado a tua alma, e os trarei contra ti de toda a parte em derredor.'),
('acf','ez',23,23,'Os filhos de Babilônia, e todos os caldeus de Pecode, e de Soa, e de Coa, e todos os filhos da Assíria com eles, jovens cobiçáveis, capitàes e magistrados todos eles, grandes e afamados senhores, todos eles montados a cavalo.'),
('acf','ez',23,24,'E virão contra ti com carros, carretas e rodas, e com multidão de povos; e se colocarão contra ti em redor com paveses, e escudos e capacetes; e porei diante deles o juízo, e julgar-te-ão segundo os seus juízos.'),
('acf','ez',23,25,'E porei contra ti o meu zelo, e usarão de indignação contigo. Tirar-te-ão o nariz e as orelhas, e o que restar cairá à espada. Eles tomarão teus filhos e tuas filhas, e o que ficar por último em ti será consumido pelo fogo.'),
('acf','ez',23,26,'Também te despirão as tuas vestes, e te tomarão as tuas belas jóias.'),
('acf','ez',23,27,'Assim farei cessar em ti a tua perversidade e a tua prostituição trazida da terra do Egito; e não levantarás os teus olhos para eles, nem te lembrarás nunca mais do Egito.'),
('acf','ez',23,28,'Porque assim diz o Senhor DEUS: Eis que eu te entregarei na mão dos que odeias, na mão daqueles de quem tem se apartado a tua alma.'),
('acf','ez',23,29,'E eles te tratarão com ódio, e levarão todo o fruto do teu trabalho, e te deixarão nua e despida; e descobrir-se-á a vergonha da tua prostituição, e a tua perversidade, e as tuas devassidões.'),
('acf','ez',23,30,'Estas coisas se te farão, porque te prostituíste após os gentios, e te contaminaste com os seus ídolos.'),
('acf','ez',23,31,'No caminho de tua irmã andaste; por isso entregarei o seu cálice na tua mão.'),
('acf','ez',23,32,'Assim diz o Senhor DEUS: Beberás o cálice de tua irmã, fundo e largo; servirás de riso e escárnio; pois nele cabe muito.'),
('acf','ez',23,33,'De embriaguez e de dor te encherás; o cálice de tua irmã Samaria é cálice de espanto e de assolação.'),
('acf','ez',23,34,'Bebê-lo-ás, pois, e esgotá-lo-ás, e os seus cacos roerás, e os teus seios arrancarás; porque eu o falei, diz o Senhor DEUS.'),
('acf','ez',23,35,'Portanto, assim diz o Senhor DEUS: Como te esqueceste de mim, e me lançaste para trás das tuas costas, também carregarás com a tua perversidade e as tuas devassidões.'),
('acf','ez',23,36,'Disse-me ainda o Senhor: Filho do homem, porventura julgarás tu a Aolá e a Aolibá? Mostra-lhes, pois, as suas abominações.'),
('acf','ez',23,37,'Porque adulteraram, e sangue se acha nas suas mãos, e com os seus ídolos adulteraram, e até os seus filhos, que de mim geraram, fizeram passar pelo fogo, para os consumir.'),
('acf','ez',23,38,'E ainda isto me fizeram: contaminaram o meu santuário no mesmo dia, e profanaram os meus sábados.'),
('acf','ez',23,39,'Porquanto, havendo sacrificado seus filhos aos seus ídolos, vinham ao meu santuário no mesmo dia para o profanarem; e eis que assim fizeram no meio da minha casa.'),
('acf','ez',23,40,'E, mais ainda, mandaram vir alguns homens, de longe, aos quais fora enviado um mensageiro, e eis que vieram. Por amor deles te lavaste, coloriste os teus olhos, e te ornaste de enfeites.'),
('acf','ez',23,41,'E te assentaste sobre um leito de honra, diante do qual estava uma mesa preparada; e puseste sobre ela o meu incenso e o meu azeite.'),
('acf','ez',23,42,'Com ela se ouvia a voz de uma multidão satisfeita; com homens de classe baixa foram trazidos beberrões do deserto; e puseram braceletes nas mãos das mulheres e coroas de esplendor nas suas cabeças.'),
('acf','ez',23,43,'Então disse à envelhecida em adultérios: Agora deveras se prostituirão com ela, e ela com eles?'),
('acf','ez',23,44,'E entraram a ela, como quem entra a uma prostituta; assim entraram a Aolá e a Aolibá, mulheres infames.'),
('acf','ez',23,45,'De maneira que homens justos as julgarão como se julgam as adúlteras, e como se julgam as que derramam sangue; porque são adúlteras, e sangue há nas suas mãos.'),
('acf','ez',23,46,'Porque assim diz o Senhor DEUS: Farei subir contra elas uma multidão, e as entregarei ao desterro e ao saque.'),
('acf','ez',23,47,'E a multidão as apedrejará, e as golpeará com as suas espadas; eles a seus filhos e a suas filhas matarão, e as suas casas queimarão a fogo.'),
('acf','ez',23,48,'Assim farei cessar a perversidade da terra, para que se escarmentem todas as mulheres, e não façam conforme a vossa perversidade;'),
('acf','ez',23,49,'O castigo da vossa perversidade eles farão recair sobre vós, e levareis os pecados dos vossos ídolos; e sabereis que eu sou o Senhor DEUS.'),
('acf','ez',24,1,'E veio a mim a palavra do SENHOR, no nono ano, no décimo mês, aos dez do mês, dizendo:'),
('acf','ez',24,2,'Filho do homem, escreve o nome deste dia, deste mesmo dia; porque o rei de babilônia se pôs contra Jerusalém neste mesmo dia.'),
('acf','ez',24,3,'E fala por parábola à casa rebelde, e dize-lhes: Assim diz o Senhor DEUS: Põe a panela ao lume, põe-na, e deita-lhe também água dentro.'),
('acf','ez',24,4,'Ajunta nela pedaços, todos os bons pedaços, as coxas e as espáduas; enche-a de ossos escolhidos.'),
('acf','ez',24,5,'Escolhe o melhor do rebanho, e queima também os ossos debaixo dela; faze-a ferver bem, e cozam-se dentro dela os seus ossos.'),
('acf','ez',24,6,'Portanto, assim diz o Senhor DEUS: Ai da cidade sanguinária, da panela que escuma por dentro, e cuja escuma não saiu dela! Tira dela pedaço por pedaço; não caia sorte sobre ela;'),
('acf','ez',24,7,'Porque o seu sangue está no meio dela, sobre uma penha descalvada o pôs; não o derramou sobre a terra, para o cobrir com pó.'),
('acf','ez',24,8,'Para fazer subir a indignação, para tomar vingança, eu pus o seu sangue numa penha descalvada, para que não fosse coberto.'),
('acf','ez',24,9,'Portanto, assim diz o Senhor DEUS: Ai da cidade sanguinária! Também eu farei uma grande fogueira.'),
('acf','ez',24,10,'Amontoa muita lenha, acende o fogo, ferve bem a carne, e tempera o caldo, e ardam os ossos.'),
('acf','ez',24,11,'Então a porás vazia sobre as suas brasas, para que ela aqueça, e se queime o seu cobre, e se funda a sua imundícia no meio dela, e se consuma a sua escuma.'),
('acf','ez',24,12,'Ela com mentiras se cansou; e não saiu dela a sua muita escuma; ao fogo irá a sua escuma.'),
('acf','ez',24,13,'Na imundícia está a infâmia, porquanto te purifiquei, e não permaneceste pura; nunca mais serás purificada da tua imundícia, enquanto eu não fizer descansar sobre ti a minha indignação.'),
('acf','ez',24,14,'Eu, o SENHOR, o disse: viva isso, e o farei, não me tornarei atrás, e não pouparei, nem me arrependerei; conforme os teus caminhos, e conforme os teus feitos, te julgarão, diz o Senhor DEUS.'),
('acf','ez',24,15,'E veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',24,16,'Filho do homem, eis que, de um golpe tirarei de ti o desejo dos teus olhos, mas não lamentarás, nem chorarás, nem te correrão as lágrimas.'),
('acf','ez',24,17,'Geme em silêncio, não faças luto por mortos; ata o teu turbante, e põe nos pés os teus sapatos, e não cubras os teus lábios, e não comas o pão dos homens.'),
('acf','ez',24,18,'E falei ao povo pela manhã, e à tarde morreu minha mulher; e fiz pela manhã como me foi mandado.'),
('acf','ez',24,19,'E o povo me disse: Porventura não nos farás saber o que significam para nós estas coisas que estás fazendo?'),
('acf','ez',24,20,'E eu lhes disse: Veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',24,21,'Dize à casa de Israel: Assim diz o Senhor DEUS: Eis que eu profanarei o meu santuário, a glória da vossa força, o desejo dos vossos olhos, e o anelo das vossas almas; e vossos filhos e vossas filhas, que deixastes, cairão à espada.'),
('acf','ez',24,22,'E fareis como eu fiz; não vos cobrireis os lábios, e não comereis o pão dos homens.'),
('acf','ez',24,23,'E tereis nas cabeças os vossos turbantes, e os vossos sapatos nos pés; não lamentareis, nem chorareis, mas definhar-vos-eis nas vossas maldades, e gemereis uns com os outros.'),
('acf','ez',24,24,'Assim vos servirá Ezequiel de sinal; conforme tudo quanto ele fez, fareis; quando isso suceder, sabereis que eu sou o Senhor DEUS.'),
('acf','ez',24,25,'E quanto a ti, filho do homem, não sucederá que no dia que eu lhes tirar a sua força, a alegria da sua glória, o desejo dos seus olhos, e o anelo de suas almas, com seus filhos e suas filhas,'),
('acf','ez',24,26,'Nesse dia virá ter contigo aquele que escapar, para te dar notícias pessoalmente?'),
('acf','ez',24,27,'Naquele dia abrir-se-á a tua boca para com aquele que escapar, e falarás, e não mais ficarás mudo; assim virás a ser para eles um sinal, e saberão que eu sou o Senhor.'),
('acf','ez',25,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',25,2,'Filho do homem, dirige o teu rosto contra os filhos de Amom, e profetiza contra eles.'),
('acf','ez',25,3,'E dize aos filhos de Amom: Ouvi a palavra do Senhor DEUS: Assim diz o Senhor DEUS: Porquanto tu disseste: Ah! contra o meu santuário, quando foi profanado; e contra a terra de Israel, quando foi assolada; e contra a casa de Judá, quando foi ao cativeiro;'),
('acf','ez',25,4,'Portanto, eis que te entregarei em possessão aos do oriente, e em ti estabelecerão os seus acampamentos, e porão em ti as suas moradas; eles comerão os teus frutos, e eles beberão o teu leite.'),
('acf','ez',25,5,'E farei de Rabá uma estrebaria de camelos, e dos filhos de Amom um curral de ovelhas; e sabereis que eu sou o Senhor.'),
('acf','ez',25,6,'Porque assim diz o Senhor DEUS: Porquanto bateste com as mãos, e pateaste com os pés, e com todo o desprezo do teu coração te alegraste contra a terra de Israel,'),
('acf','ez',25,7,'Portanto, eis que eu tenho estendido a minha mão sobre ti, e te darei por despojo aos gentios, e te arrancarei dentre os povos, e te destruirei dentre as terras, e acabarei de todo contigo; e saberás que eu sou o Senhor.'),
('acf','ez',25,8,'Assim diz o Senhor DEUS: Porquanto dizem Moabe e Seir: Eis que a casa de Judá é como todos os gentios;'),
('acf','ez',25,9,'Portanto, eis que eu abrirei o lado de Moabe desde as cidades, desde as suas cidades da fronteira, a glória da terra, Bete-Jesimote, Baal-Meom, e Quiriataim.'),
('acf','ez',25,10,'E aos do oriente, contra os filhos de Amom, o entregarei em possessão, para que não haja memória dos filhos de Amom entre as nações.'),
('acf','ez',25,11,'Também executarei juízos sobre Moabe, e saberão que eu sou o Senhor.'),
('acf','ez',25,12,'Assim diz o Senhor DEUS: Porquanto Edom se houve vingativamente para com a casa de Judá, e se fez culpadíssimo, quando se vingou deles;'),
('acf','ez',25,13,'Portanto assim diz o Senhor DEUS: Também estenderei a minha mão sobre Edom, e arrancarei dela homens e animais; e a tornarei em deserto, e desde Temã até Dedã cairão à espada.'),
('acf','ez',25,14,'E exercerei a minha vingança sobre Edom, pela mão do meu povo de Israel; e farão em Edom segundo a minha ira e segundo o meu furor; e conhecerão a minha vingança, diz o Senhor DEUS.'),
('acf','ez',25,15,'Assim diz o Senhor DEUS: Porquanto os filisteus se houveram vingativamente, e executaram vingança com desprezo de coração, para destruírem com perpétua inimizade,'),
('acf','ez',25,16,'Portanto assim diz o Senhor DEUS: Eis que eu estendo a minha mão sobre os filisteus, e arrancarei os quereteus, e destruirei o restante da costa do mar.'),
('acf','ez',25,17,'E executarei sobre eles grandes vinganças, com furiosos castigos, e saberão que eu sou o Senhor, quando eu tiver exercido a minha vingança sobre eles.'),
('acf','ez',26,1,'E sucedeu no undécimo ano, ao primeiro do mês, que veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',26,2,'Filho do homem, visto que Tiro disse contra Jerusalém: Ah! está quebrada a porta dos povos; virou-se para mim; eu me encherei, agora que ela está assolada;'),
('acf','ez',26,3,'Portanto assim diz o Senhor DEUS: Eis que eu estou contra ti, ó Tiro, e farei subir contra ti muitas nações, como o mar faz subir as suas ondas,'),
('acf','ez',26,4,'Elas destruirão os muros de Tiro, e derrubarão as suas torres; e eu lhe varrerei o seu pó, e dela farei uma penha descalvada.'),
('acf','ez',26,5,'No meio do mar virá a ser um enxugadouro das redes; porque eu o falei, diz o Senhor DEUS; e servirá de despojo para as nações.'),
('acf','ez',26,6,'E suas filhas, que estão no campo, serão mortas à espada; e saberão que eu sou o Senhor.'),
('acf','ez',26,7,'Porque assim diz o Senhor DEUS: Eis que eu, desde o norte, trarei contra Tiro a Nabucodonosor, rei de babilônia, o rei dos reis, com cavalos, e com carros, e com cavaleiros, e companhias, e muito povo.'),
('acf','ez',26,8,'As tuas filhas que estão no campo, ele as matará à espada, e levantará um baluarte contra ti, e fundará uma trincheira contra ti, e levantará paveses contra ti.'),
('acf','ez',26,9,'E disporá os seus aríetes contra os teus muros, e derrubará as tuas torres com os seus machados.'),
('acf','ez',26,10,'Por causa da multidão de seus cavalos te cobrirá o seu pó; os teus muros tremerão com o estrondo dos cavaleiros, e das rodas, e dos carros, quando ele entrar pelas tuas portas, como os homens entram numa cidade em que se fez brecha.'),
('acf','ez',26,11,'Com os cascos dos seus cavalos pisará todas as tuas ruas; ao teu povo matará à espada, e as tuas fortes colunas cairão por terra.'),
('acf','ez',26,12,'E roubarão as tuas riquezas, e saquearão as tuas mercadorias, e derrubarão os teus muros, e arrazarão as tuas casas agradáveis; e lançarão no meio das águas as tuas pedras, e as tuas madeiras, e o teu pó.'),
('acf','ez',26,13,'E farei cessar o ruído das tuas cantigas, e o som dos tuas harpas não se ouvirá mais.'),
('acf','ez',26,14,'E farei de ti uma penha descalvada; virás a ser um enxugadouro das redes, nunca mais serás edificada; porque eu o SENHOR o falei, diz o Senhor DEUS.'),
('acf','ez',26,15,'Assim diz o Senhor DEUS a Tiro: Porventura não tremerão as ilhas com o estrondo da tua queda, quando gemerem os feridos, quando se fizer uma espantosa matança no meio de ti?'),
('acf','ez',26,16,'E todos os príncipes do mar descerão dos seus tronos, e tirarão de si os seus mantos, e despirão as suas vestes bordadas; se vestirão de tremores, sobre a terra se assentarão, e estremecerão a cada momento; e por tua causa pasmarão.'),
('acf','ez',26,17,'E levantarão uma lamentação sobre ti, e te dirão: Como pereceste, ó bem povoada e afamada cidade, que foste forte no mar; ela e os seus moradores, que atemorizaram a todos os seus habitantes!'),
('acf','ez',26,18,'Agora, estremecerão as ilhas no dia da tua queda; sim, as ilhas, que estão no mar, turbar-se-ão com tua saída.'),
('acf','ez',26,19,'Porque assim diz o Senhor DEUS: Quando eu te fizer uma cidade assolada, como as cidades que não se habitam, quando eu fizer subir sobre ti o abismo, e as muitas águas te cobrirem,'),
('acf','ez',26,20,'Então te farei descer com os que descem à cova, ao povo antigo, e te farei habitar nas mais baixas partes da terra, em lugares desertos antigos, com os que descem à cova, para que não sejas habitada; e estabelecerei a glória na terra dos viventes.'),
('acf','ez',26,21,'Farei de ti um grande espanto, e não mais existirás; e quando te buscarem então nunca mais serás achada para sempre, diz o Senhor DEUS.'),
('acf','ez',27,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',27,2,'Tu pois, ó filho do homem, levanta uma lamentação sobre Tiro.'),
('acf','ez',27,3,'E dize a Tiro, que habita nas entradas do mar, e negocia com os povos em muitas ilhas: Assim diz o Senhor Deus: Ó Tiro, tu dizes: Eu sou perfeita em formosura.'),
('acf','ez',27,4,'No coração dos mares estão os teus termos; os que te edificaram aperfeiçoaram a tua formosura.'),
('acf','ez',27,5,'Fabricaram todos os teus conveses de faias de Senir; trouxeram cedros do Líbano para te fazerem mastros.'),
('acf','ez',27,6,'Fizeram os teus remos de carvalhos de Basã; os teus bancos fizeram-nos de marfim engastado em buxo das ilhas dos quiteus.'),
('acf','ez',27,7,'Linho fino bordado do Egito era a tua cortina, para te servir de vela; azul e púrpura das ilhas de Elisá era a tua cobertura.'),
('acf','ez',27,8,'Os moradores de Sidom e de Arvade foram os teus remadores; os teus sábios, ó Tiro, que se achavam em ti, esses foram os teus pilotos.'),
('acf','ez',27,9,'Os anciãos de Gebal e seus sábios foram em ti os que consertavam as tuas fendas; todos os navios do mar e os marinheiros se acharam em ti, para tratarem dos teus negócios.'),
('acf','ez',27,10,'Os persas, e os lídios, e os de Pute eram no teu exército os teus soldados; escudos e capacetes penduraram em ti; eles manifestaram a tua beleza.'),
('acf','ez',27,11,'Os filhos de Arvade e o teu exército estavam sobre os teus muros em redor, e os gamaditas nas tuas torres; penduravam os seus escudos nos teus muros em redor; eles aperfeiçoavam a tua formosura.'),
('acf','ez',27,12,'Társis negociava contigo, por causa da abundância de toda a casta de riquezas; com prata, ferro, estanho e chumbo, negociavam em tuas feiras.'),
('acf','ez',27,13,'Javã, Tubal e Meseque eram teus mercadores; em troca das tuas mercadorias davam pessoas de homens e objetos de bronze.'),
('acf','ez',27,14,'Os da casa de Togarma trocavam pelas tuas mercadorias, cavalos, e cavaleiros e mulos.'),
('acf','ez',27,15,'Os filhos de Dedã eram os teus mercadores; muitas ilhas eram o comércio da tua mão; dentes de marfim e pau de ébano tornavam a dar-te em presente.'),
('acf','ez',27,16,'A Síria negociava contigo por causa da multidão das tuas manufaturas; pelas tuas mercadorias davam esmeralda, púrpura, obra bordada, linho fino, corais e ágata.'),
('acf','ez',27,17,'Judá e a terra de Israel, eram os teus mercadores; pelas tuas mercadorias trocavam trigo de Minite, e Panague, e mel, azeite e bálsamo.'),
('acf','ez',27,18,'Damasco negociava contigo, por causa da multidão das tuas obras, por causa da abundância de toda a sorte de riqueza, dando em troca vinho de Helbom e lã branca.'),
('acf','ez',27,19,'Também Dã e Javã, de Uzal, pelas tuas mercadorias, davam em troca ferro trabalhado, cássia e cálamo aromático, que assim entravam no teu comércio.'),
('acf','ez',27,20,'Dedã negociava contigo com panos preciosos para carros.'),
('acf','ez',27,21,'A Arábia, e todos os príncipes de Quedar, eram mercadores ao teu serviço, com cordeiros, carneiros e bodes; nestas coisas negociavam contigo.'),
('acf','ez',27,22,'Os mercadores de Sabá e Raamá eram os teus mercadores; em todos os seus mais finos aromas, em toda a pedra preciosa e ouro, negociaram nas tuas feiras.'),
('acf','ez',27,23,'Harã, e Cane e Éden, os mercadores de Sabá, Assur e Quilmade negociavam contigo.'),
('acf','ez',27,24,'Estes eram teus mercadores em roupas escolhidas, em pano de azul, e bordados, e em cofres de roupas preciosas, amarrados com cordas e feitos de cedros, entre tua mercadoria.'),
('acf','ez',27,25,'Os navios de Társis eram as tuas caravanas que traziam tuas mercadorias; e te encheste, e te glorificaste muito no meio dos mares.'),
('acf','ez',27,26,'Os teus remadores te conduziram sobre grandes águas; o vento oriental te quebrou no meio dos mares.'),
('acf','ez',27,27,'As tuas riquezas, as tuas feiras, e tuas mercadorias, os teus marinheiros, os teus pilotos, os que consertavam as tuas fendas, os que faziam os teus negócios, e todos os teus soldados, que estão em ti, juntamente com toda a tua companhia, que está no meio de ti, cairão no meio dos mares no dia da tua queda,'),
('acf','ez',27,28,'Ao estrondo da gritaria dos teus pilotos tremerão os arrabaldes.'),
('acf','ez',27,29,'E todos os que pegam no remo, os marinheiros, e todos os pilotos do mar descerão de seus navios, e pararão em terra.'),
('acf','ez',27,30,'E farão ouvir a sua voz sobre ti, e gritarão amargamente; e lançarão pó sobre as cabeças, e na cinza se revolverão.'),
('acf','ez',27,31,'E far-se-ão calvos por tua causa, e cingir-se-ão de sacos, e chorarão sobre ti com amargura de alma, e com amarga lamentação.'),
('acf','ez',27,32,'E no seu pranto levantarão uma lamentação sobre ti, e te lamentarão sobre ti, dizendo: Quem foi como Tiro, como a que foi destruída no meio do mar?'),
('acf','ez',27,33,'Quando as tuas mercadorias saiam pelos mares, fartaste a muitos povos; com a multidão das tuas riquezas e do teu negócio, enriqueceste os reis da terra.'),
('acf','ez',27,34,'No tempo em que foste quebrantada pelos mares, nas profundezas das águas, caíram, no meio de ti, os teus negócios e toda a tua companhia.'),
('acf','ez',27,35,'Todos os moradores das ilhas estão a teu respeito cheios de espanto; e os seus reis tremeram sobremaneira, e ficaram perturbados nos seus rostos;'),
('acf','ez',27,36,'Os mercadores dentre os povos assobiaram contra ti; tu te tornaste em grande espanto, e jamais subsistirá.'),
('acf','ez',28,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',28,2,'Filho do homem, dize ao príncipe de Tiro: Assim diz o Senhor DEUS: Porquanto o teu coração se elevou e disseste: Eu sou Deus, sobre a cadeira de Deus me assento no meio dos mares; e não passas de homem, e não és Deus, ainda que estimas o teu coração como se fora o coração de Deus;'),
('acf','ez',28,3,'Eis que tu és mais sábio que Daniel; e não há segredo algum que se possa esconder de ti.'),
('acf','ez',28,4,'Pela tua sabedoria e pelo teu entendimento alcançaste para ti riquezas, e adquiriste ouro e prata nos teus tesouros.'),
('acf','ez',28,5,'Pela extensão da tua sabedoria no teu comércio aumentaste as tuas riquezas; e eleva-se o teu coração por causa das tuas riquezas;'),
('acf','ez',28,6,'Portanto, assim diz o Senhor DEUS: Porquanto estimas o teu coração, como se fora o coração de Deus,'),
('acf','ez',28,7,'Por isso eis que eu trarei sobre ti estrangeiros, os mais terríveis dentre as nações, os quais desembainharão as suas espadas contra a formosura da tua sabedoria, e mancharão o teu resplendor.'),
('acf','ez',28,8,'Eles te farão descer à cova e morrerás da morte dos traspassados no meio dos mares.'),
('acf','ez',28,9,'Acaso dirás ainda diante daquele que te matar: Eu sou Deus? mas tu és homem, e não Deus, na mão do que te traspassa.'),
('acf','ez',28,10,'Da morte dos incircuncisos morrerás, por mão de estrangeiros, porque eu o falei, diz o Senhor DEUS.'),
('acf','ez',28,11,'Veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',28,12,'Filho do homem, levanta uma lamentação sobre o rei de Tiro, e dize-lhe: Assim diz o Senhor DEUS: Tu eras o selo da medida, cheio de sabedoria e perfeito em formosura.'),
('acf','ez',28,13,'Estiveste no Éden, jardim de Deus; de toda a pedra preciosa era a tua cobertura: sardônia, topázio, diamante, turquesa, ônix, jaspe, safira, carbúnculo, esmeralda e ouro; em ti se faziam os teus tambores e os teus pífaros; no dia em que foste criado foram preparados.'),
('acf','ez',28,14,'Tu eras o querubim, ungido para cobrir, e te estabeleci; no monte santo de Deus estavas, no meio das pedras afogueadas andavas.'),
('acf','ez',28,15,'Perfeito eras nos teus caminhos, desde o dia em que foste criado, até que se achou iniqüidade em ti.'),
('acf','ez',28,16,'Na multiplicação do teu comércio encheram o teu interior de violência, e pecaste; por isso te lancei, profanado, do monte de Deus, e te fiz perecer, ó querubim cobridor, do meio das pedras afogueadas.'),
('acf','ez',28,17,'Elevou-se o teu coração por causa da tua formosura, corrompeste a tua sabedoria por causa do teu resplendor; por terra te lancei, diante dos reis te pus, para que olhem para ti.'),
('acf','ez',28,18,'Pela multidão das tuas iniqüidades, pela injustiça do teu comércio profanaste os teus santuários; eu, pois, fiz sair do meio de ti um fogo, que te consumiu e te tornei em cinza sobre a terra, aos olhos de todos os que te vêem.'),
('acf','ez',28,19,'Todos os que te conhecem entre os povos estão espantados de ti; em grande espanto te tornaste, e nunca mais subsistirá.'),
('acf','ez',28,20,'E veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',28,21,'Filho do homem, dirige o teu rosto contra Sidom, e profetiza contra ela,'),
('acf','ez',28,22,'E dize: Assim diz o Senhor DEUS: Eis-me contra ti, ó Sidom, e serei glorificado no meio de ti; e saberão que eu sou o SENHOR, quando nela executar juízos e nela me santificar.'),
('acf','ez',28,23,'Porque enviarei contra ela a peste, e o sangue nas suas ruas, e os traspassados cairão no meio dela, estando a espada contra ela por todos os lados; e saberão que eu sou o Senhor.'),
('acf','ez',28,24,'E a casa de Israel nunca mais terá espinho que a fira, nem espinho que cause dor, entre os que se acham ao redor deles e que os desprezam; e saberão que eu sou o Senhor DEUS.'),
('acf','ez',28,25,'Assim diz o Senhor DEUS: Quando eu congregar a casa de Israel dentre os povos entre os quais estão espalhados, e eu me santificar entre eles, perante os olhos dos gentios, então habitarão na sua terra que dei a meu servo, a Jacó.'),
('acf','ez',28,26,'E habitarão nela seguros, e edificarão casas, e plantarão vinhas, e habitarão seguros, quando eu executar juízos contra todos os que estão ao seu redor e que os desprezam; e saberão que eu sou o Senhor seu Deus.'),
('acf','ez',29,1,'No décimo ano, no décimo mês, no dia doze do mês, veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',29,2,'Filho do homem, dirige o teu rosto contra Faraó, rei do Egito, e profetiza contra ele e contra todo o Egito.'),
('acf','ez',29,3,'Fala, e dize: Assim diz o Senhor DEUS: Eis-me contra ti, ó Faraó, rei do Egito, grande dragão, que pousas no meio dos teus rios, e que dizes: O meu rio é meu, e eu o fiz para mim.'),
('acf','ez',29,4,'Mas eu porei anzóis em teus queixos, e farei que os peixes dos teus rios se apeguem às tuas escamas; e tirar-te-ei do meio dos teus rios, e todos os peixes dos teus rios se apegarem às tuas escamas.'),
('acf','ez',29,5,'E te deixarei no deserto, a ti e a todo o peixe dos teus rios; sobre a face do campo cairás; não serás recolhido nem ajuntado; aos animais da terra e às aves do céu te dei por mantimento.'),
('acf','ez',29,6,'E saberão todos os moradores do Egito que eu sou o Senhor, porquanto se tornaram um bordão de cana para a casa de Israel.'),
('acf','ez',29,7,'Tomando-te eles pela mão, te quebraste, e lhes rasgaste todo o ombro; e quando se apoiaram em ti, te quebraste, e lhes fazias tremer todos os seus lombos.'),
('acf','ez',29,8,'Portanto, assim diz o Senhor DEUS: Eis que eu trarei sobre ti a espada, e de ti destruirei homem e animal,'),
('acf','ez',29,9,'E a terra do Egito se tornará em desolação e deserto; e saberão que eu sou o Senhor, porquanto disse: O rio é meu, e eu o fiz.'),
('acf','ez',29,10,'Portanto, eis que eu estou contra ti, e contra os teus rios; e tornarei a terra do Egito deserta, em completa desolação, desde a torre de Syene até aos confins da Etiópia.'),
('acf','ez',29,11,'Não passará por ela pé de homem, nem pé de animal passará por ela, nem será habitada quarenta anos.'),
('acf','ez',29,12,'Porque tornarei a terra do Egito em desolação no meio das terras desoladas; e as suas cidades entre as cidades desertas se tornarão em desolação por quarenta anos; e espalharei os egípcios entre as nações, e os dispersarei pelas terras.'),
('acf','ez',29,13,'Porém, assim diz o Senhor DEUS: Ao fim de quarenta anos ajuntarei os egípcios dentre os povos entre os quais foram espalhados.'),
('acf','ez',29,14,'E removerei o cativeiro dos egípcios, e os farei voltar à terra de Patros, à terra de sua origem; e serão ali um reino humilde;'),
('acf','ez',29,15,'Mais humilde se fará do que os outros reinos, e nunca mais se exalçará sobre as nações; porque os diminuirei, para que não dominem sobre as nações.'),
('acf','ez',29,16,'E não será mais a confiança da casa de Israel, para lhes trazer à lembrança a sua iniqüidade, quando olharem para trás deles; antes saberão que eu sou o Senhor DEUS.'),
('acf','ez',29,17,'E sucedeu que, no ano vinte e sete, no primeiro mês, no primeiro dia do mês, veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',29,18,'Filho do homem, Nabucodonosor, rei de babilônia, fez com que o seu exército prestasse um grande serviço contra Tiro; toda a cabeça se tornou calva, e todo o ombro se pelou; e não houve paga de Tiro para ele, nem para o seu exército, pelo serviço que prestou contra ela.'),
('acf','ez',29,19,'Portanto, assim diz o Senhor DEUS: Eis que eu darei a Nabucodonosor, rei de babilônia, a terra do Egito; e levará a sua multidão, e tomará o seu despojo, e roubará a sua presa, e isto será a recompensa para o seu exército.'),
('acf','ez',29,20,'Como recompensa do seu trabalho, com que serviu contra ela, lhe dei a terra do Egito; porquanto trabalharam por mim, diz o Senhor DEUS.'),
('acf','ez',29,21,'Naquele dia farei brotar o poder na casa de Israel, e abrirei a tua boca no meio deles; e saberão que eu sou o Senhor.'),
('acf','ez',30,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',30,2,'Filho do homem, profetiza, e dize: Assim diz o Senhor DEUS: Gemei: Ah! Aquele dia!'),
('acf','ez',30,3,'Porque está perto o dia, sim, está perto o dia do Senhor; dia nublado; será o tempo dos gentios.'),
('acf','ez',30,4,'A espada virá ao Egito, e haverá grande dor na Etiópia, quando caírem os traspassados no Egito; e tomarão a sua multidão, e serão destruídos os seus fundamentos.'),
('acf','ez',30,5,'Etiópia, Pute e Lude, e toda a mistura de gente, e Cube, e os homens da terra da liga, juntamente com eles cairão à espada.'),
('acf','ez',30,6,'Assim diz o SENHOR: Também cairão os que sustém o Egito, e descerá a soberba de seu poder; desde a torre de Syene ali cairão à espada, diz o Senhor DEUS.'),
('acf','ez',30,7,'E serão desolados no meio das terras assoladas; e as suas cidades estarão no meio das cidades desertas.'),
('acf','ez',30,8,'E saberão que eu sou o Senhor, quando eu puser fogo no Egito, e forem destruídos todos os que lhe davam auxílio.'),
('acf','ez',30,9,'Naquele dia sairão mensageiros de diante de mim em navios, para espantarem a Etiópia descuidada; e haverá neles grandes dores, como no dia do Egito; pois, eis que já vem.'),
('acf','ez',30,10,'Assim diz o Senhor DEUS: Eu, pois, farei cessar a multidão do Egito, por mão de Nabucodonosor, rei de babilônia.'),
('acf','ez',30,11,'Ele e o seu povo com ele, os mais terríveis das nações, serão levados para destruírem a terra; e desembainharão as suas espadas contra o Egito, e encherão a terra de mortos.'),
('acf','ez',30,12,'E secarei os rios, e venderei a terra entregando-a na mão dos maus, e assolarei a terra e a sua plenitude pela mão dos estrangeiros; eu, o Senhor, o disse.'),
('acf','ez',30,13,'Assim diz o Senhor DEUS: Também destruirei os ídolos, e farei cessar as imagens de Nofe; e não haverá mais um príncipe da terra do Egito; e porei o temor na terra do Egito.'),
('acf','ez',30,14,'E assolarei a Patros, e porei fogo a Zoã, e executarei juízos em Nô.'),
('acf','ez',30,15,'E derramarei o meu furor sobre Sim, a fortaleza do Egito, e exterminarei a multidão de Nô.'),
('acf','ez',30,16,'E porei fogo no Egito; Sim terá grande dor, e Nô será fendida, e Nofe terá angústias cotidianas.'),
('acf','ez',30,17,'Os jovens de Áven e Pi-Besete cairão à espada, e as cidades irão em cativeiro.'),
('acf','ez',30,18,'E em Tafnes se escurecerá o dia, quando eu quebrar ali os jugos do Egito, e nela cessar a soberba do seu poder; uma nuvem a cobrirá, e suas filhas irão em cativeiro.'),
('acf','ez',30,19,'Assim executarei juízos no Egito, e saberão que eu sou o Senhor.'),
('acf','ez',30,20,'E sucedeu que, no ano undécimo, no primeiro mês, aos sete do mês, veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',30,21,'Filho do homem, eu quebrei o braço de Faraó, rei do Egito, e eis que não foi atado para se lhe aplicar remédios, nem lhe colocarão ligaduras para o atar, a fim de torná-lo forte, para pegar na espada.'),
('acf','ez',30,22,'Portanto assim diz o Senhor DEUS: Eis que eu estou contra Faraó, rei do Egito, e quebrarei os seus braços, assim o forte como o que está quebrado, e farei cair da sua mão a espada.'),
('acf','ez',30,23,'E espalharei os egípcios entre as nações, e os dispersarei pelas terras.'),
('acf','ez',30,24,'E fortalecerei os braços do rei de babilônia, e porei a minha espada na sua mão; mas quebrarei os braços de Faraó, e diante dele gemerá como geme o traspassado.'),
('acf','ez',30,25,'Eu fortalecerei os braços do rei de babilônia, mas os braços de Faraó cairão; e saberão que eu sou o SENHOR, quando eu puser a minha espada na mão do rei de babilônia, e ele a estender sobre a terra do Egito.'),
('acf','ez',30,26,'E espalharei os egípcios entre as nações, e os dispersarei entre as terras; assim saberão que eu sou o Senhor.'),
('acf','ez',31,1,'E sucedeu, no ano undécimo, no terceiro mês, ao primeiro do mês, que veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',31,2,'Filho do homem, dize a Faraó, rei do Egito, e à sua multidão: A quem és semelhante na tua grandeza?'),
('acf','ez',31,3,'Eis que a Assíria era um cedro no Líbano, de ramos formosos, de sombrosa ramagem e de alta estatura, e a sua copa estava entre os ramos espessos.'),
('acf','ez',31,4,'As águas o fizeram crescer, o abismo o exalçou; as suas correntes corriam em torno da sua plantação, e ele enviava os regatos a todas as árvores do campo.'),
('acf','ez',31,5,'Por isso se elevou a sua estatura sobre todas as árvores do campo, e se multiplicaram os seus ramos, e se alongaram as suas varas, por causa das muitas águas quando brotava.'),
('acf','ez',31,6,'Todas as aves do céu se aninhavam nos seus ramos, e todos os animais do campo geravam debaixo dos seus ramos, e todas as grandes nações habitavam à sua sombra.'),
('acf','ez',31,7,'Assim era ele formoso na sua grandeza, na extensão dos seus ramos, porque a sua raiz estava junto às muitas águas.'),
('acf','ez',31,8,'Os cedros, no jardim de Deus, não o podiam obscurecer; as faias não igualavam os seus ramos, e os castanheiros não eram como os seus renovos; nenhuma árvore no jardim de Deus se assemelhou a ele na sua formosura.'),
('acf','ez',31,9,'Formoso o fiz com a multidão dos seus ramos; e todas as árvores do Éden, que estavam no jardim de Deus, tiveram inveja dele.'),
('acf','ez',31,10,'Portanto assim diz o Senhor DEUS: Porquanto te elevaste na tua estatura, e se levantou a sua copa no meio dos espessos ramos, e o seu coração se exalçou na sua altura,'),
('acf','ez',31,11,'Eu o entregarei na mão do mais poderoso dos gentios, que lhe dará o tratamento merecido; pela sua impiedade o lançarei fora.'),
('acf','ez',31,12,'E estrangeiros, das mais terríveis nações o cortarão, e deixá-lo-ão; cairão os seus ramos sobre os montes e por todos os vales, e os seus renovos serão quebrados por todos os rios da terra; e todos os povos da terra se retirarão da sua sombra, e o deixarão.'),
('acf','ez',31,13,'Todas as aves do céu habitarão sobre a sua ruína, e todos os animais do campo se acolherão sob os seus renovos;'),
('acf','ez',31,14,'Para que todas as árvores junto às águas não se exaltem na sua estatura, nem levantem a sua copa no meio dos ramos espessos, nem as que bebem as águas venham a confiar em si, por causa da sua altura; porque todos estão entregues à morte, até à terra mais baixa, no meio dos filhos dos homens, com os que descem à cova.'),
('acf','ez',31,15,'Assim diz o Senhor DEUS: No dia em que ele desceu ao inferno, fiz eu que houvesse luto; fiz cobrir o abismo, por sua causa, e retive as suas correntes, e detiveram-se as muitas águas; e cobri o Líbano de preto por causa dele, e todas as árvores do campo por causa dele desfaleceram.'),
('acf','ez',31,16,'Ao som da sua queda fiz tremer as nações, quando o fiz descer ao inferno, com os que descem à cova; e todas as árvores do Éden, a flor e o melhor do Líbano, todas as árvores que bebem águas, se consolavam nas partes mais baixas da terra.'),
('acf','ez',31,17,'Também estes com ele descerão ao inferno a juntar-se aos que foram traspassados à espada, sim, aos que foram seu braço, e que habitavam à sombra no meio dos gentios.'),
('acf','ez',31,18,'A quem, pois, és semelhante em glória e em grandeza entre as árvores do Éden? Todavia serás precipitado com as árvores do Éden às partes mais baixas da terra; no meio dos incircuncisos jazerás com os que foram traspassados à espada; este é Faraó e toda a sua multidão, diz o Senhor DEUS.'),
('acf','ez',32,1,'E sucedeu que, no ano duodécimo, no duodécimo mês, ao primeiro do mês, veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',32,2,'Filho do homem, levanta uma lamentação sobre Faraó, rei do Egito, e dize-lhe: Eras semelhante a um filho do leão entre as nações, mas tu és como uma baleia nos mares, e rompias os teus rios, e turbavas as águas com os teus pés, e pisavas os teus rios.'),
('acf','ez',32,3,'Assim diz o Senhor DEUS: Portanto, estenderei sobre ti a minha rede com reunião de muitos povos, e te farão subir na minha rede.'),
('acf','ez',32,4,'Então te deixarei em terra; sobre a face do campo te lançarei, e farei posar sobre ti todas as aves do céu, e fartarei de ti os animais de toda a terra.'),
('acf','ez',32,5,'E porei as tuas carnes sobre os montes, e encherei os vales da tua altura.'),
('acf','ez',32,6,'E regarei com o teu sangue a terra onde nadas, até aos montes; e os rios se encherão de ti.'),
('acf','ez',32,7,'E, apagando-te eu, cobrirei os céus, e enegrecerei as suas estrelas; ao sol encobrirei com uma nuvem, e a lua não fará resplandecer a sua luz.'),
('acf','ez',32,8,'Todas as brilhantes luzes do céu enegrecerei sobre ti, e trarei trevas sobre a tua terra, diz o Senhor DEUS.'),
('acf','ez',32,9,'E afligirei os corações de muitos povos, quando eu levar a tua destruição entre as nações, às terras que não conheceste.'),
('acf','ez',32,10,'E farei com que muitos povos fiquem pasmados de ti, e os seus reis tremam sobremaneira, quando eu brandir a minha espada ante os seus rostos; e estremecerão a cada momento, cada um pela sua vida, no dia da tua queda.'),
('acf','ez',32,11,'Porque assim diz o Senhor DEUS: A espada do rei de babilônia virá sobre ti.'),
('acf','ez',32,12,'Farei cair a tua multidão pelas espadas dos poderosos, que são todos os mais terríveis das nações; e destruirão a soberba do Egito, e toda a sua multidão será destruída.'),
('acf','ez',32,13,'E exterminarei todos os seus animais sobre as muitas águas; nem as turbará mais pé de homem, nem as turbarão unhas de animais.'),
('acf','ez',32,14,'Então farei assentar as suas águas, e farei correr os seus rios como o azeite, diz o Senhor DEUS.'),
('acf','ez',32,15,'Quando eu tornar a terra do Egito em desolação, e ela for despojada da sua plenitude, e quando ferir a todos os que habitam nela, então saberão que eu sou o Senhor.'),
('acf','ez',32,16,'Esta é a lamentação que se fará; que as filhas das nações farão; sobre o Egito e sobre toda a sua multidão, diz o Senhor DEUS.'),
('acf','ez',32,17,'E sucedeu que, no ano duodécimo, aos quinze do mês, veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',32,18,'Filho do homem, pranteia sobre a multidão do Egito, e faze-a descer, a ela e às filhas das nações magníficas, às partes mais baixas da terra, juntamente com os que descem à cova.'),
('acf','ez',32,19,'A quem sobrepujas tu em formosura? Desce, e deita-te com os incircuncisos.'),
('acf','ez',32,20,'No meio daqueles que foram mortos à espada cairão; à espada ela está entregue; arrastai-a e a toda a sua multidão.'),
('acf','ez',32,21,'Os mais poderosos dos fortes lhe falarão desde o meio do inferno, com os que a socorrem; desceram, jazeram com os incircuncisos mortos à espada.'),
('acf','ez',32,22,'Ali está Assur com toda a sua multidão; em redor dele estão os seus sepulcros; todos eles mortos, abatidos à espada.'),
('acf','ez',32,23,'Os seus sepulcros foram postos nas extremidades da cova, e a sua multidão está em redor do seu sepulcro; todos eles mortos, abatidos à espada; os que tinham causado espanto na terra dos viventes.'),
('acf','ez',32,24,'Ali está Elão com toda a sua multidão em redor do seu sepulcro; todos eles mortos, abatidos à espada; desceram incircuncisos às partes mais baixas da terra, causaram terror na terra dos viventes e levaram a sua vergonha com os que desceram à cova.'),
('acf','ez',32,25,'No meio dos mortos lhe puseram uma cama, entre toda a sua multidão; ao redor dele estão os seus sepulcros; todos eles são incircuncisos, mortos à espada; porque causaram terror na terra dos viventes, e levaram a sua vergonha com os que desceram à cova; foi posto no meio dos mortos.'),
('acf','ez',32,26,'Ali estão Meseque, Tubal e toda a sua multidão; ao redor deles estão os seus sepulcros; todos eles são incircuncisos, e mortos à espada, porquanto causaram terror na terra dos viventes.'),
('acf','ez',32,27,'Porém não jazerão com os poderosos que caíram dos incircuncisos, os quais desceram ao inferno com as suas armas de guerra e puseram as suas espadas debaixo das suas cabeças; e a sua iniqüidade está sobre os seus ossos, porquanto eram o terror dos fortes na terra dos viventes.'),
('acf','ez',32,28,'Também tu serás quebrado no meio dos incircuncisos, e jazerás com os que foram mortos à espada.'),
('acf','ez',32,29,'Ali está Edom, os seus reis e todos os seus príncipes, que com o seu poder foram postos com os que foram mortos à espada; estes jazem com os incircuncisos e com os que desceram à cova.'),
('acf','ez',32,30,'Ali estão os príncipes do norte, todos eles, e todos os sidônios, que desceram com os mortos, envergonhados com o terror causado pelo seu poder; e jazem incircuncisos com os que foram mortos à espada, e levam a sua vergonha com os que desceram à cova.'),
('acf','ez',32,31,'Faraó os verá, e se consolará com toda a sua multidão; sim, o próprio Faraó, e todo o seu exército, mortos à espada, diz o Senhor DEUS.'),
('acf','ez',32,32,'Porque também eu pus o meu espanto na terra dos viventes; por isso jazerá no meio dos incircuncisos, com os mortos à espada, Faraó e toda a sua multidão, diz o Senhor DEUS.'),
('acf','ez',33,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',33,2,'Filho do homem, fala aos filhos do teu povo, e dize-lhes: Quando eu fizer vir a espada sobre a terra, e o povo da terra tomar um homem dos seus termos, e o constituir por seu atalaia;'),
('acf','ez',33,3,'E, vendo ele que a espada vem sobre a terra, tocar a trombeta e avisar o povo;'),
('acf','ez',33,4,'Se aquele que ouvir o som da trombeta, não se der por avisado, e vier a espada, e o alcançar, o seu sangue será sobre a sua cabeça.'),
('acf','ez',33,5,'Ele ouviu o som da trombeta, e não se deu por avisado, o seu sangue será sobre ele; mas o que se dá por avisado salvará a sua vida.'),
('acf','ez',33,6,'Mas, se quando o atalaia vir que vem a espada, e não tocar a trombeta, e não for avisado o povo, e a espada vier, e levar uma vida dentre eles, este tal foi levado na sua iniqüidade, porém o seu sangue requererei da mão do atalaia.'),
('acf','ez',33,7,'A ti, pois, ó filho do homem, te constituí por atalaia sobre a casa de Israel; tu, pois, ouvirás a palavra da minha boca, e lha anunciarás da minha parte.'),
('acf','ez',33,8,'Se eu disser ao ímpio: Ó ímpio, certamente morrerás; e tu não falares, para dissuadir ao ímpio do seu caminho, morrerá esse ímpio na sua iniqüidade, porém o seu sangue eu o requererei da tua mão.'),
('acf','ez',33,9,'Mas, se advertires o ímpio do seu caminho, para que dele se converta, e ele não se converter do seu caminho, ele morrerá na sua iniqüidade; mas tu livraste a tua alma.'),
('acf','ez',33,10,'Tu, pois, filho do homem, dize à casa de Israel: Assim falais vós, dizendo: Visto que as nossas transgressões e os nossos pecados estão sobre nós, e nós desfalecemos neles, como viveremos então?'),
('acf','ez',33,11,'Dize-lhes: Vivo eu, diz o Senhor DEUS, que não tenho prazer na morte do ímpio, mas em que o ímpio se converta do seu caminho, e viva. Convertei-vos, convertei-vos dos vossos maus caminhos; pois, por que razão morrereis, ó casa de Israel?'),
('acf','ez',33,12,'Tu, pois, filho do homem, dize aos filhos do teu povo: A justiça do justo não o livrará no dia da sua transgressão; e, quanto à impiedade do ímpio, não cairá por ela, no dia em que se converter da sua impiedade; nem o justo poderá viver pela sua justiça no dia em que pecar.'),
('acf','ez',33,13,'Quando eu disser ao justo que certamente viverá, e ele, confiando na sua justiça, praticar a iniqüidade, não virão à memória todas as suas justiças, mas na sua iniqüidade, que pratica, ele morrerá.'),
('acf','ez',33,14,'Quando eu também disser ao ímpio: Certamente morrerás; se ele se converter do seu pecado, e praticar juízo e justiça,'),
('acf','ez',33,15,'Restituindo esse ímpio o penhor, indenizando o que furtou, andando nos estatutos da vida, e não praticando iniqüidade, certamente viverá, não morrerá.'),
('acf','ez',33,16,'De todos os seus pecados que cometeu não se terá memória contra ele; juízo e justiça fez, certamente viverá.'),
('acf','ez',33,17,'Todavia os filhos do teu povo dizem: Não é justo o caminho do Senhor; mas o próprio caminho deles é que não é justo.'),
('acf','ez',33,18,'Desviando-se o justo da sua justiça, e praticando iniqüidade, morrerá nela.'),
('acf','ez',33,19,'E, convertendo-se o ímpio da sua impiedade, e praticando juízo e justiça, ele viverá por eles.'),
('acf','ez',33,20,'Todavia, vós dizeis: Não é justo o caminho do Senhor; julgar-vos-ei a cada um conforme os seus caminhos, ó casa de Israel.'),
('acf','ez',33,21,'E sucedeu que, no ano duodécimo do nosso cativeiro, no décimo mês, aos cinco do mês, veio a mim um que tinha escapado de Jerusalém, dizendo: A cidade está ferida.'),
('acf','ez',33,22,'Ora, a mão do Senhor estivera sobre mim pela tarde, antes que viesse o que tinha escapado; e ele abrira a minha boca antes que esse homem viesse ter comigo pela manhã; e abriu-se a minha boca, e não fiquei mais calado.'),
('acf','ez',33,23,'Então veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',33,24,'Filho do homem, os moradores destes lugares desertos da terra de Israel falam, dizendo: Abraão era um só, e possuiu esta terra; mas nós somos muitos, esta terra nos foi dada em possessão.'),
('acf','ez',33,25,'Dize-lhes portanto: Assim diz o Senhor DEUS: Comeis a carne com o sangue, e levantais os vossos olhos para os vossos ídolos, e derramais o sangue! Porventura possuireis a terra?'),
('acf','ez',33,26,'Vós vos estribais sobre a vossa espada, cometeis abominação, e cada um contamina a mulher do seu próximo! E possuireis a terra?'),
('acf','ez',33,27,'Assim lhes dirás: Assim disse o Senhor DEUS: Vivo eu, que os que estiverem em lugares desertos, cairão à espada, e o que estiver em campo aberto o entregarei às feras, para que o devorem, e os que estiverem em lugares fortes e em cavernas morrerão de peste.'),
('acf','ez',33,28,'E tornarei a terra em desolação e espanto e cessará a soberba do seu poder; e os montes de Israel ficarão tão desolados que ninguém passará por eles.'),
('acf','ez',33,29,'Então saberão que eu sou o Senhor, quando eu tornar a terra em desolação e espanto, por causa de todas as abominações que cometeram.'),
('acf','ez',33,30,'Quanto a ti, ó filho do homem, os filhos do teu povo falam de ti junto às paredes e nas portas das casas; e fala um com o outro, cada um a seu irmão, dizendo: Vinde, peço-vos, e ouvi qual seja a palavra que procede do Senhor.'),
('acf','ez',33,31,'E eles vêm a ti, como o povo costumava vir, e se assentam diante de ti, como meu povo, e ouvem as tuas palavras, mas não as põem por obra; pois lisonjeiam com a sua boca, mas o seu coração segue a sua avareza.'),
('acf','ez',33,32,'E eis que tu és para eles como uma canção de amores, de quem tem voz suave, e que bem tange; porque ouvem as tuas palavras, mas não as põem por obra.'),
('acf','ez',33,33,'Mas, quando vier isto (eis que está para vir), então saberão que houve no meio deles um profeta.'),
('acf','ez',34,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',34,2,'Filho do homem, profetiza contra os pastores de Israel; profetiza, e dize aos pastores: Assim diz o Senhor DEUS: Ai dos pastores de Israel que se apascentam a si mesmos! Não devem os pastores apascentar as ovelhas?'),
('acf','ez',34,3,'Comeis a gordura, e vos vestis da lã; matais o cevado; mas não apascentais as ovelhas.'),
('acf','ez',34,4,'As fracas não fortalecestes, e a doente não curastes, e a quebrada não ligastes, e a desgarrada não tornastes a trazer, e a perdida não buscastes; mas dominais sobre elas com rigor e dureza.'),
('acf','ez',34,5,'Assim se espalharam, por não haver pastor, e tornaram-se pasto para todas as feras do campo, porquanto se espalharam.'),
('acf','ez',34,6,'As minhas ovelhas andaram desgarradas por todos os montes, e por todo o alto outeiro; sim, as minhas ovelhas andaram espalhadas por toda a face da terra, sem haver quem perguntasse por elas, nem quem as buscasse.'),
('acf','ez',34,7,'Portanto, ó pastores, ouvi a palavra do Senhor:'),
('acf','ez',34,8,'Vivo eu, diz o Senhor DEUS, que, porquanto as minhas ovelhas foram entregues à rapina, e as minhas ovelhas vieram a servir de pasto a todas as feras do campo, por falta de pastor, e os meus pastores não procuraram as minhas ovelhas; e os pastores apascentaram a si mesmos, e não apascentaram as minhas ovelhas;'),
('acf','ez',34,9,'Portanto, ó pastores, ouvi a palavra do Senhor:'),
('acf','ez',34,10,'Assim diz o Senhor DEUS: Eis que eu estou contra os pastores; das suas mãos demandarei as minhas ovelhas, e eles deixarão de apascentar as ovelhas; os pastores não se apascentarão mais a si mesmos; e livrarei as minhas ovelhas da sua boca, e não lhes servirão mais de pasto.'),
('acf','ez',34,11,'Porque assim diz o Senhor DEUS: Eis que eu, eu mesmo, procurarei pelas minhas ovelhas, e as buscarei.'),
('acf','ez',34,12,'Como o pastor busca o seu rebanho, no dia em que está no meio das suas ovelhas dispersas, assim buscarei as minhas ovelhas; e livrá-las-ei de todos os lugares por onde andam espalhadas, no dia nublado e de escuridão.'),
('acf','ez',34,13,'E tirá-las-ei dos povos, e as congregarei dos países, e as trarei à sua própria terra, e as apascentarei nos montes de Israel, junto aos rios, e em todas as habitações da terra.'),
('acf','ez',34,14,'Em bons pastos as apascentarei, e nos altos montes de Israel será o seu aprisco; ali se deitarão num bom redil, e pastarão em pastos gordos nos montes de Israel.'),
('acf','ez',34,15,'Eu mesmo apascentarei as minhas ovelhas, e eu as farei repousar, diz o Senhor DEUS.'),
('acf','ez',34,16,'A perdida buscarei, e a desgarrada tornarei a trazer, e a quebrada ligarei, e a enferma fortalecerei; mas a gorda e a forte destruirei; apascentá-las-ei com juízo.'),
('acf','ez',34,17,'E quanto a vós, ó ovelhas minhas, assim diz o Senhor DEUS: Eis que eu julgarei entre ovelhas e ovelhas, entre carneiros e bodes.'),
('acf','ez',34,18,'Acaso não vos basta pastar os bons pastos, senão que pisais o resto de vossos pastos aos vossos pés? E não vos basta beber as águas claras, senão que sujais o resto com os vossos pés?'),
('acf','ez',34,19,'E quanto às minhas ovelhas elas pastarão o que haveis pisado com os vossos pés, e beberão o que haveis sujado com os vossos pés.'),
('acf','ez',34,20,'Por isso o Senhor DEUS assim lhes diz: Eis que eu, eu mesmo, julgarei entre a ovelha gorda e a ovelha magra.'),
('acf','ez',34,21,'Porquanto com o lado e com o ombro dais empurrões, e com os vossos chifres escorneais todas as fracas, até que as espalhais para fora.'),
('acf','ez',34,22,'Portanto livrarei as minhas ovelhas, para que não sirvam mais de rapina, e julgarei entre ovelhas e ovelhas.'),
('acf','ez',34,23,'E suscitarei sobre elas um só pastor, e ele as apascentará; o meu servo Davi é que as apascentará; ele lhes servirá de pastor.'),
('acf','ez',34,24,'E eu, o Senhor, lhes serei por Deus, e o meu servo Davi será príncipe no meio delas; eu, o Senhor, o disse.'),
('acf','ez',34,25,'E farei com elas uma aliança de paz, e acabarei com as feras da terra, e habitarão em segurança no deserto, e dormirão nos bosques.'),
('acf','ez',34,26,'E delas e dos lugares ao redor do meu outeiro, farei uma bênção; e farei descer a chuva a seu tempo; chuvas de bênção serão.'),
('acf','ez',34,27,'E as árvores do campo darão o seu fruto, e a terra dará a sua novidade, e estarão seguras na sua terra; e saberão que eu sou o Senhor, quando eu quebrar as ataduras do seu jugo e as livrar da mão dos que se serviam delas.'),
('acf','ez',34,28,'E não servirão mais de rapina aos gentios, as feras da terra nunca mais as devorarão; e habitarão seguramente, e ninguém haverá que as espante.'),
('acf','ez',34,29,'E lhes levantarei uma plantação de renome, e nunca mais serão consumidas pela fome na terra, nem mais levarão sobre si o opróbrio dos gentios.'),
('acf','ez',34,30,'Saberão, porém, que eu, o SENHOR seu Deus, estou com elas, e que elas são o meu povo, a casa de Israel, diz o Senhor DEUS.'),
('acf','ez',34,31,'Vós, pois, ó ovelhas minhas, ovelhas do meu pasto; homens sois; porém eu sou o vosso Deus, diz o Senhor DEUS.'),
('acf','ez',35,1,'E veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',35,2,'Filho do homem, dirige o teu rosto contra o monte Seir, e profetiza contra ele.'),
('acf','ez',35,3,'E dize-lhe: Assim diz o Senhor DEUS: Eis que eu estou contra ti, ó monte Seir, e estenderei a minha mão contra ti, e te farei maior desolação.'),
('acf','ez',35,4,'As tuas cidades farei desertas, e tu serás desolado; e saberás que eu sou o Senhor.'),
('acf','ez',35,5,'Porquanto guardaste inimizade perpétua, e espalhaste os filhos de Israel pelo poder da espada no tempo da sua calamidade e no tempo da iniqüidade final.'),
('acf','ez',35,6,'Por isso vivo eu, diz o Senhor DEUS, que te preparei para sangue, e o sangue te perseguirá; visto que não odiaste o sangue, o sangue te perseguirá.'),
('acf','ez',35,7,'E farei do monte Seir uma extrema desolação, e exterminarei dele o que por ele passar, e o que por ele voltar.'),
('acf','ez',35,8,'E encherei os seus montes dos seus mortos; nos teus outeiros, e nos teus vales, e em todos os teus rios cairão os mortos à espada.'),
('acf','ez',35,9,'Em desolações perpétuas te porei, e as tuas cidades nunca mais serão habitadas; assim sabereis que eu sou o Senhor.'),
('acf','ez',35,10,'Porquanto disseste: As duas nações e as duas terras serão minhas, e as possuiremos, sendo que o Senhor se achava ali.'),
('acf','ez',35,11,'Portanto, vivo eu, diz o Senhor DEUS, que procederei conforme a tua ira, e conforme a tua inveja, de que usaste, no teu ódio contra eles; e me farei conhecer entre eles, quando te julgar.'),
('acf','ez',35,12,'E saberás que eu, o Senhor, ouvi todas as tuas blasfêmias, que proferiste contra os montes de Israel, dizendo: Já estão assolados, a nós nos são entregues por pasto.'),
('acf','ez',35,13,'Assim vos engrandecestes contra mim com a vossa boca, e multiplicastes as vossas palavras contra mim. Eu o ouvi.'),
('acf','ez',35,14,'Assim diz o Senhor DEUS: Quando toda a terra se alegrar eu te porei em desolação.'),
('acf','ez',35,15,'Como te alegraste da herança da casa de Israel, porque foi assolada, assim te farei a ti; assolado serás, ó monte Seir, e todo o Edom, sim, todo ele; e saberão que eu sou o Senhor.'),
('acf','ez',36,1,'E tu, ó filho do homem, profetiza aos montes de Israel, e dize: Montes de Israel, ouvi a palavra do SENHOR.'),
('acf','ez',36,2,'Assim diz o Senhor DEUS: Pois que disse o inimigo contra vós: Ah! ah! até as alturas eternas serão nossa herança;'),
('acf','ez',36,3,'Portanto, profetiza, e dize: Assim diz o Senhor DEUS: Porquanto vos assolaram e devoraram de todos os lados, para que ficásseis feitos herança do restante dos gentios, e tendes andado em lábios paroleiros, e em infâmia do povo,'),
('acf','ez',36,4,'Portanto, ouvi, ó montes de Israel, a palavra do Senhor DEUS: Assim diz o Senhor DEUS aos montes e aos outeiros, aos rios e aos vales, aos lugares assolados e solitários, e às cidades desamparadas que se tornaram em rapina e em escárnio para o restante dos gentios que lhes estão em redor;'),
('acf','ez',36,5,'Portanto, assim diz o Senhor DEUS: Certamente no fogo do meu zelo falei contra o restante dos gentios, e contra todo o Edom, que se apropriaram da minha terra, com toda a alegria de seu coração, e com menosprezo da alma, para a lançarem fora à rapina.'),
('acf','ez',36,6,'Portanto, profetiza sobre a terra de Israel, e dize aos montes, e aos outeiros, aos rios e aos vales: Assim diz o Senhor DEUS: Eis que falei no meu zelo e no meu furor, porque levastes sobre vós o opróbrio dos gentios.'),
('acf','ez',36,7,'Portanto, assim diz o Senhor DEUS: Eu levantei a minha mão, para que os gentios, que estão ao redor de vós, levem o seu opróbrio.'),
('acf','ez',36,8,'Mas vós, ó montes de Israel, produzireis os vossos ramos, e dareis o vosso fruto para o meu povo de Israel; porque estão prestes a vir.'),
('acf','ez',36,9,'Porque eis que eu estou convosco, e eu me voltarei para vós, e sereis lavrados e semeados.'),
('acf','ez',36,10,'E multiplicarei homens sobre vós, a toda a casa de Israel, a toda ela; e as cidades serão habitadas, e os lugares devastados serão edificados.'),
('acf','ez',36,11,'E multiplicarei homens e animais sobre vós, e eles se multiplicarão, e frutificarão. E farei com que sejais habitados como dantes e vos tratarei melhor que nos vossos princípios; e sabereis que eu sou o Senhor.'),
('acf','ez',36,12,'E farei andar sobre vós homens, o meu povo de Israel; eles te possuirão, e serás a sua herança, e nunca mais os desfilharás.'),
('acf','ez',36,13,'Assim diz o Senhor DEUS: Porquanto vos dizem: Tu és uma terra que devora os homens, e és uma terra que desfilha as suas nações;'),
('acf','ez',36,14,'Por isso tu não devorarás mais os homens, nem desfilharás mais as tuas nações, diz o Senhor DEUS.'),
('acf','ez',36,15,'E farei que nunca mais tu ouças a afronta dos gentios; nem levarás mais sobre ti o opróbrio das gentes, nem mais desfilharás a tua nação, diz o Senhor DEUS.'),
('acf','ez',36,16,'E veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',36,17,'Filho do homem, quando a casa de Israel habitava na sua terra, então a contaminaram com os seus caminhos e com as suas ações. Como a imundícia de uma mulher em sua separação, tal era o seu caminho perante o meu rosto.'),
('acf','ez',36,18,'Derramei, pois, o meu furor sobre eles, por causa do sangue que derramaram sobre a terra, e dos seus ídolos, com que a contaminaram.'),
('acf','ez',36,19,'E espalhei-os entre os gentios, e foram dispersos pelas terras; conforme os seus caminhos, e conforme os seus feitos, eu os julguei.'),
('acf','ez',36,20,'E, chegando aos gentios para onde foram, profanaram o meu santo nome, porquanto se dizia deles: Estes são o povo do Senhor, e saíram da sua terra.'),
('acf','ez',36,21,'Mas eu os poupei por amor do meu santo nome, que a casa de Israel profanou entre os gentios para onde foi.'),
('acf','ez',36,22,'Dize portanto à casa de Israel: Assim diz o Senhor DEUS: Não é por respeito a vós que eu faço isto, ó casa de Israel, mas pelo meu santo nome, que profanastes entre as nações para onde fostes.'),
('acf','ez',36,23,'E eu santificarei o meu grande nome, que foi profanado entre os gentios, o qual profanastes no meio deles; e os gentios saberão que eu sou o SENHOR, diz o Senhor DEUS, quando eu for santificado aos seus olhos.'),
('acf','ez',36,24,'E vos tomarei dentre os gentios, e vos congregarei de todas as terras, e vos trarei para a vossa terra.'),
('acf','ez',36,25,'Então aspergirei água pura sobre vós, e ficareis purificados; de todas as vossas imundícias e de todos os vossos ídolos vos purificarei.'),
('acf','ez',36,26,'E dar-vos-ei um coração novo, e porei dentro de vós um espírito novo; e tirarei da vossa carne o coração de pedra, e vos darei um coração de carne.'),
('acf','ez',36,27,'E porei dentro de vós o meu Espírito, e farei que andeis nos meus estatutos, e guardeis os meus juízos, e os observeis.'),
('acf','ez',36,28,'E habitareis na terra que eu dei a vossos pais e vós sereis o meu povo, e eu serei o vosso Deus.'),
('acf','ez',36,29,'E livrar-vos-ei de todas as vossas imundícias; e chamarei o trigo, e o multiplicarei, e não trarei fome sobre vós.'),
('acf','ez',36,30,'E multiplicarei o fruto das árvores, e a novidade do campo, para que nunca mais recebais o opróbrio da fome entre os gentios.'),
('acf','ez',36,31,'Então vos lembrareis dos vossos maus caminhos, e dos vossos feitos, que não foram bons; e tereis nojo em vós mesmos das vossas iniqüidades e das vossas abominações.'),
('acf','ez',36,32,'Não é por amor de vós que eu faço isto, diz o Senhor DEUS; notório vos seja; envergonhai-vos, e confundi-vos por causa dos vossos caminhos, ó casa de Israel.'),
('acf','ez',36,33,'Assim diz o Senhor DEUS: No dia em que eu vos purificar de todas as vossas iniqüidades, então farei com que sejam habitadas as cidades e sejam edificados os lugares devastados.'),
('acf','ez',36,34,'E a terra assolada será lavrada, em lugar de estar assolada aos olhos de todos os que passavam.'),
('acf','ez',36,35,'E dirão: Esta terra assolada ficou como jardim do Éden: e as cidades solitárias, e assoladas, e destruídas, estão fortalecidas e habitadas.'),
('acf','ez',36,36,'Então saberão os gentios, que tiverem ficado ao redor de vós, que eu, o Senhor, tenho reedificado as cidades destruídas, e plantado o que estava devastado. Eu, o Senhor, o disse e o farei.'),
('acf','ez',36,37,'Assim diz o Senhor DEUS: Ainda por isso serei solicitado pela casa de Israel, que lho faça; multiplicar-lhes-ei os homens, como a um rebanho.'),
('acf','ez',36,38,'Como o rebanho santificado, como o rebanho de Jerusalém nas suas solenidades, assim as cidades desertas se encherão de rebanhos de homens; e saberão que eu sou o Senhor.'),
('acf','ez',37,1,'Veio sobre mim a mão do SENHOR, e ele me fez sair no Espírito do SENHOR, e me pôs no meio de um vale que estava cheio de ossos.'),
('acf','ez',37,2,'E me fez passar em volta deles; e eis que eram mui numerosos sobre a face do vale, e eis que estavam sequíssimos.'),
('acf','ez',37,3,'E me disse: Filho do homem, porventura viverão estes ossos? E eu disse: Senhor DEUS, tu o sabes.'),
('acf','ez',37,4,'Então me disse: Profetiza sobre estes ossos, e dize-lhes: Ossos secos, ouvi a palavra do Senhor.'),
('acf','ez',37,5,'Assim diz o Senhor DEUS a estes ossos: Eis que farei entrar em vós o espírito, e vivereis.'),
('acf','ez',37,6,'E porei nervos sobre vós e farei crescer carne sobre vós, e sobre vós estenderei pele, e porei em vós o espírito, e vivereis, e sabereis que eu sou o Senhor.'),
('acf','ez',37,7,'Então profetizei como se me deu ordem. E houve um ruído, enquanto eu profetizava; e eis que se fez um rebuliço, e os ossos se achegaram, cada osso ao seu osso.'),
('acf','ez',37,8,'E olhei, e eis que vieram nervos sobre eles, e cresceu a carne, e estendeu-se a pele sobre eles por cima; mas não havia neles espírito.'),
('acf','ez',37,9,'E ele me disse: Profetiza ao espírito, profetiza, ó filho do homem, e dize ao espírito: Assim diz o Senhor DEUS: Vem dos quatro ventos, ó espírito, e assopra sobre estes mortos, para que vivam.'),
('acf','ez',37,10,'E profetizei como ele me deu ordem; então o espírito entrou neles, e viveram, e se puseram em pé, um exército grande em extremo.'),
('acf','ez',37,11,'Então me disse: Filho do homem, estes ossos são toda a casa de Israel. Eis que dizem: Os nossos ossos se secaram, e pereceu a nossa esperança; nós mesmos estamos cortados.'),
('acf','ez',37,12,'Portanto profetiza, e dize-lhes: Assim diz o Senhor DEUS: Eis que eu abrirei os vossos sepulcros, e vos farei subir das vossas sepulturas, ó povo meu, e vos trarei à terra de Israel.'),
('acf','ez',37,13,'E sabereis que eu sou o Senhor, quando eu abrir os vossos sepulcros, e vos fizer subir das vossas sepulturas, ó povo meu.'),
('acf','ez',37,14,'E porei em vós o meu Espírito, e vivereis, e vos porei na vossa terra; e sabereis que eu, o SENHOR, disse isto, e o fiz, diz o SENHOR.'),
('acf','ez',37,15,'E outra vez veio a mim a palavra do Senhor, dizendo:'),
('acf','ez',37,16,'Tu, pois, ó filho do homem, toma um pedaço de madeira, e escreve nele: Por Judá e pelos filhos de Israel, seus companheiros. E toma outro pedaço de madeira, e escreve nele: Por José, vara de Efraim, e por toda a casa de Israel, seus companheiros.'),
('acf','ez',37,17,'E ajunta um ao outro, para que se unam, e se tornem uma só vara na tua mão.'),
('acf','ez',37,18,'E quando te falarem os filhos do teu povo, dizendo: Porventura não nos declararás o que significam estas coisas?'),
('acf','ez',37,19,'Tu lhes dirás: Assim diz o Senhor DEUS: Eis que eu tomarei a vara de José que esteve na mão de Efraim, e a das tribos de Israel, suas companheiras, e as ajuntarei à vara de Judá, e farei delas uma só vara, e elas se farão uma só na minha mão.'),
('acf','ez',37,20,'E as varas, sobre que houve- res escrito, estarão na tua mão, perante os olhos deles.'),
('acf','ez',37,21,'Dize-lhes pois: Assim diz o Senhor DEUS: Eis que eu tomarei os filhos de Israel dentre os gentios, para onde eles foram, e os congregarei de todas as partes, e os levarei à sua terra.'),
('acf','ez',37,22,'E deles farei uma nação na terra, nos montes de Israel, e um rei será rei de todos eles, e nunca mais serão duas nações; nunca mais para o futuro se dividirão em dois reinos.'),
('acf','ez',37,23,'E nunca mais se contaminarão com os seus ídolos, nem com as suas abominações, nem com as suas transgressões, e os livrarei de todas as suas habitações, em que pecaram, e os purificarei. Assim eles serão o meu povo, e eu serei o seu Deus.'),
('acf','ez',37,24,'E meu servo Davi será rei sobre eles, e todos eles terão um só pastor; e andarão nos meus juízos e guardarão os meus estatutos, e os observarão.'),
('acf','ez',37,25,'E habitarão na terra que dei a meu servo Jacó, em que habitaram vossos pais; e habitarão nela, eles e seus filhos, e os filhos de seus filhos, para sempre, e Davi, meu servo, será seu príncipe eternamente.'),
('acf','ez',37,26,'E farei com eles uma aliança de paz; e será uma aliança perpétua. E os estabelecerei, e os multiplicarei, e porei o meu santuário no meio deles para sempre.'),
('acf','ez',37,27,'E o meu tabernáculo estará com eles, e eu serei o seu Deus e eles serão o meu povo.'),
('acf','ez',37,28,'E os gentios saberão que eu sou o Senhor que santifico a Israel, quando estiver o meu santuário no meio deles para sempre.'),
('acf','ez',38,1,'Veio a mim a palavra do SENHOR, dizendo:'),
('acf','ez',38,2,'Filho do homem, dirige o teu rosto contra Gogue, terra de Magogue, príncipe e chefe de Meseque, e Tubal, e profetiza contra ele.'),
('acf','ez',38,3,'E dize: Assim diz o Senhor DEUS: Eis que eu sou contra ti, ó Gogue, príncipe e chefe de Meseque e de Tubal;'),
('acf','ez',38,4,'E te farei voltar, e porei anzóis nos teus queixos, e te levarei a ti, com todo o teu exército, cavalos e cavaleiros, todos vestidos com primor, grande multidão, com escudo e rodela, manejando todos a espada;'),
('acf','ez',38,5,'Persas, etíopes, e os de Pute com eles, todos com escudo e capacete;'),
('acf','ez',38,6,'Gômer e todas as suas tropas; a casa de Togarma, do extremo norte, e todas as suas tropas, muitos povos contigo.'),
('acf','ez',38,7,'Prepara-te, e dispõe-te, tu e todas as multidões do teu povo que se reuniram a ti, e serve-lhes tu de guarda.'),
('acf','ez',38,8,'Depois de muitos dias serás visitado. No fim dos anos virás à terra que se recuperou da espada, e que foi congregada dentre muitos povos, junto aos montes de Israel, que sempre se faziam desertos; mas aquela terra foi tirada dentre as nações, e todas elas habitarão seguramente.'),
('acf','ez',38,9,'Então subirás, virás como uma tempestade, far-te-ás como uma nuvem para cobrir a terra, tu e todas as tuas tropas, e muitos povos contigo.'),
('acf','ez',38,10,'Assim diz o Senhor DEUS: E acontecerá naquele dia que subirão palavras no teu coração, e maquinarás um mau desígnio,'),
('acf','ez',38,11,'E dirás: Subirei contra a terra das aldeias não muradas; virei contra os que estão em repouso, que habitam seguros; todos eles habitam sem muro, e não têm ferrolhos nem portas;'),
('acf','ez',38,12,'A fim de tomar o despojo, e para arrebatar a presa, e tornar a tua mão contra as terras desertas que agora se acham habitadas, e contra o povo que se congregou dentre as nações, o qual adquiriu gado e bens, e habita no meio da terra.'),
('acf','ez',38,13,'Sebá e Dedã, e os mercadores de Társis, e todos os seus leõezinhos te dirão: Vens tu para tomar o despojo? Ajuntaste a tua multidão para arrebatar a tua presa? Para levar a prata e o ouro, para tomar o gado e os bens, para saquear o grande despojo?'),
('acf','ez',38,14,'Portanto, profetiza, ó filho do homem, e dize a Gogue: Assim diz o Senhor DEUS: Porventura não o saberás naquele dia, quando o meu povo Israel habitar em segurança?'),
('acf','ez',38,15,'Virás, pois, do teu lugar, do extremo norte, tu e muitos povos contigo, montados todos a cavalo, grande ajuntamento, e exército poderoso,'),
('acf','ez',38,16,'E subirás contra o meu povo Israel, como uma nuvem, para cobrir a terra. Nos últimos dias sucederá que hei de trazer-te contra a minha terra, para que os gentios me conheçam a mim, quando eu me houver santificado em ti, ó Gogue, diante dos seus olhos.'),
('acf','ez',38,17,'Assim diz o Senhor DEUS: Não és tu aquele de quem eu disse nos dias antigos, por intermédio dos meus servos, os profetas de Israel, os quais naqueles dias profetizaram largos anos, que te traria contra eles?'),
('acf','ez',38,18,'Sucederá, porém, naquele dia, no dia em que vier Gogue contra a terra de Israel, diz o Senhor DEUS, que a minha indignação subirá à minha face.'),
('acf','ez',38,19,'Porque disse no meu zelo, no fogo do meu furor, que, certamente, naquele dia haverá grande tremor sobre a terra de Israel;'),
('acf','ez',38,20,'De tal modo que tremerão diante da minha face os peixes do mar, e as aves do céu, e os animais do campo, e todos os répteis que se arrastam sobre a terra, e todos os homens que estão sobre a face da terra; e os montes serão deitados abaixo, e os precipícios se desfarão, e todos os muros desabarão por terra.'),
('acf','ez',38,21,'Porque chamarei contra ele a espada sobre todos os meus montes, diz o Senhor DEUS; a espada de cada um se voltará contra seu irmão.'),
('acf','ez',38,22,'E contenderei com ele por meio da peste e do sangue; e uma chuva inundante, e grandes pedras de saraiva, fogo, e enxofre farei chover sobre ele, e sobre as suas tropas, e sobre os muitos povos que estiverem com ele.'),
('acf','ez',38,23,'Assim eu me engrandecerei e me santificarei, e me darei a conhecer aos olhos de muitas nações; e saberão que eu sou o Senhor.'),
('acf','ez',39,1,'Tu, pois, ó filho do homem, profetiza ainda contra Gogue, e dize: Assim diz o Senhor DEUS: Eis que eu sou contra ti, ó Gogue, príncipe e chefe de Meseque e de Tubal.'),
('acf','ez',39,2,'E te farei voltar, mas deixarei uma sexta parte de ti, e far-te-ei subir do extremo norte, e te trarei aos montes de Israel.'),
('acf','ez',39,3,'E, com um golpe, tirarei o teu arco da tua mão esquerda, e farei cair as tuas flechas da tua mão direita.'),
('acf','ez',39,4,'Nos montes de Israel cairás, tu e todas as tuas tropas, e os povos que estão contigo; e às aves de rapina, de toda espécie, e aos animais do campo, te darei por comida.'),
('acf','ez',39,5,'Sobre a face do campo cairás, porque eu o falei, diz o Senhor DEUS.'),
('acf','ez',39,6,'E enviarei um fogo sobre Magogue e entre os que habitam seguros nas ilhas; e saberão que eu sou o Senhor.'),
('acf','ez',39,7,'E farei conhecido o meu santo nome no meio do meu povo Israel, e nunca mais deixarei profanar o meu santo nome; e os gentios saberão que eu sou o Senhor, o Santo em Israel.'),
('acf','ez',39,8,'Eis que vem, e se cumprirá, diz o Senhor DEUS; este é o dia de que tenho falado.'),
('acf','ez',39,9,'E os habitantes das cidades de Israel sairão, e acenderão o fogo, e queimarão as armas, e os escudos e as rodelas, com os arcos, e com as flechas, e com os bastões de mão, e com as lanças; e acenderão fogo com elas por sete anos.'),
('acf','ez',39,10,'E não trarão lenha do campo, nem a cortarão dos bosques, mas com as armas acenderão fogo; e roubarão aos que os roubaram, e despojarão aos que os despojaram, diz o Senhor DEUS.'),
('acf','ez',39,11,'E sucederá que, naquele dia, darei ali a Gogue um lugar de sepultura em Israel, o vale dos que passam ao oriente do mar; e pararão os que por ele passarem; e ali sepultarão a Gogue, e a toda a sua multidão, e lhe chamarão o vale da multidão de Gogue.'),
('acf','ez',39,12,'E a casa de Israel os enterrará durante sete meses, para purificar a terra.'),
('acf','ez',39,13,'Sim, todo o povo da terra os enterrará, e será para eles memo-rável dia em que eu for glorificado, diz o Senhor Deus.'),
('acf','ez',39,14,'E separarão homens que incessantemente percorrerão a terra, para que eles, juntamente com os que passam, sepultem os que tiverem ficado sobre a face da terra, para a purificarem; durante sete meses farão esta busca.'),
('acf','ez',39,15,'E os que percorrerem a terra, a qual atravessarão, vendo algum osso de homem, porão ao lado um sinal; até que os enterradores o tenham enterrado no vale da multidão de Gogue.'),
('acf','ez',39,16,'E também o nome da cidade será Hamona; assim purificarão a terra.'),
('acf','ez',39,17,'Tu, pois, ó filho do homem, assim diz o Senhor DEUS, dize às aves de toda espécie, e a todos os animais do campo: Ajuntai-vos e vinde, congregai-vos de toda parte para o meu sacrifício, que eu ofereci por vós, um sacrifício grande, nos montes de Israel, e comei carne e bebei sangue.'),
('acf','ez',39,18,'Comereis a carne dos poderosos e bebereis o sangue dos príncipes da terra; dos carneiros, dos cordeiros, e dos bodes, e dos bezerros, todos cevados de Basã.'),
('acf','ez',39,19,'E comereis a gordura até vos fartardes e bebereis o sangue até vos embebedardes, do meu sacrifício que ofereci por vós.'),
('acf','ez',39,20,'E, à minha mesa, fartar-vos-ei de cavalos, de carros, de poderosos, e de todos os homens de guerra, diz o Senhor DEUS.'),
('acf','ez',39,21,'E eu porei a minha glória entre os gentios e todos os gentios verão o meu juízo, que eu tiver executado, e a minha mão, que sobre elas tiver descarregado.'),
('acf','ez',39,22,'E saberão os da casa de Israel que eu sou o Senhor seu Deus, desde aquele dia em diante.'),
('acf','ez',39,23,'E os gentios saberão que os da casa de Israel, por causa da sua iniqüidade, foram levados em cativeiro, porque se rebelaram contra mim, e eu escondi deles a minha face, e os entreguei nas mãos de seus adversários, e todos caíram à espada.'),
('acf','ez',39,24,'Conforme a sua imundícia e conforme as suas transgressões me houve com eles, e escondi deles a minha face.'),
('acf','ez',39,25,'Portanto assim diz o Senhor DEUS: Agora tornarei a trazer os cativos de Jacó, e me compadecerei de toda a casa de Israel; zelarei pelo meu santo nome.'),
('acf','ez',39,26,'E levarão sobre si a sua vergonha, e toda a sua rebeldia, com que se rebelaram contra mim, quando eles habitarem seguros na sua terra, sem haver quem os espante.'),
('acf','ez',39,27,'Quando eu os tornar a trazer de entre os povos, e os houver ajuntado das terras de seus inimigos, e eu for santificado neles aos olhos de muitas nações,'),
('acf','ez',39,28,'Então saberão que eu sou o Senhor seu Deus, vendo que eu os fiz ir em cativeiro entre os gentios, e os ajuntarei para voltarem a sua terra, e não mais deixarei lá nenhum deles.'),
('acf','ez',39,29,'Nem lhes esconderei mais a minha face, pois derramarei o meu Espírito sobre a casa de Israel, diz o Senhor DEUS.'),
('acf','ez',40,1,'No ano vinte e cinco do nosso cativeiro, no princípio do ano, no décimo dia do mês, catorze anos depois que a cidade foi conquistada, naquele mesmo dia veio sobre mim a mão do SENHOR, e me levou para lá.'),
('acf','ez',40,2,'Em visões de Deus me levou à terra de Israel, e me pôs sobre um monte muito alto, sobre o qual havia como que um edifício de cidade para o lado sul.'),
('acf','ez',40,3,'E, havendo-me levado ali, eis que um homem cuja aparência era como a do bronze, tendo um cordel de linho na sua mão e uma cana de medir, e estava em pé na porta.'),
('acf','ez',40,4,'E disse-me o homem: Filho do homem, vê com os teus olhos, e ouve com os teus ouvidos, e põe no teu coração tudo quanto eu te fizer ver; porque para to mostrar foste tu aqui trazido; anuncia, pois, à casa de Israel tudo quanto vires.'),
('acf','ez',40,5,'E havia um muro fora da casa, em seu redor, e na mão do homem uma cana de medir, de seis côvados, cada um dos quais tinha um côvado e um palmo; e ele mediu a largura do edifício, uma cana, e a altura, uma cana.'),
('acf','ez',40,6,'Então veio à porta que olhava para o caminho do oriente, e subiu pelos seus degraus; mediu o umbral da porta, uma cana de largo, e o outro umbral, uma cana de largo.'),
('acf','ez',40,7,'E cada câmara tinha uma cana de comprido, e uma cana de largo, e o espaço entre os aposentos era de cinco côvados; e o umbral da porta, ao pé do vestíbulo da porta, por dentro, era de uma cana.'),
('acf','ez',40,8,'Também mediu o vestíbulo da porta, por dentro, uma cana.'),
('acf','ez',40,9,'Então mediu o vestíbulo da porta, que tinha oito côvados, e os seus pilares, dois côvados, e este vestíbulo da porta, estava por dentro.'),
('acf','ez',40,10,'As câmaras da porta para o lado do oriente eram três de um lado e três do outro; a mesma medida era a dos três; também os pilares de um lado e do outro tinham a mesma medida.'),
('acf','ez',40,11,'Mediu mais a largura da entrada da porta, que era de dez côvados; e o comprimento da porta, treze côvados.'),
('acf','ez',40,12,'E o espaço em frente das câmaras era de um côvado, e de um côvado o espaço do outro lado; e cada câmara tinha seis côvados de um lado e seis côvados do outro.'),
('acf','ez',40,13,'Então mediu a porta desde o telhado de uma câmara até ao telhado da outra, vinte e cinco côvados de largo, porta contra porta.'),
('acf','ez',40,14,'Fez também os pilares, de sessenta côvados, cada pilar, do átrio, em redor da porta.'),
('acf','ez',40,15,'E, desde a face da porta da entrada até à face do vestíbulo da porta interior, havia cinqüenta côvados.'),
('acf','ez',40,16,'Havia também janelas estreitas nas câmaras, e nos seus pilares, dentro da porta ao redor, e da mesma sorte nos vestíbulos; e as janelas estavam ao redor, na parte de dentro, e nos pilares havia palmeiras.'),
('acf','ez',40,17,'E ele me levou ao átrio exterior, e eis que havia nele câmaras, e um pavimento que estava feito no átrio em redor; trinta câmaras havia naquele pavimento.'),
('acf','ez',40,18,'E o pavimento do lado das portas era proporcional ao comprimento das portas; o pavimento estava mais baixo.'),
('acf','ez',40,19,'E mediu a largura desde a dianteira da porta inferior até a dianteira do átrio interior, por fora, cem côvados, do lado do oriente e do norte.'),
('acf','ez',40,20,'E, quanto à porta que olhava para o caminho do norte, no átrio exterior, ele mediu o seu comprimento e a sua largura.'),
('acf','ez',40,21,'E as suas câmaras eram três de um lado, e três do outro, e os seus pilares e os seus arcos eram da medida da primeira porta: cinqüenta côvados era o seu comprimento, e a largura vinte e cinco côvados.'),
('acf','ez',40,22,'E as suas janelas, e os seus arcos, e as suas palmeiras, eram da medida da porta que olhava para o caminho do oriente; e subia-se para ela por sete degraus, e os seus arcos estavam diante dela.'),
('acf','ez',40,23,'E a porta do átrio interior estava defronte da porta do norte bem como da do oriente; e mediu de porta a porta cem côvados.'),
('acf','ez',40,24,'Então ele me levou ao caminho do sul, e eis que havia ali uma porta que olhava para o caminho do sul, e mediu os seus pilares e os seus arcos conforme estas medidas.'),
('acf','ez',40,25,'E havia também janelas em redor dos seus arcos, como as outras janelas; cinqüenta côvados era o comprimento, e a largura vinte e cinco côvados.'),
('acf','ez',40,26,'E de sete degraus eram as suas subidas, e os seus arcos estavam diante delas; e tinha palmeiras, uma de um lado e outra do outro, nos seus pilares.'),
('acf','ez',40,27,'Também havia uma porta no átrio interior para o caminho do sul; e mediu de porta a porta, para o caminho do sul, cem côvados.'),
('acf','ez',40,28,'Então me levou ao átrio interior pela porta do sul; e mediu a porta do sul, conforme estas medidas.'),
('acf','ez',40,29,'E as suas câmaras, e os seus pilares, e os seus arcos eram conforme estas medidas; e tinham também janelas ao redor dos seus arcos; o comprimento era de cinqüenta côvados, e a largura de vinte e cinco côvados.'),
('acf','ez',40,30,'E havia arcos em redor; o comprimento era de vinte e cinco côvados, e a largura de cinco côvados.'),
('acf','ez',40,31,'E os seus arcos estavam na direção do átrio exterior, e havia palmeiras nos seus pilares; e de oito degraus eram as suas subidas.'),
('acf','ez',40,32,'Depois me levou ao átrio interior, para o caminho do oriente, e mediu a porta conforme estas medidas;'),
('acf','ez',40,33,'E também as suas câmaras, e os seus pilares, e os seus arcos, conforme estas medidas; e havia também janelas em redor dos seus arcos; o comprimento de cinqüenta côvados, e a largura de vinte e cinco côvados.'),
('acf','ez',40,34,'E os seus arcos estavam no átrio de fora; também havia palmeiras nos seus pilares de um e de outro lado; e eram as suas subidas de oito degraus.'),
('acf','ez',40,35,'Então me levou à porta do norte, e mediu conforme estas medidas;'),
('acf','ez',40,36,'As suas câmaras, os seus pilares, e os seus arcos; também tinha janelas em redor; o comprimento era de cinqüenta côvados, e a largura de vinte e cinco côvados.'),
('acf','ez',40,37,'E os seus pilares estavam no átrio exterior; também havia palmeiras nos seus pilares de um e de outro lado; e eram as suas subidas de oito degraus.'),
('acf','ez',40,38,'E as suas câmaras e as suas entradas estavam junto aos pilares das portas onde lavavam o holocausto.'),
('acf','ez',40,39,'E no vestíbulo da porta havia duas mesas de um lado, e duas mesas do outro, para nelas se matar o holocausto e a oferta pelo pecado e pela culpa.'),
('acf','ez',40,40,'Também do lado de fora da subida para a entrada da porta do norte havia duas mesas; e do outro lado, que estava no vestíbulo da porta, havia duas mesas.'),
('acf','ez',40,41,'Quatro mesas de um lado, e quatro mesas do outro; aos lados da porta oito mesas, sobre as quais imolavam.'),
('acf','ez',40,42,'E as quatro mesas para o holocausto eram de pedras lavradas; o comprimento era de um côvado e meio, e a largura de um côvado e meio, e a altura de um côvado; e sobre elas se punham os instrumentos com que imolavam o holocausto e o sacrifício.'),
('acf','ez',40,43,'E os ganchos de um palmo de comprimento, estavam fixos por dentro em redor, e sobre as mesas estava a carne da oferta.'),
('acf','ez',40,44,'E fora da porta interior estavam as câmaras dos cantores, no átrio de dentro, que estava ao lado da porta do norte e olhava para o caminho do sul; uma estava ao lado da porta do oriente, e olhava para o caminho do norte.'),
('acf','ez',40,45,'E ele me disse: Esta câmara que olha para o caminho do sul é para os sacerdotes que têm a guarda da casa.'),
('acf','ez',40,46,'Mas a câmara que olha para o caminho do norte é para os sacerdotes que têm a guarda do altar; são estes os filhos de Zadoque, que se chegam ao Senhor, dentre os filhos de Levi, para o servir.'),
('acf','ez',40,47,'E mediu o átrio; o comprimento de cem côvados e a largura de cem côvados, um quadrado; e o altar estava diante da casa.'),
('acf','ez',40,48,'Então me levou ao vestíbulo da casa, e mediu a cada pilar do vestíbulo, cinco côvados de um lado, e cinco côvados do outro; e a largura da porta, três côvados de um lado, e três côvados do outro.'),
('acf','ez',40,49,'O comprimento do vestíbulo era de vinte côvados, e a largura de onze côvados, e era por degraus, que se subia a ele; e havia colunas junto aos pilares, uma de um lado e outra do outro.'),
('acf','ez',41,1,'Então me levou ao templo, e mediu os pilares, seis côvados de largura de um lado, e seis côvados de largura do outro, que era a largura da tenda.'),
('acf','ez',41,2,'E a largura da entrada, dez côvados; e os lados da entrada, cinco côvados de um lado e cinco côvados do outro; também mediu o seu comprimento, de quarenta côvados, e a largura, de vinte côvados.'),
('acf','ez',41,3,'E entrou no interior, e mediu o pilar da entrada, dois côvados, e a entrada, seis côvados, e a largura da entrada, sete côvados.'),
('acf','ez',41,4,'Também mediu o seu comprimento, vinte côvados, e a largura, vinte côvados, diante do templo, e disse-me: Este é o Santo dos Santos.'),
('acf','ez',41,5,'E mediu a parede da casa, seis côvados, e a largura das câmaras laterais, quatro côvados, por todo o redor da casa.'),
('acf','ez',41,6,'E as câmaras laterais, estavam em três andares, câmara sobre câmara, trinta em cada andar, e elas entravam na parede que tocava na casa pelas câmaras laterais em redor, para prenderem nela, e não travavam na parede da casa.'),
('acf','ez',41,7,'E havia maior largura nas câmaras laterais superiores, porque o caracol da casa ia subindo muito alto por todo o redor da casa, por isso que a casa tinha mais largura para cima; e assim da câmara baixa se subia à mais alta pelo meio.'),
('acf','ez',41,8,'E olhei para a altura da casa ao redor; e eram os fundamentos das câmaras laterais da medida de uma cana inteira, seis côvados grandes.'),
('acf','ez',41,9,'A grossura da parede das câmaras laterais de fora era de cinco côvados; e o que foi deixado vazio era o lugar das câmaras laterais, que estavam por dentro.'),
('acf','ez',41,10,'E entre as câmaras havia a largura de vinte côvados por todo o redor da casa.'),
('acf','ez',41,11,'E as entradas das câmaras laterais estavam voltadas para o lugar vazio; uma entrada para o caminho do norte, e outra entrada para o do sul; e a largura do lugar vazio era de cinco côvados em redor.'),
('acf','ez',41,12,'Era também o edifício que estava diante do lugar separado, do lado do ocidente, da largura de setenta côvados; e a parede do edifício de cinco côvados de largura em redor, e o seu comprimento era de noventa côvados.'),
('acf','ez',41,13,'Assim mediu a casa, do comprimento de cem côvados, como também o lugar separado, e o edifício, e as suas paredes, cem côvados de comprimento.'),
('acf','ez',41,14,'E a largura da frente da casa, e do lugar separado para o oriente, de uma e de outra parte, de cem côvados.'),
('acf','ez',41,15,'Também mediu o comprimento do edifício, diante do lugar separado, que estava por detrás, e as suas galerias de uma e de outra parte, cem côvados, com o templo de dentro e os vestíbulos do átrio.'),
('acf','ez',41,16,'Os umbrais e as janelas estreitas, e as galerias em redor nos três andares, defronte do umbral, estavam cobertas de madeira em redor; e isto desde o chão até às janelas; e as janelas estavam cobertas.'),
('acf','ez',41,17,'No espaço em cima da porta, e até na casa, no seu interior e na parte de fora, e até toda a parede em redor, por dentro e por fora, tudo por medida.'),
('acf','ez',41,18,'E foi feito com querubins e palmeiras, de maneira que cada palmeira estava entre querubim e querubim, e cada querubim tinha dois rostos,'),
('acf','ez',41,19,'A saber: um rosto de homem olhava para a palmeira de um lado, e um rosto de leãozinho para a palmeira do outro lado; assim foi feito por toda a casa em redor.'),
('acf','ez',41,20,'Desde o chão até acima da entrada estavam feitos os querubins e as palmeiras, como também pela parede do templo.'),
('acf','ez',41,21,'As ombreiras do templo eram quadradas e, no tocante à frente do santuário, a aparência de uma era como a aparência da outra,'),
('acf','ez',41,22,'O altar de madeira era de três côvados de altura, e o seu comprimento de dois côvados; os seus cantos, o seu comprimento e as suas paredes eram de madeira; e disse-me: Esta é a mesa que está perante a face do Senhor.'),
('acf','ez',41,23,'E o templo e o santuário, ambos tinham duas portas.'),
('acf','ez',41,24,'E as portas tinham duas folhas; duas folhas que viravam; duas para uma porta e duas para a outra.'),
('acf','ez',41,25,'E nelas, isto é, nas portas do templo, foram feitos querubins e palmeiras, como estavam feitos nas paredes, e havia uma trave grossa de madeira na frente do vestíbulo por fora.'),
('acf','ez',41,26,'E havia janelas estreitas, e palmeiras, de um e de outro lado, pelos lados do vestíbulo, como também nas câmaras da casa e nas grossas traves.'),
('acf','ez',42,1,'Depois disto fez-me sair para fora, ao átrio exterior, para o lado do caminho do norte; e me levou às câmaras que estavam defronte do lugar separado, e que estavam defronte do edifício, do lado norte.'),
('acf','ez',42,2,'Do comprimento de cem côvados, era a entrada do norte; e a largura era de cinqüenta côvados.'),
('acf','ez',42,3,'Em frente dos vinte côvados, que tinha o átrio interior, e em frente do pavimento que tinha o átrio exterior, havia galeria contra galeria em três andares.'),
('acf','ez',42,4,'E diante das câmaras havia um passeio de dez côvados de largo, do lado de dentro, e um caminho de um côvado, e as suas entradas eram para o lado do norte.'),
('acf','ez',42,5,'E as câmaras superiores eram mais estreitas; porque as galerias tomavam aqui mais espaço do que as de baixo e as do meio do edifício.'),
('acf','ez',42,6,'Porque elas eram de três andares, e não tinham colunas como as colunas dos átrios; por isso desde o chão se iam estreitando, mais do que as de baixo e as do meio.'),
('acf','ez',42,7,'E o muro que estava de fora, defronte das câmaras, no caminho do átrio exterior, diante das câmaras, tinha cinqüenta côvados de comprimento.'),
('acf','ez',42,8,'Pois o comprimento das câmaras, que estavam no átrio exterior, era de cinqüenta côvados; e eis que defronte do templo havia cem côvados.'),
('acf','ez',42,9,'Por baixo destas câmaras estava a entrada do lado do oriente, quando se entra nelas pelo átrio exterior.'),
('acf','ez',42,10,'Na largura do muro do átrio para o lado do oriente, diante do lugar separado, e diante do edifício, havia também câmaras.'),
('acf','ez',42,11,'E o caminho que havia diante delas era da aparência das câmaras, que davam para o norte; conforme o seu comprimento, assim era a sua largura; e todas as suas saídas eram também conforme os seus padrões, e conforme as suas entradas.'),
('acf','ez',42,12,'E conforme as portas das câmaras, que olhavam para o caminho do sul, havia também uma entrada no topo do caminho, isto é, do caminho em frente do muro direito, para o caminho do oriente, quando se entra por elas.'),
('acf','ez',42,13,'Então me disse: As câmaras do norte, e as câmaras do sul, que estão diante do lugar separado, elas são câmaras santas, em que os sacerdotes, que se chegam ao Senhor, comerão as coisas mais santas; ali porão as coisas mais santas, e a oferta de manjar, a oferta pelo pecado, e a oferta pela culpa; porque o lugar é santo.'),
('acf','ez',42,14,'Quando os sacerdotes entrarem, não sairão do santuário para o átrio exterior, mas porão ali as suas vestiduras com que ministraram, porque elas são santas; e vestir-se-ão de outras vestiduras, e assim se aproximarão do lugar pertencente ao povo.'),
('acf','ez',42,15,'E, acabando ele de medir a casa interior, ele me fez sair pelo caminho da porta, cuja face olha para o caminho do oriente; e a mediu em redor.'),
('acf','ez',42,16,'Mediu o lado oriental com a cana de medir, quinhentas canas, com a cana de medir, ao redor.'),
('acf','ez',42,17,'Mediu o lado do norte, com a cana de medir, quinhentas canas ao redor.'),
('acf','ez',42,18,'Mediu também o lado do sul, com a cana de medir, quinhentas canas.'),
('acf','ez',42,19,'Deu uma volta para o lado do ocidente, e mediu, com a cana de medir, quinhentas canas.'),
('acf','ez',42,20,'Mediu pelos quatro lados; e havia um muro em redor, de quinhentas canas de comprimento, e quinhentas de largura, para fazer separação entre o santo e o profano.'),
('acf','ez',43,1,'Então me levou à porta, à porta que olha para o caminho do oriente.'),
('acf','ez',43,2,'E eis que a glória do Deus de Israel vinha do caminho do oriente; e a sua voz era como a voz de muitas águas, e a terra resplandeceu por causa da sua glória.'),
('acf','ez',43,3,'E o aspecto da visão que tive era como o da visão que eu tivera quando vim destruir a cidade; e eram as visões como as que tive junto ao rio Quebar; e caí sobre o meu rosto.'),
('acf','ez',43,4,'E a glória do Senhor entrou na casa pelo caminho da porta, cuja face está para o lado do oriente.'),
('acf','ez',43,5,'E levantou-me o Espírito, e me levou ao átrio interior; e eis que a glória do SENHOR encheu a casa.'),
('acf','ez',43,6,'E ouvi alguém que falava comigo de dentro da casa, e um homem se pôs em pé junto de mim.'),
('acf','ez',43,7,'E disse-me: Filho do homem, este é o lugar do meu trono, e o lugar das plantas dos meus pés, onde habitarei no meio dos filhos de Israel para sempre; e os da casa de Israel não contaminarão mais o meu nome santo, nem eles nem os seus reis, com suas prostituições e com os cadáveres dos seus reis, nos seus altos,'),
('acf','ez',43,8,'Pondo o seu limiar ao pé do meu limiar, e o seu umbral junto ao meu umbral, e havendo uma parede entre mim e eles; e contaminaram o meu santo nome com as suas abominações que cometiam; por isso eu os consumi na minha ira.'),
('acf','ez',43,9,'Agora lancem eles para longe de mim a sua prostituição, e os cadáveres dos seus reis, e habitarei no meio deles para sempre.'),
('acf','ez',43,10,'Tu, pois, ó filho do homem, mostra à casa de Israel esta casa, para que se envergonhe das suas maldades, e meça o modelo.'),
('acf','ez',43,11,'E, envergonhando-se eles de tudo quanto fizeram, faze-lhes saber a forma desta casa, e a sua figura, e as suas saídas, e as suas entradas, e todas as suas formas, e todos os seus estatutos, todas as suas formas, e todas as suas leis; e escreve isto aos seus olhos, para que guardem toda a sua forma, e todos os seus estatutos, e os cumpram.'),
('acf','ez',43,12,'Esta é a lei da casa: Sobre o cume do monte todo o seu contorno em redor será santíssimo; eis que esta é a lei da casa.'),
('acf','ez',43,13,'E estas são as medidas do altar, em côvados (o côvado é um côvado e um palmo): e o fundo será de um côvado de altura, e um côvado de largura, e a sua borda em todo o seu contorno, de um palmo; e esta é a base do altar.'),
('acf','ez',43,14,'E do fundo, desde a terra até a armação inferior, dois côvados, e de largura um côvado, e desde a pequena armação até a grande, quatro côvados, e a largura de um côvado.'),
('acf','ez',43,15,'E o altar, de quatro côvados; e desde o altar e para cima havia quatro pontas.'),
('acf','ez',43,16,'E o altar terá doze côvados de comprimento, e doze de largura, quadrado nos quatro lados.'),
('acf','ez',43,17,'E a armação, catorze côvados de comprimento, e catorze de largura, nos seus quatro lados; e o contorno, ao redor dela, de meio côvado, e o fundo dela de um côvado, ao redor; e os seus degraus davam para o oriente.'),
('acf','ez',43,18,'E disse-me: Filho do homem, assim diz o Senhor DEUS: Estes são os estatutos do altar, no dia em que o fizerem, para oferecerem sobre ele holocausto e para aspergirem sobre ele sangue.'),
('acf','ez',43,19,'E aos sacerdotes levitas, que são da descendência de Zadoque, que se chegam a mim (diz o Senhor DEUS) para me servirem, darás um bezerro, para oferta pelo pecado.'),
('acf','ez',43,20,'E tomarás do seu sangue, e o porás sobre as suas quatro pontas, e sobre os quatro cantos da armação, e no contorno ao redor; assim o purificarás e o expiarás.'),
('acf','ez',43,21,'Então tomarás o bezerro da oferta pelo pecado, e o queimará no lugar da casa para isso designado, fora do santuário.'),
('acf','ez',43,22,'E no segundo dia oferecerás um bode, sem mancha, como oferta pelo pecado; e purificarão o altar, como o purificaram com o bezerro.'),
('acf','ez',43,23,'E, acabando tu de purificá-lo, oferecerás um bezerro, sem mancha, e um carneiro do rebanho, sem mancha.'),
('acf','ez',43,24,'E oferecê-los-ás perante a face do Senhor; e os sacerdotes deitarão sal sobre eles, e oferecê-los-ão em holocausto ao Senhor.'),
('acf','ez',43,25,'Por sete dias prepararás, cada dia um bode como oferta pelo pecado; também prepararão um bezerro, e um carneiro do rebanho, sem mancha.'),
('acf','ez',43,26,'Por sete dias expiarão o altar, e o purificarão; e assim consagrar-se-ão.'),
('acf','ez',43,27,'E, cumprindo eles estes dias, será que, ao oitavo dia, e dali em diante, os sacerdotes oferecerão sobre o altar os vossos holocaustos e as vossas ofertas pacíficas; e eu me deleitarei em vós, diz o Senhor DEUS.'),
('acf','ez',44,1,'Então me fez voltar para o caminho da porta exterior do santuário, que olha para o oriente, a qual estava fechada.'),
('acf','ez',44,2,'E disse-me o Senhor: Esta porta permanecerá fechada, não se abrirá; ninguém entrará por ela, porque o Senhor, o Deus de Israel entrou por ela; por isso permanecerá fechada.'),
('acf','ez',44,3,'Quanto ao príncipe, por ser príncipe, se assentará nela para sempre, para comer o pão diante do Senhor; pelo caminho do vestíbulo da porta entrará e por esse mesmo caminho sairá.'),
('acf','ez',44,4,'Depois me levou pelo caminho da porta do norte, diante da casa; e olhei, e eis que a glória do Senhor encheu a casa do Senhor; então caí sobre o meu rosto.'),
('acf','ez',44,5,'E disse-me o Senhor: Filho do homem, pondera no teu coração, e vê com os teus olhos, e ouve com os teus ouvidos, tudo quanto eu te disser de todos os estatutos da casa do Senhor, e de todas as suas leis; e considera no teu coração a entrada da casa, com todas as saídas do santuário.'),
('acf','ez',44,6,'E dize ao rebelde, à casa de Israel: Assim diz o Senhor DEUS: Bastem-vos todas as vossas abominações, ó casa de Israel!'),
('acf','ez',44,7,'Porque introduzistes estrangeiros, incircuncisos de coração e incircuncisos de carne, para estarem no meu santuário, para o profanarem em minha casa, quando ofereceis o meu pão, a gordura, e o sangue; e eles invalidaram a minha aliança, por causa de todas as vossas abominações.'),
('acf','ez',44,8,'E não guardastes a ordenança a respeito das minhas coisas sagradas; antes vos constituístes, a vós mesmos, guardas da minha ordenança no meu santuário.'),
('acf','ez',44,9,'Assim diz o Senhor DEUS: Nenhum estrangeiro, incircunciso de coração ou incircunciso de carne, entrará no meu santuário, dentre os estrangeiros que se acharem no meio dos filhos de Israel.'),
('acf','ez',44,10,'Mas os levitas que se apartaram para longe de mim, quando Israel andava errado; os quais andavam transviados, desviados de mim, para irem atrás dos seus ídolos, levarão sobre si a sua iniqüidade.'),
('acf','ez',44,11,'Contudo serão ministros no meu santuário, nos ofícios das portas da casa, e servirão à casa; eles matarão o holocausto, e o sacrifício para o povo, e estarão perante eles, para os servir.'),
('acf','ez',44,12,'Porque lhes ministraram diante dos seus ídolos, e fizeram a casa de Israel cair em iniqüidade; por isso eu levantei a minha mão contra eles, diz o Senhor DEUS, e levarão sobre si a sua iniqüidade.'),
('acf','ez',44,13,'E não se chegarão a mim, para me servirem no sacerdócio, nem para se chegarem a alguma de todas as minhas coisas sagradas, às coisas que são santíssimas, mas levarão sobre si a sua vergonha e as suas abominações que cometeram.'),
('acf','ez',44,14,'Contudo, eu os constituirei guardas da ordenança da casa, em todo o seu serviço, e em tudo o que nela se fizer.'),
('acf','ez',44,15,'Mas os sacerdotes levíticos, os filhos de Zadoque, que guardaram a ordenança do meu santuário quando os filhos de Israel se extraviaram de mim, eles se chegarão a mim, para me servirem, e estarão diante de mim, para me oferecerem a gordura e o sangue, diz o Senhor DEUS.'),
('acf','ez',44,16,'Eles entrarão no meu santuário, e se chegarão à minha mesa, para me servirem, e guardarão a minha ordenança;'),
('acf','ez',44,17,'E será que, quando entrarem pelas portas do átrio interior, se vestirão com vestes de linho; e não se porá lã sobre eles, quando servirem nas portas do átrio interior, e dentro.'),
('acf','ez',44,18,'Gorros de linho estarão sobre as suas cabeças, e calções de linho sobre os seus lombos; não se cingirão de modo que lhes venha suor.'),
('acf','ez',44,19,'E, saindo eles ao átrio exterior, ao átrio de fora, ao povo, despirão as suas vestiduras com que ministraram, e as porão nas santas câmaras, e se vestirão de outras vestes, para que não santifiquem o povo estando com as suas vestiduras.'),
('acf','ez',44,20,'E não raparão a sua cabeça, nem deixarão crescer o cabelo; antes, como convém, tosquiarão as suas cabeças.'),
('acf','ez',44,21,'E nenhum sacerdote beberá vinho quando entrar no átrio interior.'),
('acf','ez',44,22,'E eles não se casarão nem com viúva nem com repudiada, mas tomarão virgens da linhagem da casa de Israel, ou viúva que for viúva de sacerdote.'),
('acf','ez',44,23,'E a meu povo ensinarão a distinguir entre o santo e o profano, e o farão discernir entre o impuro e o puro.'),
('acf','ez',44,24,'E, quando houver disputa, eles assistirão a ela para a julgarem; pelos meus juízos as julgarão; e as minhas leis e os meus estatutos guardarão em todas as minhas solenidades, e santificarão os meus sábados.'),
('acf','ez',44,25,'E eles não se aproximarão de nenhum homem morto, para se contaminarem; mas por pai, ou por mãe, ou por filho, ou por filha, ou por irmão, ou por irmã que não tiver marido, se poderão contaminar.'),
('acf','ez',44,26,'E, depois da sua purificação, contar-se-lhe-ão sete dias.'),
('acf','ez',44,27,'E, no dia em que ele entrar no lugar santo, no átrio interior, para ministrar no lugar santo, oferecerá a sua expiação pelo pecado, diz o Senhor DEUS.'),
('acf','ez',44,28,'Eles terão uma herança: eu serei a sua herança. Não lhes dareis, portanto, possessão em Israel; eu sou a sua possessão.'),
('acf','ez',44,29,'Eles comerão a oferta de alimentos, e a oferta pelo pecado e a oferta pela culpa; e toda a coisa consagrada em Israel será deles.'),
('acf','ez',44,30,'E as primícias de todos os primeiros frutos de tudo, e toda a oblação de tudo, de todas as vossas oblações, serão dos sacerdotes; também as primeiras das vossas massas dareis ao sacerdote, para que faça repousar a bênção sobre a tua casa.'),
('acf','ez',44,31,'Nenhuma coisa, que tenha morrido ou tenha sido despedaçada, de aves e de animais, comerão os sacerdotes.'),
('acf','ez',45,1,'Quando, pois, repartirdes a terra em herança, oferecereis uma oferta ao SENHOR, uma porção santa da terra; o seu comprimento será de vinte e cinco mil canas e a largura de dez mil. Esta será santa em toda a sua extensão ao redor.'),
('acf','ez',45,2,'Desta porção o santuário ocupará quinhentas canas de comprimento, e quinhentas de largura, em quadrado, e terá em redor um espaço vazio de cinqüenta côvados.'),
('acf','ez',45,3,'E desta porção medirás vinte e cinco mil côvados de comprimento, e a largura de dez mil; e ali estará o santuário, o lugar santíssimo.'),
('acf','ez',45,4,'Esta será a porção santa da terra; ela será para os sacerdotes, ministros do santuário, que dele se aproximam para servir ao Senhor; e lhes servirá de lugar para suas casas, e de lugar santo para o santuário.'),
('acf','ez',45,5,'E os levitas, ministros da casa, terão em sua possessão, vinte e cinco mil canas de comprimento, para vinte câmaras.'),
('acf','ez',45,6,'E para possessão da cidade, de largura dareis cinco mil canas, e de comprimento vinte e cinco mil, defronte da oferta santa; o que será para toda a casa de Israel.'),
('acf','ez',45,7,'O príncipe, porém, terá a sua parte deste e do outro lado da área santa, e da possessão da cidade, diante da santa oferta, e em frente da possessão da cidade, desde o extremo ocidental até o extremo oriental, e de comprimento, corresponderá a uma das porções, desde o termo ocidental até ao termo oriental.'),
('acf','ez',45,8,'E esta terra será a sua possessão em Israel; e os meus príncipes nunca mais oprimirão o meu povo, antes deixarão a terra à casa de Israel, conforme as suas tribos.'),
('acf','ez',45,9,'Assim diz o Senhor DEUS: Basta já, ó príncipes de Israel; afastai a violência e a assolação e praticai juízo e justiça; tirai as vossas imposições do meu povo, diz o Senhor DEUS.'),
('acf','ez',45,10,'Tereis balanças justas, efa justo e bato justo.'),
('acf','ez',45,11,'O efa e o bato serão de uma mesma medida, de modo que o bato contenha a décima parte do ômer, e o efa a décima parte do ômer; conforme o ômer será a sua medida.'),
('acf','ez',45,12,'E o siclo será de vinte geras; vinte siclos, vinte e cinco siclos, e quinze siclos terá a vossa mina.'),
('acf','ez',45,13,'Esta será a oferta que haveis de oferecer: a sexta parte de um efa de cada ômer de trigo; também dareis a sexta parte de um efa de cada ômer de cevada.'),
('acf','ez',45,14,'Quanto à ordenança do azeite, de cada bato de azeite oferecereis a décima parte de um bato tirado de um coro, que é um ômer de dez batos; porque dez batos fazem um ômer.'),
('acf','ez',45,15,'E um cordeiro do rebanho, de cada duzentos, da terra mais regada de Israel, para oferta de alimentos, e para holocausto, e para sacrifício pacífico; para que façam expiação por eles, diz o Senhor DEUS.'),
('acf','ez',45,16,'Todo o povo da terra concorrerá com esta oferta, para o príncipe em Israel.'),
('acf','ez',45,17,'E estarão a cargo do príncipe os holocaustos, e as ofertas de alimentos, e as libações, nas festas, e nas luas novas, e nos sábados, em todas as solenidades da casa de Israel. Ele preparará a oferta pelo pecado, e a oferta de alimentos, e o holocausto, e os sacrifícios pacíficos, para fazer expiação pela casa de Israel.'),
('acf','ez',45,18,'Assim diz o Senhor DEUS: No primeiro mês, no primeiro dia do mês, tomarás um bezerro sem mancha e purificarás o santuário.'),
('acf','ez',45,19,'E o sacerdote tomará do sangue do sacrifício pelo pecado, e porá dele nas ombreiras da casa, e nos quatro cantos da armação do altar, e nas ombreiras da porta do átrio interior.'),
('acf','ez',45,20,'Assim também farás no sétimo dia do mês, pelos que erram, e pelos símplices; assim expiareis a casa.'),
('acf','ez',45,21,'No primeiro mês, no dia catorze do mês, tereis a páscoa, uma festa de sete dias; pão ázimo se comerá.'),
('acf','ez',45,22,'E no mesmo dia o príncipe preparará por si e por todo o povo da terra, um bezerro como oferta pelo pecado.'),
('acf','ez',45,23,'E durante os sete dias da festa preparará um holocausto ao Senhor, de sete bezerros e sete carneiros sem mancha, cada dia, durante os sete dias; e em sacrifício pelo pecado um bode cada dia.'),
('acf','ez',45,24,'Também preparará uma oferta de alimentos, a saber, um efa, para cada bezerro, e um efa para cada carneiro, e um him de azeite para cada efa.'),
('acf','ez',45,25,'No sétimo mês, no dia quinze do mês, na festa, fará o mesmo por sete dias, tanto o sacrifício pelo pecado, como o holocausto, e como a oferta de alimentos, e como o azeite.'),
('acf','ez',46,1,'Assim diz o Senhor DEUS: A porta do átrio interior que dá para o oriente, estará fechada durante os seis dias que são de trabalho; mas no dia de sábado ela se abrirá; também no dia da lua nova se abrirá.'),
('acf','ez',46,2,'E o príncipe entrará pelo caminho do vestíbulo da porta, por fora, e permanecerá junto da ombreira da porta; e os sacerdo- tes prepararão o holocausto, e os sacrifícios pacíficos dele; e ele adorará junto ao umbral da porta, e sairá; mas a porta não se fechará até à tarde.'),
('acf','ez',46,3,'E o povo da terra adorará à entrada da mesma porta, nos sábados e nas luas novas, diante do Senhor.'),
('acf','ez',46,4,'E o holocausto, que o príncipe oferecer ao Senhor, será, no dia de sábado, seis cordeiros sem mancha e um carneiro sem mancha.'),
('acf','ez',46,5,'E a oferta de alimentos será um efa para o carneiro; e para o cordeiro, a oferta de alimentos será o que puder dar; e de azeite um him para cada efa.'),
('acf','ez',46,6,'Mas no dia da lua nova será um bezerro sem mancha, e seis cordeiros e um carneiro; eles serão sem mancha.'),
('acf','ez',46,7,'E preparará por oferta de manjares um efa para o bezerro e um efa para o carneiro, mas para os cordeiros, o que a sua mão puder dar; e um him de azeite para um efa.'),
('acf','ez',46,8,'E, quando entrar o príncipe, entrará pelo caminho do vestíbulo da porta, e sairá pelo mesmo caminho.'),
('acf','ez',46,9,'Mas, quando vier o povo da terra perante a face do Senhor nas solenidades, aquele que entrar pelo caminho da porta do norte, para adorar, sairá pelo caminho da porta do sul; e aquele que entrar pelo caminho da porta do sul sairá pelo caminho da porta do norte; não tornará pelo caminho da porta por onde entrou, mas sairá pela outra que está oposta.'),
('acf','ez',46,10,'E o príncipe entrará no meio deles; quando eles entrarem e, saindo eles, sairão todos.'),
('acf','ez',46,11,'E nas festas e nas solenidades a oferta de alimentos será um efa para o bezerro, e um efa para o carneiro, mas para os cordeiros o que puder dar; e de azeite um him para um efa.'),
('acf','ez',46,12,'E, quando o príncipe fizer oferta voluntária de holocaustos, ou de sacrifícios pacíficos, uma oferta voluntária ao Senhor, então lhe abrirão a porta que dá para o oriente, e fará o seu holocausto e os seus sacrifícios pacíficos, como houver feito no dia de sábado; e sairá, e se fechará a porta depois dele sair.'),
('acf','ez',46,13,'E prepararás um cordeiro de um ano sem mancha, em holocausto ao Senhor, cada dia; todas as manhãs o prepararás.'),
('acf','ez',46,14,'E, juntamente com ele prepararás uma oferta de alimentos, todas as manhãs, a sexta parte de um efa, e de azeite a terça parte de um him, para misturar com a flor de farinha; por oferta de alimentos para o Senhor, em estatutos perpétuos e contínuos.'),
('acf','ez',46,15,'Assim prepararão o cordeiro, e a oferta de alimentos, e o azeite, todas as manhãs, em holocausto contínuo.'),
('acf','ez',46,16,'Assim diz o Senhor DEUS: Quando o príncipe der um presente a algum de seus filhos, é sua herança, pertencerá a seus filhos; será possessão deles por herança.'),
('acf','ez',46,17,'Mas, dando ele um presente da sua herança a algum dos seus servos, será deste até ao ano da liberdade; então tornará para o príncipe, porque herança dele é; seus filhos a herdarão.'),
('acf','ez',46,18,'E o príncipe não tomará nada da herança do povo por opressão, defraudando-os da sua possessão; da sua própria possessão deixará herança a seus filhos, para que o meu povo não seja separado, cada um da sua possessão.'),
('acf','ez',46,19,'Depois disto me trouxe pela entrada que estava ao lado da porta, às câmaras santas dos sacerdotes, que olhavam para o norte; e eis que ali havia um lugar nos fundos extremos, para o lado do ocidente.'),
('acf','ez',46,20,'E ele me disse: Este é o lugar onde os sacerdotes cozerão a oferta pela culpa, e a oferta pelo pecado, e onde cozerão a oferta de alimentos, para que não as tragam ao átrio exterior para santificarem o povo.'),
('acf','ez',46,21,'Então me levou para fora, para o átrio exterior, e me fez passar pelos quatro cantos do átrio; e eis que em cada canto do átrio havia outro átrio.'),
('acf','ez',46,22,'Nos quatro cantos do átrio havia outros átrios juntos, de quarenta côvados de comprimento e de trinta de largura; estes quatro cantos tinham uma mesma medida.'),
('acf','ez',46,23,'E havia uma fileira construída ao redor deles, ao redor dos quatro; e havia cozinhas feitas por baixo das fileiras ao redor.'),
('acf','ez',46,24,'E me disse: Estas são as cozinhas, onde os ministros da casa cozerão o sacrifício do povo.'),
('acf','ez',47,1,'Depois disto me fez voltar à porta da casa, e eis que saíam águas por debaixo do umbral da casa para o oriente; porque a face da casa dava para o oriente, e as águas desciam de debaixo, desde o lado direito da casa, ao sul do altar.'),
('acf','ez',47,2,'E ele me fez sair pelo caminho da porta do norte, e me fez dar uma volta pelo caminho de fora, até à porta exterior, pelo caminho que dá para o oriente e eis que corriam as águas do lado direito.'),
('acf','ez',47,3,'E saiu aquele homem para o oriente, tendo na mão um cordel de medir; e mediu mil côvados, e me fez passar pelas águas, águas que me davam pelos artelhos.'),
('acf','ez',47,4,'E mediu mais mil côvados, e me fez passar pelas águas, águas que me davam pelos joelhos; e outra vez mediu mil, e me fez passar pelas águas que me davam pelos lombos.'),
('acf','ez',47,5,'E mediu mais mil, e era um rio, que eu não podia atravessar, porque as águas eram profundas, águas que se deviam passar a nado, rio pelo qual não se podia passar.'),
('acf','ez',47,6,'E disse-me: Viste isto, filho do homem? Então levou-me, e me fez voltar para a margem do rio.'),
('acf','ez',47,7,'E, tendo eu voltado, eis que à margem do rio havia uma grande abundância de árvores, de um e de outro lado.'),
('acf','ez',47,8,'Então disse-me: Estas águas saem para a região oriental, e descem ao deserto, e entram no mar; e, sendo levadas ao mar, as águas tornar-se-ão saudáveis.'),
('acf','ez',47,9,'E será que toda a criatura vivente que passar por onde quer que entrarem estes rios viverá; e haverá muitíssimo peixe, porque lá chegarão estas águas, e serão saudáveis, e viverá tudo por onde quer que entrar este rio.'),
('acf','ez',47,10,'Será também que os pescadores estarão em pé junto dele; desde En-Gedi até En-Eglaim haverá lugar para estender as redes; o seu peixe, segundo a sua espécie, será como o peixe do mar grande, em multidão excessiva.'),
('acf','ez',47,11,'Mas os seus charcos e os seus pântanos não tornar-se-ão saudáveis; serão deixados para sal.'),
('acf','ez',47,12,'E junto ao rio, à sua margem, de um e de outro lado, nascerá toda a sorte de árvore que dá fruto para se comer; não cairá a sua folha, nem acabará o seu fruto; nos seus meses produzirá novos frutos, porque as suas águas saem do santuário; e o seu fruto servirá de comida e a sua folha de remédio.'),
('acf','ez',47,13,'Assim diz o Senhor DEUS: Este será o termo conforme o qual repartireis a terra em herança, segundo as doze tribos de Israel; José terá duas partes.'),
('acf','ez',47,14,'E vós a herdareis, tanto um como o outro; terra sobre a qual levantei a minha mão, para dá-la a vossos pais; assim esta mesma terra vos cairá a vós em herança.'),
('acf','ez',47,15,'E este será o termo da terra; do lado do norte, desde o mar grande, caminho de Hetlom, até à entrada de Zedade;'),
('acf','ez',47,16,'Hamate, Berota, Sibraim, que estão entre o termo de Damasco e o termo de Hamate; Hazer-Haticom, que está junto ao termo de Haurã.'),
('acf','ez',47,17,'E o termo será desde o mar até Hazar-Enom, o termo de Damasco, e na direção do norte, para o norte, está o termo de Hamate. Este será o lado do norte.'),
('acf','ez',47,18,'E o lado do oriente, entre Haurã, e Damasco, e Gileade, e a terra de Israel será o Jordão; desde o termo do norte até ao mar do oriente medireis. Este será o lado do oriente.'),
('acf','ez',47,19,'E o lado do sul, para o sul, será desde Tamar até às águas da contenda de Cades, junto ao ribeiro, até ao mar grande. Este será o lado do sul.'),
('acf','ez',47,20,'E o lado do ocidente será o mar grande, desde o termo do sul até a entrada de Hamate. Este será o lado do ocidente.'),
('acf','ez',47,21,'Repartireis, pois, esta terra entre vós, segundo as tribos de Israel.'),
('acf','ez',47,22,'Será, porém, que a sorteareis para vossa herança, e para a dos estrangeiros que habitam no meio de vós, que gerarão filhos no meio de vós; e vos serão como naturais entre os filhos de Israel; convosco entrarão em herança, no meio das tribos de Israel.'),
('acf','ez',47,23,'E será que na tribo em que habitar o estrangeiro, ali lhe dareis a sua herança, diz o Senhor DEUS.'),
('acf','ez',48,1,'E estes são os nomes das tribos: desde o extremo norte, ao longo do caminho de Hetlom, indo para Hamate, até Hazar-Enom, termo de Damasco para o norte, ao pé de Hamate, terá Dã uma parte, desde o lado oriental até o ocidental.'),
('acf','ez',48,2,'E junto ao termo de Dã, desde o lado oriental até o ocidental, Aser terá uma porção.'),
('acf','ez',48,3,'E junto ao termo de Aser, desde o lado oriental até o ocidental, Naftali, uma porção.'),
('acf','ez',48,4,'E junto ao termo de Naftali, desde o lado oriental até o lado ocidental, Manassés, uma porção.'),
('acf','ez',48,5,'E junto ao termo de Manassés, desde o lado oriental até o lado ocidental, Efraim, uma porção.'),
('acf','ez',48,6,'E junto ao termo de Efraim, desde o lado oriental até o lado ocidental, Rúben, uma porção.'),
('acf','ez',48,7,'E junto ao termo de Rúben, desde o lado oriental até o lado ocidental, Judá, uma porção.'),
('acf','ez',48,8,'E junto ao termo de Judá, desde o lado oriental até o lado ocidental, será a oferta que haveis de fazer de vinte e cinco mil canas de largura, e de comprimento de cada uma das porções, desde o lado oriental até o lado ocidental; e o santuário estará no meio dela.'),
('acf','ez',48,9,'A oferta que haveis de oferecer ao Senhor será do comprimento de vinte e cinco mil canas, e da largura de dez mil.'),
('acf','ez',48,10,'E ali será a oferta santa para os sacerdotes, medindo para o norte vinte e cinco mil canas de comprimento, e para o ocidente dez mil de largura, e para o oriente dez mil de largura, e para o sul vinte e cinco mil de comprimento; e o santuário do Senhor estará no meio dela.'),
('acf','ez',48,11,'E será para os sacerdotes santificados dentre os filhos de Zadoque, que guardaram a minha ordenança, que não se desviaram, quando os filhos de Israel se extraviaram, como se extraviaram os outros levitas.'),
('acf','ez',48,12,'E eles terão uma oferta, da oferta da terra, lugar santíssimo, junto ao limite dos levitas.'),
('acf','ez',48,13,'E os levitas terão, consoante ao termo dos sacerdotes, vinte e cinco mil canas de comprimento, e de largura dez mil; todo o comprimento será vinte e cinco mil, e a largura dez mil.'),
('acf','ez',48,14,'E não venderão disto, nem trocarão, nem transferirão as primícias da terra, porque é santidade ao Senhor.'),
('acf','ez',48,15,'Mas as cinco mil canas, as que restaram da largura, diante das vinte e cinco mil, ficarão para uso comum, para a cidade, para habitação e para arrabaldes; e a cidade estará no meio delas.'),
('acf','ez',48,16,'E estas serão as suas medidas: o lado do norte de quatro mil e quinhentas canas, o lado do sul de quatro mil e quinhentas, o lado oriental de quatro mil e quinhentas e o lado ocidental de quatro mil e quinhentas.'),
('acf','ez',48,17,'E os arrabaldes da cidade serão para o norte de duzentas e cinqüenta canas, para o sul de duzentas e cinqüenta, para o oriente de duzentas e cinqüenta e para o ocidente de duzentas e cinqüenta.'),
('acf','ez',48,18,'E, quanto ao que restou do comprimento, consoante com a santa oferta, será dez mil para o oriente, e dez mil para o ocidente; e corresponderá à santa oferta; e a sua novidade será para sustento daqueles que servem a cidade.'),
('acf','ez',48,19,'E os que servem à cidade, servi-la-ão dentre todas as tribos de Israel.'),
('acf','ez',48,20,'Toda a oferta será de vinte e cinco mil canas com mais vinte e cinco mil; em quadrado oferecereis a oferta santa, com a possessão da cidade.'),
('acf','ez',48,21,'E o que restou será para o príncipe; deste e do outro lado da oferta santa, e da possessão da cidade, diante das vinte e cinco mil canas da oferta, até ao termo do oriente e do ocidente, diante das vinte e cinco mil, até ao termo do ocidente, correspondente às porções, será para o príncipe; e a santa oferta e o santuário da casa estarão no meio dela.'),
('acf','ez',48,22,'E desde a possessão dos levitas, e desde a possessão da cidade, no meio do que pertencer ao príncipe, entre o termo de Judá, e o termo de Benjamim, será isso para o príncipe.'),
('acf','ez',48,23,'E, quanto ao restante das tribos, desde o lado oriental até o lado ocidental, Benjamim terá uma porção.'),
('acf','ez',48,24,'E junto ao termo de Benjamim, desde o lado oriental até o lado ocidental, Simeão terá uma porção.'),
('acf','ez',48,25,'E junto ao termo de Simeão, desde o lado oriental até o lado ocidental, Issacar terá uma porção.'),
('acf','ez',48,26,'E junto ao termo de Issacar, desde o lado oriental até o lado ocidental, Zebulom terá uma porção.'),
('acf','ez',48,27,'E junto ao termo de Zebulom, desde o lado oriental até o lado ocidental, Gade terá uma porção.'),
('acf','ez',48,28,'E junto ao termo de Gade, ao sul, do lado sul, será o termo desde Tamar até às águas da contenda de Cades, junto ao rio até ao mar grande.'),
('acf','ez',48,29,'Esta é a terra que sorteareis em herança às tribos de Israel; e estas são as suas porções, diz o Senhor DEUS.'),
('acf','ez',48,30,'E estas são as saídas da cidade, desde o lado norte: quatro mil e quinhentas canas por medida.'),
('acf','ez',48,31,'E as portas da cidade serão conforme os nomes das tribos de Israel; três portas para o norte: a porta de Rúben uma, a porta de Judá outra, a porta de Levi outra.'),
('acf','ez',48,32,'E do lado oriental quatro mil e quinhentas canas, e três portas, a saber: a porta de José uma, a porta de Benjamim outra, a porta de Dã outra.'),
('acf','ez',48,33,'E do lado sul quatro mil e quinhentas canas por medida, e três portas: a porta de Simeão uma, a porta de Issacar outra, a porta de Zebulom outra.'),
('acf','ez',48,34,'Do lado ocidental quatro mil e quinhentas canas, e as suas três portas: a porta de Gade uma, a porta de Aser outra, a porta de Naftali outra.'),
('acf','ez',48,35,'Dezoito mil canas por medida terá ao redor; e o nome da cidade desde aquele dia será: o Senhor está ali.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','dn',1,1,'No ano terceiro do reinado de Jeoiaquim, rei de Judá, veio Nabucodonosor, rei de babilônia, a Jerusalém, e a sitiou.'),
('acf','dn',1,2,'E o Senhor entregou nas suas mãos a Jeoiaquim, rei de Judá, e uma parte dos utensílios da casa de Deus, e ele os levou para a terra de Sinar, para a casa do seu deus, e pôs os utensílios na casa do tesouro do seu deus.'),
('acf','dn',1,3,'E disse o rei a Aspenaz, chefe dos seus eunucos, que trouxesse alguns dos filhos de Israel, e da linhagem real e dos príncipes,'),
('acf','dn',1,4,'Jovens em quem não houvesse defeito algum, de boa aparência, e instruídos em toda a sabedoria, e doutos em ciência, e entendidos no conhecimento, e que tivessem habilidade para assistirem no palácio do rei, e que lhes ensinassem as letras e a língua dos caldeus.'),
('acf','dn',1,5,'E o rei lhes determinou a porção diária, das iguarias do rei, e do vinho que ele bebia, e que assim fossem mantidos por três anos, para que no fim destes pudessem estar diante do rei.'),
('acf','dn',1,6,'E entre eles se achavam, dos filhos de Judá, Daniel, Hananias, Misael e Azarias;'),
('acf','dn',1,7,'E o chefe dos eunucos lhes pôs outros nomes, a saber: a Daniel pôs o de Beltessazar, e a Hananias o de Sadraque, e a Misael o de Mesaque, e a Azarias o de Abednego.'),
('acf','dn',1,8,'E Daniel propôs no seu coração não se contaminar com a porção das iguarias do rei, nem com o vinho que ele bebia; portanto pediu ao chefe dos eunucos que lhe permitisse não se contaminar.'),
('acf','dn',1,9,'Ora, Deus fez com que Daniel achasse graça e misericórdia diante do chefe dos eunucos.'),
('acf','dn',1,10,'E disse o chefe dos eunucos a Daniel: Tenho medo do meu senhor, o rei, que determinou a vossa comida e a vossa bebida; pois por que veria ele os vossos rostos mais tristes do que os dos outros jovens da vossa idade? Assim porias em perigo a minha cabeça para com o rei.'),
('acf','dn',1,11,'Então disse Daniel ao despenseiro a quem o chefe dos eunucos havia constituído sobre Daniel, Hananias, Misael e Azarias:'),
('acf','dn',1,12,'Experimenta, peço-te, os teus servos dez dias, e que se nos dêem legumes a comer, e água a beber.'),
('acf','dn',1,13,'Então se examine diante de ti a nossa aparência, e a aparência dos jovens que comem a porção das iguarias do rei; e, conforme vires, procederás para com os teus servos.'),
('acf','dn',1,14,'E ele consentiu isto, e os experimentou dez dias.'),
('acf','dn',1,15,'E, ao fim dos dez dias, apareceram os seus semblantes melhores, e eles estavam mais gordos de carne do que todos os jovens que comiam das iguarias do rei.'),
('acf','dn',1,16,'Assim o despenseiro tirou-lhes a porção das iguarias, e o vinho de que deviam beber, e lhes dava legumes.'),
('acf','dn',1,17,'Quanto a estes quatro jovens, Deus lhes deu o conhecimento e a inteligência em todas as letras, e sabedoria; mas a Daniel deu entendimento em toda a visão e sonhos.'),
('acf','dn',1,18,'E ao fim dos dias, em que o rei tinha falado que os trouxessem, o chefe dos eunucos os trouxe diante de Nabucodonosor.'),
('acf','dn',1,19,'E o rei falou com eles; entre todos eles não foram achados outros tais como Daniel, Hananias, Misael e Azarias; portanto ficaram assistindo diante do rei.'),
('acf','dn',1,20,'E em toda a matéria de sabedoria e de discernimento, sobre o que o rei lhes perguntou, os achou dez vezes mais doutos do que todos os magos astrólogos que havia em todo o seu reino.'),
('acf','dn',1,21,'E Daniel permaneceu até ao primeiro ano do rei Ciro.'),
('acf','dn',2,1,'E no segundo ano do reinado de Nabucodonosor, Nabucodonosor teve sonhos; e o seu espírito se perturbou, e passou-se-lhe o sono.'),
('acf','dn',2,2,'Então o rei mandou chamar os magos, os astrólogos, os encantadores e os caldeus, para que declarassem ao rei os seus sonhos; e eles vieram e se apresentaram diante do rei.'),
('acf','dn',2,3,'E o rei lhes disse: Tive um sonho; e para saber o sonho está perturbado o meu espírito.'),
('acf','dn',2,4,'E os caldeus disseram ao rei em aramaico: Ó rei, vive eternamente! Dize o sonho a teus servos, e daremos a interpretação.'),
('acf','dn',2,5,'Respondeu o rei, e disse aos caldeus: O assunto me tem escapado; se não me fizerdes saber o sonho e a sua interpretação, sereis despedaçados, e as vossas casas serão feitas um monturo;'),
('acf','dn',2,6,'Mas se vós me declarardes o sonho e a sua interpretação, recebereis de mim dádivas, recompensas e grande honra; portanto declarai-me o sonho e a sua interpretação.'),
('acf','dn',2,7,'Responderam segunda vez, e disseram: Diga o rei o sonho a seus servos, e daremos a sua interpretação.'),
('acf','dn',2,8,'Respondeu o rei, e disse: Percebo muito bem que vós quereis ganhar tempo; porque vedes que o assunto me tem escapado.'),
('acf','dn',2,9,'De modo que, se não me fizerdes saber o sonho, uma só sentença será a vossa; pois vós preparastes palavras mentirosas e perversas para as proferirdes na minha presença, até que se mude o tempo; portanto dizei-me o sonho, para que eu entenda que me podeis dar a sua interpretação.'),
('acf','dn',2,10,'Responderam os caldeus na presença do rei, e disseram: Não há ninguém sobre a terra que possa declarar a palavra ao rei; pois nenhum rei há, grande ou dominador, que requeira coisas semelhantes de algum mago, ou astrólogo, ou caldeu.'),
('acf','dn',2,11,'Porque o assunto que o rei requer é difícil; e ninguém há que o possa declarar diante do rei, senão os deuses, cuja morada não é com a carne.'),
('acf','dn',2,12,'Por isso o rei muito se irou e enfureceu; e ordenou que matassem a todos os sábios de babilônia.'),
('acf','dn',2,13,'E saiu o decreto, segundo o qual deviam ser mortos os sábios; e buscaram a Daniel e aos seus companheiros, para que fossem mortos.'),
('acf','dn',2,14,'Então Daniel falou avisada e prudentemente a Arioque, capitão da guarda do rei, que tinha saído para matar os sábios de babilônia.'),
('acf','dn',2,15,'Respondeu, e disse a Arioque, capitão do rei: Por que se apressa tanto o decreto da parte do rei? Então Arioque explicou o caso a Daniel.'),
('acf','dn',2,16,'E Daniel entrou; e pediu ao rei que lhe desse tempo, para que lhe pudesse dar a interpretação.'),
('acf','dn',2,17,'Então Daniel foi para a sua casa, e fez saber o caso a Hananias, Misael e Azarias, seus companheiros;'),
('acf','dn',2,18,'Para que pedissem misericórdia ao Deus do céu, sobre este mistério, a fim de que Daniel e seus companheiros não perecessem, juntamente com o restante dos sábios da Babilônia.'),
('acf','dn',2,19,'Então foi revelado o mistério a Daniel numa visão de noite; então Daniel louvou o Deus do céu.'),
('acf','dn',2,20,'Falou Daniel, dizendo: Seja bendito o nome de Deus de eternidade a eternidade, porque dele são a sabedoria e a força;'),
('acf','dn',2,21,'E ele muda os tempos e as estações; ele remove os reis e estabelece os reis; ele dá sabedoria aos sábios e conhecimento aos entendidos.'),
('acf','dn',2,22,'Ele revela o profundo e o escondido; conhece o que está em trevas, e com ele mora a luz.'),
('acf','dn',2,23,'Ó Deus de meus pais, eu te dou graças e te louvo, porque me deste sabedoria e força; e agora me fizeste saber o que te pedimos, porque nos fizeste saber este assunto do rei.'),
('acf','dn',2,24,'Por isso Daniel foi ter com Arioque, ao qual o rei tinha constituído para matar os sábios de babilônia; entrou, e disse-lhe assim: Não mates os sábios de babilônia; introduze-me na presença do rei, e declararei ao rei a interpretação.'),
('acf','dn',2,25,'Então Arioque depressa introduziu a Daniel na presença do rei, e disse-lhe assim: Achei um homem dentre os cativos de Judá, o qual fará saber ao rei a interpretação.'),
('acf','dn',2,26,'Respondeu o rei, e disse a Daniel (cujo nome era Beltessazar): Podes tu fazer-me saber o sonho que tive e a sua interpretação?'),
('acf','dn',2,27,'Respondeu Daniel na presença do rei, dizendo: O segredo que o rei requer, nem sábios, nem astrólogos, nem magos, nem adivinhos o podem declarar ao rei;'),
('acf','dn',2,28,'Mas há um Deus no céu, o qual revela os mistérios; ele, pois, fez saber ao rei Nabucodonosor o que há de acontecer nos últimos dias; o teu sonho e as visões da tua cabeça que tiveste na tua cama são estes:'),
('acf','dn',2,29,'Estando tu, ó rei, na tua cama, subiram os teus pensamentos, acerca do que há de ser depois disto. Aquele, pois, que revela os mistérios te fez saber o que há de ser.'),
('acf','dn',2,30,'E a mim me foi revelado esse mistério, não porque haja em mim mais sabedoria que em todos os viventes, mas para que a interpretação se fizesse saber ao rei, e para que entendesses os pensamentos do teu coração.'),
('acf','dn',2,31,'Tu, ó rei, estavas vendo, e eis aqui uma grande estátua; esta estátua, que era imensa, cujo esplendor era excelente, e estava em pé diante de ti; e a sua aparência era terrível.'),
('acf','dn',2,32,'A cabeça daquela estátua era de ouro fino; o seu peito e os seus braços de prata; o seu ventre e as suas coxas de cobre;'),
('acf','dn',2,33,'As pernas de ferro; os seus pés em parte de ferro e em parte de barro.'),
('acf','dn',2,34,'Estavas vendo isto, quando uma pedra foi cortada, sem auxílio de mão, a qual feriu a estátua nos pés de ferro e de barro, e os esmiuçou.'),
('acf','dn',2,35,'Então foi juntamente esmiuçado o ferro, o barro, o bronze, a prata e o ouro, os quais se fizeram como pragana das eiras do estio, e o vento os levou, e não se achou lugar algum para eles; mas a pedra, que feriu a estátua, se tornou grande monte, e encheu toda a terra.'),
('acf','dn',2,36,'Este é o sonho; também a sua interpretação diremos na presença do rei.'),
('acf','dn',2,37,'Tu, ó rei, és rei de reis; a quem o Deus do céu tem dado o reino, o poder, a força, e a glória.'),
('acf','dn',2,38,'E onde quer que habitem os filhos de homens, na tua mão entregou os animais do campo, e as aves do céu, e fez que reinasse sobre todos eles; tu és a cabeça de ouro.'),
('acf','dn',2,39,'E depois de ti se levantará outro reino, inferior ao teu; e um terceiro reino, de bronze, o qual dominará sobre toda a terra.'),
('acf','dn',2,40,'E o quarto reino será forte como ferro; pois, como o ferro, esmiúça e quebra tudo; como o ferro que quebra todas as coisas, assim ele esmiuçará e fará em pedaços.'),
('acf','dn',2,41,'E, quanto ao que viste dos pés e dos dedos, em parte de barro de oleiro, e em parte de ferro, isso será um reino dividido; contudo haverá nele alguma coisa da firmeza do ferro, pois viste o ferro misturado com barro de lodo.'),
('acf','dn',2,42,'E como os dedos dos pés eram em parte de ferro e em parte de barro, assim por uma parte o reino será forte, e por outra será frágil.'),
('acf','dn',2,43,'Quanto ao que viste do ferro misturado com barro de lodo, misturar-se-ão com semente humana, mas não se ligarão um ao outro, assim como o ferro não se mistura com o barro.'),
('acf','dn',2,44,'Mas, nos dias desses reis, o Deus do céu levantará um reino que não será jamais destruído; e este reino não passará a outro povo; esmiuçará e consumirá todos esses reinos, mas ele mesmo subsistirá para sempre,'),
('acf','dn',2,45,'Da maneira que viste que do monte foi cortada uma pedra, sem auxílio de mãos, e ela esmiuçou o ferro, o bronze, o barro, a prata e o ouro; o grande Deus fez saber ao rei o que há de ser depois disto. Certo é o sonho, e fiel a sua interpretação.'),
('acf','dn',2,46,'Então o rei Nabucodonosor caiu sobre a sua face, e adorou a Daniel, e ordenou que lhe oferecessem uma oblação e perfumes suaves.'),
('acf','dn',2,47,'Respondeu o rei a Daniel, e disse: Certamente o vosso Deus é Deus dos deuses, e o Senhor dos reis e revelador de mistérios, pois pudeste revelar este mistério.'),
('acf','dn',2,48,'Então o rei engrandeceu a Daniel, e lhe deu muitas e grandes dádivas, e o pôs por governador de toda a província de babilônia, como também o fez chefe dos governadores sobre todos os sábios de babilônia.'),
('acf','dn',2,49,'E pediu Daniel ao rei, e constituiu ele sobre os negócios da província de babilônia a Sadraque, Mesaque e Abednego; mas Daniel permaneceu na porta do rei.'),
('acf','dn',3,1,'O rei Nabucodonosor fez uma estátua de ouro, cuja altura era de sessenta côvados, e a sua largura de seis côvados; levantou-a no campo de Dura, na província de babilônia.'),
('acf','dn',3,2,'Então o rei Nabucodonosor mandou reunir os príncipes, os prefeitos, os governadores, os conselheiros, os tesoureiros, os juízes, os capitàes, e todos os oficiais das províncias, para que viessem à consagração da estátua que o rei Nabucodonosor tinha levantado.'),
('acf','dn',3,3,'Então se reuniram os príncipes, os prefeitos e governadores, os capitàes, os juízes, os tesoureiros, os conselheiros, e todos os oficiais das províncias, à consagração da estátua que o rei Nabucodonosor tinha levantado; e estavam em pé diante da imagem que Nabucodonosor tinha levantado.'),
('acf','dn',3,4,'E o arauto apregoava em alta voz: Ordena-se a vós, ó povos, nações e línguas:'),
('acf','dn',3,5,'Quando ouvirdes o som da buzina, da flauta, da harpa, da sambuca, do saltério, da gaita de foles, e de toda a espécie de música, prostrar-vos-eis, e adorareis a estátua de ouro que o rei Nabucodonosor tem levantado.'),
('acf','dn',3,6,'E qualquer que não se prostrar e não a adorar, será na mesma hora lançado dentro da fornalha de fogo ardente.'),
('acf','dn',3,7,'Portanto, no mesmo instante em que todos os povos ouviram o som da buzina, da flauta, da harpa, da sambuca, do saltério e de toda a espécie de música, prostraram-se todos os povos, nações e línguas, e adoraram a estátua de ouro que o rei Nabucodonosor tinha levantado.'),
('acf','dn',3,8,'Por isso, no mesmo instante chegaram perto alguns caldeus, e acusaram os judeus.'),
('acf','dn',3,9,'E responderam, dizendo ao rei Nabucodonosor: Ó rei, vive eternamente!'),
('acf','dn',3,10,'Tu, ó rei, fizeste um decreto, pelo qual todo homem que ouvisse o som da buzina, da flauta, da harpa, da sambuca, do saltério, e da gaita de foles, e de toda a espécie de música, se prostrasse e adorasse a estátua de ouro;'),
('acf','dn',3,11,'E, qualquer que não se prostrasse e adorasse, seria lançado dentro da fornalha de fogo ardente.'),
('acf','dn',3,12,'Há uns homens judeus, os quais constituíste sobre os negócios da província de babilônia: Sadraque, Mesaque e Abednego; estes homens, ó rei, não fizeram caso de ti; a teus deuses não servem, nem adoram a estátua de ouro que levantaste.'),
('acf','dn',3,13,'Então Nabucodonosor, com ira e furor, mandou trazer a Sadraque, Mesaque e Abednego. E trouxeram a estes homens perante o rei.'),
('acf','dn',3,14,'Falou Nabucodonosor, e lhes disse: É de propósito, ó Sadraque, Mesaque e Abednego, que vós não servis a meus deuses nem adorais a estátua de ouro que levantei?'),
('acf','dn',3,15,'Agora, pois, se estais prontos, quando ouvirdes o som da buzina, da flauta, da harpa, da sambuca, do saltério, da gaita de foles, e de toda a espécie de música, para vos prostrardes e adorardes a estátua que fiz, bom é; mas, se não a adorardes, sereis lançados, na mesma hora, dentro da fornalha de fogo ardente. E quem é o Deus que vos poderá livrar das minhas mãos?'),
('acf','dn',3,16,'Responderam Sadraque, Mesaque e Abednego, e disseram ao rei Nabucodonosor: Não necessitamos de te responder sobre este negócio.'),
('acf','dn',3,17,'Eis que o nosso Deus, a quem nós servimos, é que nos pode livrar; ele nos livrará da fornalha de fogo ardente, e da tua mão, ó rei.'),
('acf','dn',3,18,'E, se não, fica sabendo ó rei, que não serviremos a teus deuses nem adoraremos a estátua de ouro que levantaste.'),
('acf','dn',3,19,'Então Nabucodonosor se encheu de furor, e mudou-se o aspecto do seu semblante contra Sadraque, Mesaque e Abednego; falou, e ordenou que a fornalha se aquecesse sete vezes mais do que se costumava aquecer.'),
('acf','dn',3,20,'E ordenou aos homens mais poderosos, que estavam no seu exército, que atassem a Sadraque, Mesaque e Abednego, para lançá-los na fornalha de fogo ardente.'),
('acf','dn',3,21,'Então estes homens foram atados, vestidos com as suas capas, suas túnicas, e seus chapéus, e demais roupas, e foram lançados dentro da fornalha de fogo ardente.'),
('acf','dn',3,22,'E, porque a palavra do rei era urgente, e a fornalha estava sobremaneira quente, a chama do fogo matou aqueles homens que carregaram a Sadraque, Mesaque, e Abednego.'),
('acf','dn',3,23,'E estes três homens, Sadraque, Mesaque e Abednego, caíram atados dentro da fornalha de fogo ardente.'),
('acf','dn',3,24,'Então o rei Nabucodonosor se espantou, e se levantou depressa; falou, dizendo aos seus conselheiros: Não lançamos nós, dentro do fogo, três homens atados? Responderam e disseram ao rei: É verdade, ó rei.'),
('acf','dn',3,25,'Respondeu, dizendo: Eu, porém, vejo quatro homens soltos, que andam passeando dentro do fogo, sem sofrer nenhum dano; e o aspecto do quarto é semelhante ao Filho de Deus.'),
('acf','dn',3,26,'Então chegando-se Nabucodonosor à porta da fornalha de fogo ardente, falou, dizendo: Sadraque, Mesaque e Abednego, servos do Deus Altíssimo, saí e vinde! Então Sadraque, Mesaque e Abednego saíram do meio do fogo.'),
('acf','dn',3,27,'E reuniram-se os príncipes, os capitàes, os governadores e os conselheiros do rei e, contemplando estes homens, viram que o fogo não tinha tido poder algum sobre os seus corpos; nem um só cabelo da sua cabeça se tinha queimado, nem as suas capas se mudaram, nem cheiro de fogo tinha passado sobre eles.'),
('acf','dn',3,28,'Falou Nabucodonosor, dizendo: Bendito seja o Deus de Sadraque, Mesaque e Abednego, que enviou o seu anjo, e livrou os seus servos, que confiaram nele, pois violaram a palavra do rei, preferindo entregar os seus corpos, para que não servissem nem adorassem algum outro deus, senão o seu Deus.'),
('acf','dn',3,29,'Por mim, pois, é feito um decreto, pelo qual todo o povo, e nação e língua que disser blasfêmia contra o Deus de Sadraque, Mesaque e Abednego, seja despedaçado, e as suas casas sejam feitas um monturo; porquanto não há outro Deus que possa livrar como este.'),
('acf','dn',3,30,'Então o rei fez prosperar a Sadraque, Mesaque e Abednego, na província de babilônia.'),
('acf','dn',4,1,'Nabucodonosor rei, a todos os povos, nações e línguas, que moram em toda a terra: Paz vos seja multiplicada.'),
('acf','dn',4,2,'Pareceu-me bem fazer conhecidos os sinais e maravilhas que Deus, o Altíssimo, tem feito para comigo.'),
('acf','dn',4,3,'Quão grandes são os seus sinais, e quão poderosas as suas maravilhas! O seu reino é um reino sempiterno, e o seu domínio de geração em geração.'),
('acf','dn',4,4,'Eu, Nabucodonosor, estava sossegado em minha casa, e próspero no meu palácio.'),
('acf','dn',4,5,'Tive um sonho, que me espantou; e estando eu na minha cama, as imaginações e as visões da minha cabeça me turbaram.'),
('acf','dn',4,6,'Por isso expedi um decreto, para que fossem introduzidos à minha presença todos os sábios de babilônia, para que me fizessem saber a interpretação do sonho.'),
('acf','dn',4,7,'Então entraram os magos, os astrólogos, os caldeus e os adivinhadores, e eu contei o sonho diante deles; mas não me fizeram saber a sua interpretação.'),
('acf','dn',4,8,'Mas por fim entrou na minha presença Daniel, cujo nome é Beltessazar, segundo o nome do meu deus, e no qual há o espírito dos deuses santos; e eu lhe contei o sonho, dizendo:'),
('acf','dn',4,9,'Beltessazar, mestre dos magos, pois eu sei que há em ti o espírito dos deuses santos, e nenhum mistério te é difícil, dize-me as visões do meu sonho que tive e a sua interpretação.'),
('acf','dn',4,10,'Eis, pois, as visões da minha cabeça, estando eu na minha cama: Eu estava assim olhando, e vi uma árvore no meio da terra, cuja altura era grande;'),
('acf','dn',4,11,'Crescia esta árvore, e se fazia forte, de maneira que a sua altura chegava até ao céu; e era vista até aos confins da terra.'),
('acf','dn',4,12,'A sua folhagem era formosa, e o seu fruto abundante, e havia nela sustento para todos; debaixo dela os animais do campo achavam sombra, e as aves do céu faziam morada nos seus ramos, e toda a carne se mantinha dela.'),
('acf','dn',4,13,'Estava vendo isso nas visões da minha cabeça, estando eu na minha cama; e eis que um vigia, um santo, descia do céu,'),
('acf','dn',4,14,'Clamando fortemente, e dizendo assim: Derrubai a árvore, e cortai-lhe os ramos, sacudi as suas folhas, espalhai o seu fruto; afugentem-se os animais de debaixo dela, e as aves dos seus ramos.'),
('acf','dn',4,15,'Mas deixai na terra o tronco com as suas raízes, atada com cadeias de ferro e de bronze, na erva do campo; e seja molhado do orvalho do céu, e seja a sua porção com os animais na erva da terra;'),
('acf','dn',4,16,'Seja mudado o seu coração, para que não seja mais coração de homem, e lhe seja dado coração de animal; e passem sobre ele sete tempos.'),
('acf','dn',4,17,'Esta sentença é por decreto dos vigias, e esta ordem por mandado dos santos, a fim de que conheçam os viventes que o Altíssimo tem domínio sobre o reino dos homens, e o dá a quem quer, e até ao mais humilde dos homens constitui sobre ele.'),
('acf','dn',4,18,'Este sonho eu, rei Nabucodonosor vi. Tu, pois, Beltessazar, dize a interpretação, porque todos os sábios do meu reino não puderam fazer-me saber a sua interpretação, mas tu podes; pois há em ti o espírito dos deuses santos.'),
('acf','dn',4,19,'Então Daniel, cujo nome era Beltessazar, esteve atônito por uma hora, e os seus pensamentos o turbavam; falou, pois, o rei, dizendo: Beltessazar, não te espante o sonho, nem a sua interpretação. Respondeu Beltessazar, dizendo: Senhor meu, seja o sonho contra os que te têm ódio, e a sua interpretação aos teus inimigos.'),
('acf','dn',4,20,'A árvore que viste, que cresceu, e se fez forte, cuja altura chegava até ao céu, e que foi vista por toda a terra;'),
('acf','dn',4,21,'Cujas folhas eram formosas, e o seu fruto abundante, e em que para todos havia sustento, debaixo da qual moravam os animais do campo, e em cujos ramos habitavam as aves do céu;'),
('acf','dn',4,22,'És tu, ó rei, que cresceste, e te fizeste forte; a tua grandeza cresceu, e chegou até ao céu, e o teu domínio até à extremidade da terra.'),
('acf','dn',4,23,'E quanto ao que viu o rei, um vigia, um santo, que descia do céu, e dizia: Cortai a árvore, e destruí-a, mas o tronco com as suas raízes deixai na terra, e atada com cadeias de ferro e de bronze, na erva do campo; e seja molhado do orvalho do céu, e a sua porção seja com os animais do campo, até que passem sobre ele sete tempos;'),
('acf','dn',4,24,'Esta é a interpretação, ó rei; e este é o decreto do Altíssimo, que virá sobre o rei, meu senhor:'),
('acf','dn',4,25,'Serás tirado dentre os homens, e a tua morada será com os animais do campo, e te farão comer erva como os bois, e serás molhado do orvalho do céu; e passar-se-ão sete tempos por cima de ti; até que conheças que o Altíssimo tem domínio sobre o reino dos homens, e o dá a quem quer.'),
('acf','dn',4,26,'E quanto ao que foi falado, que deixassem o tronco com as raízes da árvore, o teu reino voltará para ti, depois que tiveres conhecido que o céu reina.'),
('acf','dn',4,27,'Portanto, ó rei, aceita o meu conselho, e põe fim aos teus pecados, praticando a justiça, e às tuas iniqüidades, usando de misericórdia com os pobres, pois, talvez se prolongue a tua tranqüilidade.'),
('acf','dn',4,28,'Todas estas coisas vieram sobre o rei Nabucodonosor.'),
('acf','dn',4,29,'Ao fim de doze meses, quando passeava no palácio real de babilônia,'),
('acf','dn',4,30,'Falou o rei, dizendo: Não é esta a grande babilônia que eu edifiquei para a casa real, com a força do meu poder, e para glória da minha magnificência?'),
('acf','dn',4,31,'Ainda estava a palavra na boca do rei, quando caiu uma voz do céu: A ti se diz, ó rei Nabucodonosor: Passou de ti o reino.'),
('acf','dn',4,32,'E serás tirado dentre os homens, e a tua morada será com os animais do campo; far-te-ão comer erva como os bois, e passar-se-ão sete tempos sobre ti, até que conheças que o Altíssimo domina sobre o reino dos homens, e o dá a quem quer.'),
('acf','dn',4,33,'Na mesma hora se cumpriu a palavra sobre Nabucodonosor, e foi tirado dentre os homens, e comia erva como os bois, e o seu corpo foi molhado do orvalho do céu, até que lhe cresceu pêlo, como as penas da águia, e as suas unhas como as das aves.'),
('acf','dn',4,34,'Mas ao fim daqueles dias eu, Nabucodonosor, levantei os meus olhos ao céu, e tornou-me a vir o entendimento, e eu bendisse o Altíssimo, e louvei e glorifiquei ao que vive para sempre, cujo domínio é um domínio sempiterno, e cujo reino é de geração em geração.'),
('acf','dn',4,35,'E todos os moradores da terra são reputados em nada, e segundo a sua vontade ele opera com o exército do céu e os moradores da terra; não há quem possa estorvar a sua mão, e lhe diga: Que fazes?'),
('acf','dn',4,36,'No mesmo tempo tornou a mim o meu entendimento, e para a dignidade do meu reino tornou-me a vir a minha majestade e o meu resplendor; e buscaram-me os meus conselheiros e os meus senhores; e fui restabelecido no meu reino, e a minha glória foi aumentada.'),
('acf','dn',4,37,'Agora, pois, eu, Nabucodonosor, louvo, exalço e glorifico ao Rei do céu; porque todas as suas obras são verdade, e os seus caminhos juízo, e pode humilhar aos que andam na soberba.'),
('acf','dn',5,1,'O rei Belsazar deu um grande banquete a mil dos seus senhores, e bebeu vinho na presença dos mil.'),
('acf','dn',5,2,'Havendo Belsazar provado o vinho, mandou trazer os vasos de ouro e de prata, que Nabucodonosor, seu pai, tinha tirado do templo que estava em Jerusalém, para que bebessem neles o rei, os seus príncipes, as suas mulheres e concubinas.'),
('acf','dn',5,3,'Então trouxeram os vasos de ouro, que foram tirados do templo da casa de Deus, que estava em Jerusalém, e beberam neles o rei, os seus príncipes, as suas mulheres e concubinas.'),
('acf','dn',5,4,'Beberam o vinho, e deram louvores aos deuses de ouro, de prata, de bronze, de ferro, de madeira, e de pedra.'),
('acf','dn',5,5,'Na mesma hora apareceram uns dedos de mão de homem, e escreviam, defronte do castiçal, na caiadura da parede do palácio real; e o rei via a parte da mão que estava escrevendo.'),
('acf','dn',5,6,'Mudou-se então o semblante do rei, e os seus pensamentos o turbaram; as juntas dos seus lombos se relaxaram, e os seus joelhos batiam um no outro.'),
('acf','dn',5,7,'E gritou o rei com força, que se introduzissem os astrólogos, os caldeus e os adivinhadores; e falou o rei, dizendo aos sábios de babilônia: Qualquer que ler este escrito, e me declarar a sua interpretação, será vestido de púrpura, e trará uma cadeia de ouro ao pescoço e, no reino, será o terceiro governante.'),
('acf','dn',5,8,'Então entraram todos os sábios do rei; mas não puderam ler o escrito, nem fazer saber ao rei a sua interpretação.'),
('acf','dn',5,9,'Então o rei Belsazar perturbou-se muito, e mudou-se-lhe o semblante; e os seus senhores estavam sobressaltados.'),
('acf','dn',5,10,'A rainha, por causa das palavras do rei e dos seus senhores, entrou na casa do banquete, e respondeu, dizendo: Ó rei, vive para sempre! Não te perturbem os teus pensamentos, nem se mude o teu semblante.'),
('acf','dn',5,11,'Há no teu reino um homem, no qual há o espírito dos deuses santos; e nos dias de teu pai se achou nele luz, e inteligência, e sabedoria, como a sabedoria dos deuses; e teu pai, o rei Nabucodonosor, sim, teu pai, o rei, o constituiu mestre dos magos, dos astrólogos, dos caldeus e dos adivinhadores;'),
('acf','dn',5,12,'Porquanto se achou neste Daniel um espírito excelente, e conhecimento, e entendimento, interpretando sonhos e explicando enigmas, e resolvendo dúvidas, ao qual o rei pôs o nome de Beltessazar. Chame-se, pois, agora Daniel, e ele dará a interpretação.'),
('acf','dn',5,13,'Então Daniel foi introduzido à presença do rei. Falou o rei, dizendo a Daniel: És tu aquele Daniel, um dos filhos dos cativos de Judá, que o rei, meu pai, trouxe de Judá?'),
('acf','dn',5,14,'Tenho ouvido dizer a teu respeito que o espírito dos deuses está em ti, e que em ti se acham a luz, e o entendimento e a excelente sabedoria.'),
('acf','dn',5,15,'Agora mesmo foram introduzidos à minha presença os sábios e os astrólogos, para lerem este escrito, e me fazerem saber a sua interpretação; mas não puderam dar a interpretação destas palavras.'),
('acf','dn',5,16,'Eu, porém, tenho ouvido dizer de ti que podes dar interpretação e resolver dúvidas. Agora, se puderes ler este escrito, e fazer-me saber a sua interpretação, serás vestido de púrpura, e terás cadeia de ouro ao pescoço e no reino serás o terceiro governante.'),
('acf','dn',5,17,'Então respondeu Daniel, e disse na presença do rei: As tuas dádivas fiquem contigo, e dá os teus prêmios a outro; contudo lerei ao rei o escrito, e far-lhe-ei saber a interpretação.'),
('acf','dn',5,18,'Ó rei! Deus, o Altíssimo, deu a Nabucodonosor, teu pai, o reino, e a grandeza, e a glória, e a majestade.'),
('acf','dn',5,19,'E por causa da grandeza, que lhe deu, todos os povos, nações e línguas tremiam e temiam diante dele; a quem queria matava, e a quem queria conservava em vida; e a quem queria engrandecia, e a quem queria abatia.'),
('acf','dn',5,20,'Mas quando o seu coração se exaltou, e o seu espírito se endureceu em soberba, foi derrubado do seu trono real, e passou dele a sua glória.'),
('acf','dn',5,21,'E foi tirado dentre os filhos dos homens, e o seu coração foi feito semelhante ao dos animais, e a sua morada foi com os jumentos monteses; fizeram-no comer a erva como os bois, e do orvalho do céu foi molhado o seu corpo, até que conheceu que Deus, o Altíssimo, tem domínio sobre o reino dos homens, e a quem quer constitui sobre ele.'),
('acf','dn',5,22,'E tu, Belsazar, que és seu filho, não humilhaste o teu coração, ainda que soubeste tudo isto.'),
('acf','dn',5,23,'E te levantaste contra o Senhor do céu, pois foram trazidos à tua presença os vasos da casa dele, e tu, os teus senhores, as tuas mulheres e as tuas concubinas, bebestes vinho neles; além disso, deste louvores aos deuses de prata, de ouro, de bronze, de ferro, de madeira e de pedra, que não vêem, não ouvem, nem sabem; mas a Deus, em cuja mão está a tua vida, e de quem são todos os teus caminhos, a ele não glorificaste.'),
('acf','dn',5,24,'Então dele foi enviada aquela parte da mão, que escreveu este escrito.'),
('acf','dn',5,25,'Este, pois, é o escrito que se escreveu: MENE, MENE, TEQUEL, UFARSIM.'),
('acf','dn',5,26,'Esta é a interpretação daquilo: MENE: Contou Deus o teu reino, e o acabou.'),
('acf','dn',5,27,'TEQUEL: Pesado foste na balança, e foste achado em falta.'),
('acf','dn',5,28,'PERES: Dividido foi o teu reino, e dado aos medos e aos persas.'),
('acf','dn',5,29,'Então mandou Belsazar que vestissem a Daniel de púrpura, e que lhe pusessem uma cadeia de ouro ao pescoço, e proclamassem a respeito dele que havia de ser o terceiro no governo do seu reino.'),
('acf','dn',5,30,'Naquela noite foi morto Belsazar, rei dos caldeus.'),
('acf','dn',5,31,'E Dario, o medo, ocupou o reino, sendo da idade de sessenta e dois anos.'),
('acf','dn',6,1,'E pareceu bem a Dario constituir sobre o reino cento e vinte príncipes, que estivessem sobre todo o reino;'),
('acf','dn',6,2,'E sobre eles três presidentes, dos quais Daniel era um, aos quais estes príncipes dessem conta, para que o rei não sofresse dano.'),
('acf','dn',6,3,'Então o mesmo Daniel sobrepujou a estes presidentes e príncipes; porque nele havia um espírito excelente; e o rei pensava constituí-lo sobre todo o reino.'),
('acf','dn',6,4,'Então os presidentes e os príncipes procuravam achar ocasião contra Daniel a respeito do reino; mas não podiam achar ocasião ou culpa alguma; porque ele era fiel, e não se achava nele nenhum erro nem culpa.'),
('acf','dn',6,5,'Então estes homens disseram: Nunca acharemos ocasião alguma contra este Daniel, se não a acharmos contra ele na lei do seu Deus.'),
('acf','dn',6,6,'Então estes presidentes e príncipes foram juntos ao rei, e disseram-lhe assim: Ó rei Dario, vive para sempre!'),
('acf','dn',6,7,'Todos os presidentes do reino, os capitàes e príncipes, conselheiros e governadores, concordaram em promulgar um edito real e confirmar a proibição que qualquer que, por espaço de trinta dias, fizer uma petição a qualquer deus, ou a qualquer homem, e não a ti, ó rei, seja lançado na cova dos leões.'),
('acf','dn',6,8,'Agora, pois, ó rei, confirma a proibição, e assina o edito, para que não seja mudado, conforme a lei dos medos e dos persas, que não se pode revogar.'),
('acf','dn',6,9,'Por esta razão o rei Dario assinou o edito e a proibição.'),
('acf','dn',6,10,'Daniel, pois, quando soube que o edito estava assinado, entrou em sua casa (ora havia no seu quarto janelas abertas do lado de Jerusalém), e três vezes no dia se punha de joelhos, e orava, e dava graças diante do seu Deus, como também antes costumava fazer.'),
('acf','dn',6,11,'Então aqueles homens foram juntos, e acharam a Daniel orando e suplicando diante do seu Deus.'),
('acf','dn',6,12,'Então se apresentaram ao rei e, a respeito do edito real, disseram-lhe: Porventura não assinaste o edito, pelo qual todo o homem que fizesse uma petição a qualquer deus, ou a qualquer homem, por espaço de trinta dias, e não a ti, ó rei, fosse lançado na cova dos leões? Respondeu o rei, dizendo: Esta palavra é certa, conforme a lei dos medos e dos persas, que não se pode revogar.'),
('acf','dn',6,13,'Então responderam ao rei, dizendo-lhe: Daniel, que é dos filhos dos cativos de Judá, não tem feito caso de ti, ó rei, nem do edito que assinaste, antes três vezes por dia faz a sua oração.'),
('acf','dn',6,14,'Ouvindo então o rei essas palavras, ficou muito penalizado, e a favor de Daniel propôs dentro do seu coração livrá-lo; e até ao pôr do sol trabalhou para salvá-lo.'),
('acf','dn',6,15,'Então aqueles homens foram juntos ao rei, e disseram-lhe: Sabe, ó rei, que é lei dos medos e dos persas que nenhum edito ou decreto, que o rei estabeleça, se pode mudar.'),
('acf','dn',6,16,'Então o rei ordenou que trouxessem a Daniel, e lançaram-no na cova dos leões. E, falando o rei, disse a Daniel: O teu Deus, a quem tu continuamente serves, ele te livrará.'),
('acf','dn',6,17,'E foi trazida uma pedra e posta sobre a boca da cova; e o rei a selou com o seu anel e com o anel dos seus senhores, para que não se mudasse a sentença acerca de Daniel.'),
('acf','dn',6,18,'Então o rei se dirigiu para o seu palácio, e passou a noite em jejum, e não deixou trazer à sua presença instrumentos de música; e fugiu dele o sono.'),
('acf','dn',6,19,'Pela manhã, ao romper do dia, levantou-se o rei, e foi com pressa à cova dos leões.'),
('acf','dn',6,20,'E, chegando-se à cova, chamou por Daniel com voz triste; e disse o rei a Daniel: Daniel, servo do Deus vivo, dar-se-ia o caso que o teu Deus, a quem tu continuamente serves, tenha podido livrar-te dos leões?'),
('acf','dn',6,21,'Então Daniel falou ao rei: Ó rei, vive para sempre!'),
('acf','dn',6,22,'O meu Deus enviou o seu anjo, e fechou a boca dos leões, para que não me fizessem dano, porque foi achada em mim inocência diante dele; e também contra ti, ó rei, não tenho cometido delito algum.'),
('acf','dn',6,23,'Então o rei muito se alegrou em si mesmo, e mandou tirar a Daniel da cova. Assim foi tirado Daniel da cova, e nenhum dano se achou nele, porque crera no seu Deus.'),
('acf','dn',6,24,'E ordenou o rei, e foram trazidos aqueles homens que tinham acusado a Daniel, e foram lançados na cova dos leões, eles, seus filhos e suas mulheres; e ainda não tinham chegado ao fundo da cova quando os leões se apoderaram deles, e lhes esmigalharam todos os ossos.'),
('acf','dn',6,25,'Então o rei Dario escreveu a todos os povos, nações e línguas que moram em toda a terra: A paz vos seja multiplicada.'),
('acf','dn',6,26,'Da minha parte é feito um decreto, pelo qual em todo o domínio do meu reino os homens tremam e temam perante o Deus de Daniel; porque ele é o Deus vivo e que permanece para sempre, e o seu reino não se pode destruir, e o seu domínio durará até o fim.'),
('acf','dn',6,27,'Ele salva, livra, e opera sinais e maravilhas no céu e na terra; ele salvou e livrou Daniel do poder dos leões.'),
('acf','dn',6,28,'Este Daniel, pois, prosperou no reinado de Dario, e no reinado de Ciro, o persa.'),
('acf','dn',7,1,'No primeiro ano de Belsazar, rei de babilônia, teve Daniel um sonho e visões da sua cabeça quando estava na sua cama; escreveu logo o sonho, e relatou a suma das coisas.'),
('acf','dn',7,2,'Falou Daniel, e disse: Eu estava olhando na minha visão da noite, e eis que os quatro ventos do céu agitavam o mar grande.'),
('acf','dn',7,3,'E quatro animais grandes, diferentes uns dos outros, subiam do mar.'),
('acf','dn',7,4,'O primeiro era como leão, e tinha asas de águia; enquanto eu olhava, foram-lhe arrancadas as asas, e foi levantado da terra, e posto em pé como um homem, e foi-lhe dado um coração de homem.'),
('acf','dn',7,5,'Continuei olhando, e eis aqui o segundo animal, semelhante a um urso, o qual se levantou de um lado, tendo na boca três costelas entre os seus dentes; e foi-lhe dito assim: Levanta-te, devora muita carne.'),
('acf','dn',7,6,'Depois disto, eu continuei olhando, e eis aqui outro, semelhante a um leopardo, e tinha quatro asas de ave nas suas costas; tinha também este animal quatro cabeças, e foi-lhe dado domínio.'),
('acf','dn',7,7,'Depois disto eu continuei olhando nas visões da noite, e eis aqui o quarto animal, terrível e espantoso, e muito forte, o qual tinha dentes grandes de ferro; ele devorava e fazia em pedaços, e pisava aos pés o que sobejava; era diferente de todos os animais que apareceram antes dele, e tinha dez chifres.'),
('acf','dn',7,8,'Estando eu a considerar os chifres, eis que, entre eles subiu outro chifre pequeno, diante do qual três dos primeiros chifres foram arrancados; e eis que neste chifre havia olhos, como os de homem, e uma boca que falava grandes coisas.'),
('acf','dn',7,9,'Eu continuei olhando, até que foram postos uns tronos, e um ancião de dias se assentou; a sua veste era branca como a neve, e o cabelo da sua cabeça como a pura lã; e seu trono era de chamas de fogo, e as suas rodas de fogo ardente.'),
('acf','dn',7,10,'Um rio de fogo manava e saía de diante dele; milhares de milhares o serviam, e milhões de milhões assistiam diante dele; assentou-se o juízo, e abriram-se os livros.'),
('acf','dn',7,11,'Então estive olhando, por causa da voz das grandes palavras que o chifre proferia; estive olhando até que o animal foi morto, e o seu corpo desfeito, e entregue para ser queimado pelo fogo;'),
('acf','dn',7,12,'E, quanto aos outros animais, foi-lhes tirado o domínio; todavia foi-lhes prolongada a vida até certo espaço de tempo.'),
('acf','dn',7,13,'Eu estava olhando nas minhas visões da noite, e eis que vinha nas nuvens do céu um como o filho do homem; e dirigiu-se ao ancião de dias, e o fizeram chegar até ele.'),
('acf','dn',7,14,'E foi-lhe dado o domínio, e a honra, e o reino, para que todos os povos, nações e línguas o servissem; o seu domínio é um domínio eterno, que não passará, e o seu reino tal, que não será destruído.'),
('acf','dn',7,15,'Quanto a mim, Daniel, o meu espírito foi abatido dentro do corpo, e as visões da minha cabeça me perturbaram.'),
('acf','dn',7,16,'Cheguei-me a um dos que estavam perto, e pedi-lhe a verdade acerca de tudo isto. E ele me disse, e fez-me saber a interpretação das coisas.'),
('acf','dn',7,17,'Estes grandes animais, que são quatro, são quatro reis, que se levantarão da terra.'),
('acf','dn',7,18,'Mas os santos do Altíssimo receberão o reino, e o possuirão para todo o sempre, e de eternidade em eternidade.'),
('acf','dn',7,19,'Então tive desejo de conhecer a verdade a respeito do quarto animal, que era diferente de todos os outros, muito terrível, cujos dentes eram de ferro e as suas unhas de bronze; que devorava, fazia em pedaços e pisava aos pés o que sobrava;'),
('acf','dn',7,20,'E também a respeito dos dez chifres que tinha na cabeça, e do outro que subiu, e diante do qual caíram três, isto é, daquele que tinha olhos, e uma boca que falava grandes coisas, e cujo parecer era mais robusto do que o dos seus companheiros.'),
('acf','dn',7,21,'Eu olhava, e eis que este chifre fazia guerra contra os santos, e prevaleceu contra eles.'),
('acf','dn',7,22,'Até que veio o ancião de dias, e fez justiça aos santos do Altíssimo; e chegou o tempo em que os santos possuíram o reino.'),
('acf','dn',7,23,'Disse assim: O quarto animal será o quarto reino na terra, o qual será diferente de todos os reinos; e devorará toda a terra, e a pisará aos pés, e a fará em pedaços.'),
('acf','dn',7,24,'E, quanto aos dez chifres, daquele mesmo reino se levantarão dez reis; e depois deles se levantará outro, o qual será diferente dos primeiros, e abaterá a três reis.'),
('acf','dn',7,25,'E proferirá palavras contra o Altíssimo, e destruirá os santos do Altíssimo, e cuidará em mudar os tempos e a lei; e eles serão entregues na sua mão, por um tempo, e tempos, e a metade de um tempo.'),
('acf','dn',7,26,'Mas o juízo será estabelecido, e eles tirarão o seu domínio, para o destruir e para o desfazer até ao fim.'),
('acf','dn',7,27,'E o reino, e o domínio, e a majestade dos reinos debaixo de todo o céu serão dados ao povo dos santos do Altíssimo; o seu reino será um reino eterno, e todos os domínios o servirão, e lhe obedecerão.'),
('acf','dn',7,28,'Aqui terminou o assunto. Quanto a mim, Daniel, os meus pensamentos muito me perturbaram, e mudou-se em mim o meu semblante; mas guardei o assunto no meu coração.'),
('acf','dn',8,1,'No ano terceiro do reinado do rei Belsazar apareceu-me uma visão, a mim, Daniel, depois daquela que me apareceu no princípio.'),
('acf','dn',8,2,'E vi na visão; e sucedeu que, quando vi, eu estava na cidadela de Susã, na província de Elão; vi, pois, na visão, que eu estava junto ao rio Ulai.'),
('acf','dn',8,3,'E levantei os meus olhos, e vi, e eis que um carneiro estava diante do rio, o qual tinha dois chifres; e os dois chifres eram altos, mas um era mais alto do que o outro; e o mais alto subiu por último.'),
('acf','dn',8,4,'Vi que o carneiro dava marradas para o ocidente, e para o norte e para o sul; e nenhum dos animais lhe podia resistir; nem havia quem pudesse livrar-se da sua mão; e ele fazia conforme a sua vontade, e se engrandecia.'),
('acf','dn',8,5,'E, estando eu considerando, eis que um bode vinha do ocidente sobre toda a terra, mas sem tocar no chão; e aquele bode tinha um chifre insigne entre os olhos.'),
('acf','dn',8,6,'E dirigiu-se ao carneiro que tinha os dois chifres, ao qual eu tinha visto em pé diante do rio, e correu contra ele no ímpeto da sua força.'),
('acf','dn',8,7,'E vi-o chegar perto do carneiro, enfurecido contra ele, e ferindo-o quebrou-lhe os dois chifres, pois não havia força no carneiro para lhe resistir, e o bode o lançou por terra, e o pisou aos pés; não houve quem pudesse livrar o carneiro da sua mão.'),
('acf','dn',8,8,'E o bode se engrandeceu sobremaneira; mas, estando na sua maior força, aquele grande chifre foi quebrado; e no seu lugar subiram outros quatro também insignes, para os quatro ventos do céu.'),
('acf','dn',8,9,'E de um deles saiu um chifre muito pequeno, o qual cresceu muito para o sul, e para o oriente, e para a terra formosa.'),
('acf','dn',8,10,'E se engrandeceu até contra o exército do céu; e a alguns do exército, e das estrelas, lançou por terra, e os pisou.'),
('acf','dn',8,11,'E se engrandeceu até contra o príncipe do exército; e por ele foi tirado o sacrifício contínuo, e o lugar do seu santuário foi lançado por terra.'),
('acf','dn',8,12,'E um exército foi dado contra o sacrifício contínuo, por causa da transgressão; e lançou a verdade por terra, e o fez, e prosperou.'),
('acf','dn',8,13,'Depois ouvi um santo que falava; e disse outro santo àquele que falava: Até quando durará a visão do sacrifício contínuo, e da transgressão assoladora, para que sejam entregues o santuário e o exército, a fim de serem pisados?'),
('acf','dn',8,14,'E ele me disse: Até duas mil e trezentas tardes e manhãs; e o santuário será purificado.'),
('acf','dn',8,15,'E aconteceu que, havendo eu, Daniel, tido a visão, procurei o significado, e eis que se apresen- tou diante de mim como que uma semelhança de homem.'),
('acf','dn',8,16,'E ouvi uma voz de homem entre as margens do Ulai, a qual gritou, e disse: Gabriel, dá a entender a este a visão.'),
('acf','dn',8,17,'E veio perto de onde eu estava; e, vindo ele, me amedrontei, e caí sobre o meu rosto; mas ele me disse: Entende, filho do homem, porque esta visão acontecerá no fim do tempo.'),
('acf','dn',8,18,'E, estando ele falando comigo, caí adormecido com o rosto em terra; ele, porém, me tocou, e me fez estar em pé.'),
('acf','dn',8,19,'E disse: Eis que te farei saber o que há de acontecer no último tempo da ira; pois isso pertence ao tempo determinado do fim.'),
('acf','dn',8,20,'Aquele carneiro que viste com dois chifres são os reis da Média e da Pérsia,'),
('acf','dn',8,21,'Mas o bode peludo é o rei da Grécia; e o grande chifre que tinha entre os olhos é o primeiro rei;'),
('acf','dn',8,22,'O ter sido quebrado, levantando-se quatro em lugar dele, significa que quatro reinos se levantarão da mesma nação, mas não com a força dele.'),
('acf','dn',8,23,'Mas, no fim do seu reinado, quando acabarem os prevaricadores, se levantará um rei, feroz de semblante, e será entendido em adivinhações.'),
('acf','dn',8,24,'E se fortalecerá o seu poder, mas não pela sua própria força; e destruirá maravilhosamente, e prosperará, e fará o que lhe aprouver; e destruirá os poderosos e o povo santo.'),
('acf','dn',8,25,'E pelo seu entendimento também fará prosperar o engano na sua mão; e no seu coração se engrandecerá, e destruirá a muitos que vivem em segurança; e se levantará contra o Príncipe dos príncipes, mas sem mão será quebrado.'),
('acf','dn',8,26,'E a visão da tarde e da manhã que foi falada, é verdadeira. Tu, porém, cerra a visão, porque se refere a dias muito distantes.'),
('acf','dn',8,27,'E eu, Daniel, enfraqueci, e estive enfermo alguns dias; então levantei-me e tratei do negócio do rei. E espantei-me acerca da visão, e não havia quem a entendesse.'),
('acf','dn',9,1,'No ano primeiro de Dario, filho de Assuero, da linhagem dos medos, o qual foi constituído rei sobre o reino dos caldeus,'),
('acf','dn',9,2,'No primeiro ano do seu reinado, eu, Daniel, entendi pelos livros que o número dos anos, de que falara o Senhor ao profeta Jeremias, em que haviam de cumprir-se as desolações de Jerusalém, era de setenta anos.'),
('acf','dn',9,3,'E eu dirigi o meu rosto ao Senhor Deus, para o buscar com oração e súplicas, com jejum, e saco e cinza.'),
('acf','dn',9,4,'E orei ao Senhor meu Deus, e confessei, e disse: Ah! Senhor! Deus grande e tremendo, que guardas a aliança e a misericórdia para com os que te amam e guardam os teus mandamentos;'),
('acf','dn',9,5,'Pecamos, e cometemos iniqüidades, e procedemos impiamente, e fomos rebeldes, apartando-nos dos teus mandamentos e dos teus juízos;'),
('acf','dn',9,6,'E não demos ouvidos aos teus servos, os profetas, que em teu nome falaram aos nossos reis, aos nossos príncipes, e a nossos pais, como também a todo o povo da terra.'),
('acf','dn',9,7,'A ti, ó Senhor, pertence a justiça, mas a nós a confusão de rosto, como hoje se vê; aos homens de Judá, e aos moradores de Jerusalém, e a todo o Israel, aos de perto e aos de longe, em todas as terras por onde os tens lançado, por causa das suas rebeliões que cometeram contra ti.'),
('acf','dn',9,8,'Ó Senhor, a nós pertence a confusão de rosto, aos nossos reis, aos nossos príncipes, e a nossos pais, porque pecamos contra ti.'),
('acf','dn',9,9,'Ao Senhor, nosso Deus, pertencem a misericórdia, e o perdão; pois nos rebelamos contra ele,'),
('acf','dn',9,10,'E não obedecemos à voz do Senhor, nosso Deus, para andarmos nas suas leis, que nos deu por intermédio de seus servos, os profetas.'),
('acf','dn',9,11,'Sim, todo o Israel transgrediu a tua lei, desviando-se para não obedecer à tua voz; por isso a maldição e o juramento, que estão escritos na lei de Moisés, servo de Deus, se derramaram sobre nós; porque pecamos contra ele.'),
('acf','dn',9,12,'E ele confirmou a sua palavra, que falou contra nós, e contra os nossos juízes que nos julgavam, trazendo sobre nós um grande mal; porquanto debaixo de todo o céu nunca se fez como se tem feito em Jerusalém.'),
('acf','dn',9,13,'Como está escrito na lei de Moisés, todo este mal nos sobreveio; apesar disso, não suplicamos à face do Senhor nosso Deus, para nos convertermos das nossas iniqüidades, e para nos aplicarmos à tua verdade.'),
('acf','dn',9,14,'Por isso o Senhor vigiou sobre o mal, e o trouxe sobre nós; porque justo é o Senhor, nosso Deus, em todas as suas obras, que fez, pois não obedecemos à sua voz.'),
('acf','dn',9,15,'Agora, pois, ó Senhor, nosso Deus, que tiraste o teu povo da terra do Egito com mão poderosa, e ganhaste para ti nome, como hoje se vê; temos pecado, temos procedido impiamente.'),
('acf','dn',9,16,'Ó Senhor, segundo todas as tuas justiças, aparte-se a tua ira e o teu furor da tua cidade de Jerusalém, do teu santo monte; porque por causa dos nossos pecados, e por causa das iniqüidades de nossos pais, tornou-se Jerusalém e o teu povo um opróbrio para todos os que estão em redor de nós.'),
('acf','dn',9,17,'Agora, pois, ó Deus nosso, ouve a oração do teu servo, e as suas súplicas, e sobre o teu santuário assolado faze resplandecer o teu rosto, por amor do Senhor.'),
('acf','dn',9,18,'Inclina, ó Deus meu, os teus ouvidos, e ouve; abre os teus olhos, e olha para a nossa desolação, e para a cidade que é chamada pelo teu nome, porque não lançamos as nossas súplicas perante a tua face fiados em nossas justiças, mas em tuas muitas misericórdias.'),
('acf','dn',9,19,'Ó Senhor, ouve; ó Senhor, perdoa; ó Senhor, atende-nos e age sem tardar; por amor de ti mesmo, ó Deus meu; porque a tua cidade e o teu povo são chamados pelo teu nome.'),
('acf','dn',9,20,'Estando eu ainda falando e orando, e confessando o meu pecado, e o pecado do meu povo Israel, e lançando a minha súplica perante a face do Senhor, meu Deus, pelo monte santo do meu Deus,'),
('acf','dn',9,21,'Estando eu, digo, ainda falando na oração, o homem Gabriel, que eu tinha visto na minha visão ao princípio, veio, voando rapidamente, e tocou-me, à hora do sacrifício da tarde.'),
('acf','dn',9,22,'Ele me instruiu, e falou comigo, dizendo: Daniel, agora saí para fazer-te entender o sentido.'),
('acf','dn',9,23,'No princípio das tuas súplicas, saiu a ordem, e eu vim, para to declarar, porque és mui amado; considera, pois, a palavra, e entende a visão.'),
('acf','dn',9,24,'Setenta semanas estão determinadas sobre o teu povo, e sobre a tua santa cidade, para cessar a transgressão, e para dar fim aos pecados, e para expiar a iniqüidade, e trazer a justiça eterna, e selar a visão e a profecia, e para ungir o Santíssimo.'),
('acf','dn',9,25,'Sabe e entende: desde a saída da ordem para restaurar, e para edificar a Jerusalém, até ao Messias, o Príncipe, haverá sete semanas, e sessenta e duas semanas; as ruas e o muro se reedificarão, mas em tempos angustiosos.'),
('acf','dn',9,26,'E depois das sessenta e duas semanas será cortado o Messias, mas não para si mesmo; e o povo do príncipe, que há de vir, destruirá a cidade e o santuário, e o seu fim será com uma inundação; e até ao fim haverá guerra; estão determinadas as assolações.'),
('acf','dn',9,27,'E ele firmará aliança com muitos por uma semana; e na metade da semana fará cessar o sacrifício e a oblação; e sobre a asa das abominações virá o assolador, e isso até à consumação; e o que está determinado será derramado sobre o assolador.'),
('acf','dn',10,1,'No terceiro ano de Ciro, rei da Pérsia, foi revelada uma palavra a Daniel, cujo nome era Beltessazar; a palavra era verdadeira e envolvia grande conflito; e ele entendeu esta palavra, e tinha entendimento da visão.'),
('acf','dn',10,2,'Naqueles dias eu, Daniel, estive triste por três semanas.'),
('acf','dn',10,3,'Alimento desejável não comi, nem carne nem vinho entraram na minha boca, nem me ungi com ungüento, até que se cumpriram as três semanas.'),
('acf','dn',10,4,'E no dia vinte e quatro do primeiro mês eu estava à borda do grande rio Hidequel;'),
('acf','dn',10,5,'E levantei os meus olhos, e olhei, e eis um homem vestido de linho, e os seus lombos cingidos com ouro fino de Ufaz;'),
('acf','dn',10,6,'E o seu corpo era como berilo, e o seu rosto parecia um relâmpago, e os seus olhos como tochas de fogo, e os seus braços e os seus pés brilhavam como bronze polido; e a voz das suas palavras era como a voz de uma multidão.'),
('acf','dn',10,7,'E só eu, Daniel, tive aquela visão. Os homens que estavam comigo não a viram; contudo caiu sobre eles um grande temor, e fugiram, escondendo-se.'),
('acf','dn',10,8,'Fiquei, pois, eu só, a contemplar esta grande visão, e não ficou força em mim; transmudou-se o meu semblante em corrupção, e não tive força alguma.'),
('acf','dn',10,9,'Contudo ouvi a voz das suas palavras; e, ouvindo o som das suas palavras, eu caí sobre o meu rosto num profundo sono, com o meu rosto em terra.'),
('acf','dn',10,10,'E eis que certa mão me tocou, e fez com que me movesse sobre os meus joelhos e sobre as palmas das minhas mãos.'),
('acf','dn',10,11,'E me disse: Daniel, homem muito amado, entende as palavras que vou te dizer, e levanta-te sobre os teus pés, porque a ti sou enviado. E, falando ele comigo esta palavra, levantei-me tremendo.'),
('acf','dn',10,12,'Então me disse: Não temas, Daniel, porque desde o primeiro dia em que aplicaste o teu coração a compreender e a humilhar-te perante o teu Deus, são ouvidas as tuas palavras; e eu vim por causa das tuas palavras.'),
('acf','dn',10,13,'Mas o príncipe do reino da Pérsia me resistiu vinte e um dias, e eis que Miguel, um dos primeiros príncipes, veio para ajudar-me, e eu fiquei ali com os reis da Pérsia.'),
('acf','dn',10,14,'Agora vim, para fazer-te entender o que há de acontecer ao teu povo nos derradeiros dias; porque a visão é ainda para muitos dias.'),
('acf','dn',10,15,'E, falando ele comigo estas palavras, abaixei o meu rosto para a terra, e emudeci.'),
('acf','dn',10,16,'E eis que alguém, semelhante aos filhos dos homens, tocou-me os lábios; então abri a minha boca, e falei, dizendo àquele que estava em pé diante de mim: senhor meu, por causa da visão sobrevieram-me dores, e não me ficou força alguma.'),
('acf','dn',10,17,'Como, pois, pode o servo do meu senhor falar com o meu senhor? Porque, quanto a mim, desde agora não resta força em mim, e nem fôlego ficou em mim.'),
('acf','dn',10,18,'E aquele, que tinha aparência de um homem, tocou-me outra vez, e fortaleceu-me.'),
('acf','dn',10,19,'E disse: Não temas, homem muito amado, paz seja contigo; anima-te, sim, anima-te. E, falando ele comigo, fiquei fortalecido, e disse: Fala, meu senhor, porque me fortaleceste.'),
('acf','dn',10,20,'E ele disse: Sabes por que eu vim a ti? Agora, pois, tornarei a pelejar contra o príncipe dos persas; e, saindo eu, eis que virá o príncipe da Grécia.'),
('acf','dn',10,21,'Mas eu te declararei o que está registrado na escritura da verdade; e ninguém há que me anime contra aqueles, senão Miguel, vosso príncipe.'),
('acf','dn',11,1,'Eu, pois, no primeiro ano de Dario, o medo, levantei-me para animá-lo e fortalecê-lo.'),
('acf','dn',11,2,'E agora te declararei a verdade: Eis que ainda três reis estarão na Pérsia, e o quarto acumulará grandes riquezas, mais do que todos; e, tornando-se forte, por suas riquezas, suscitará a todos contra o reino da Grécia.'),
('acf','dn',11,3,'Depois se levantará um rei valente, que reinará com grande domínio, e fará o que lhe aprouver.'),
('acf','dn',11,4,'Mas, estando ele em pé, o seu reino será quebrado, e será repartido para os quatro ventos do céu; mas não para a sua posteridade, nem tampouco segundo o seu domínio com que reinou, porque o seu reino será arrancado, e passará a outros que não eles.'),
('acf','dn',11,5,'E será forte o rei do sul; mas um dos seus príncipes será mais forte do que ele, e reinará poderosamente; seu domínio será grande.'),
('acf','dn',11,6,'Mas, ao fim de alguns anos, eles se aliarão; e a filha do rei do sul virá ao rei do norte para fazer um tratado; mas ela não reterá a força do seu braço; nem ele persistirá, nem o seu braço, porque ela será entregue, e os que a tiverem trazido, e seu pai, e o que a fortalecia naqueles tempos.'),
('acf','dn',11,7,'Mas de um renovo das raízes dela um se levantará em seu lugar, e virá com o exército, e entrará na fortaleza do rei do norte, e operará contra eles, e prevalecerá.'),
('acf','dn',11,8,'Também os seus deuses com as suas imagens de fundição, com os seus objetos preciosos de prata e ouro, levará cativos para o Egito; e por alguns anos ele persistirá contra o rei do norte.'),
('acf','dn',11,9,'E entrará no reino o rei do sul, e tornará para a sua terra.'),
('acf','dn',11,10,'Mas seus filhos intervirão e reunirão uma multidão de grandes forças; e virá apressadamente e inundará, e passará adiante; e, voltando levará a guerra até a sua fortaleza.'),
('acf','dn',11,11,'Então o rei do sul se exasperará, e sairá, e pelejará contra ele, contra o rei do norte; este porá em campo grande multidão, e aquela multidão será entregue na sua mão.'),
('acf','dn',11,12,'A multidão será tirada e o seu coração se elevará; mas ainda que derrubará muitos milhares, contudo não prevalecerá.'),
('acf','dn',11,13,'Porque o rei do norte tornará, e porá em campo uma multidão maior do que a primeira, e ao fim dos tempos, isto é, de anos, virá à pressa com grande exército e com muitas riquezas.'),
('acf','dn',11,14,'E, naqueles tempos, muitos se levantarão contra o rei do sul; e os violentos dentre o teu povo se levantarão para cumprir a visão, mas eles cairão.'),
('acf','dn',11,15,'E o rei do norte virá, e levantará baluartes, e tomará a cidade forte; e os braços do sul não poderão resistir, nem o seu povo escolhido, pois não haverá força para resistir.'),
('acf','dn',11,16,'O que, pois, há de vir contra ele fará segundo a sua vontade, e ninguém poderá resistir diante dele; e estará na terra gloriosa, e por sua mão haverá destruição.'),
('acf','dn',11,17,'E dirigirá o seu rosto, para vir com a potência de todo o seu reino, e com ele os retos, assim ele fará; e lhe dará uma filha das mulheres, para corrompê-la; ela, porém, não subsistirá, nem será para ele.'),
('acf','dn',11,18,'Depois virará o seu rosto para as ilhas, e tomará muitas; mas um príncipe fará cessar o seu opróbrio contra ele, e ainda fará recair sobre ele o seu opróbrio.'),
('acf','dn',11,19,'Virará então o seu rosto para as fortalezas da sua própria terra, mas tropeçará, e cairá, e não será achado.'),
('acf','dn',11,20,'E em seu lugar se levantará quem fará passar um arrecadador pela glória do reino; mas em poucos dias será quebrantado, e isto sem ira e sem batalha.'),
('acf','dn',11,21,'Depois se levantará em seu lugar um homem vil, ao qual não tinham dado a dignidade real; mas ele virá caladamente, e tomará o reino com engano.'),
('acf','dn',11,22,'E com os braços de uma inundação serão varridos de diante dele; e serão quebrantados, como também o príncipe da aliança.'),
('acf','dn',11,23,'E, depois do concerto com ele, usará de engano; e subirá, e se tornará forte com pouca gente.'),
('acf','dn',11,24,'Virá também caladamente aos lugares mais férteis da província, e fará o que nunca fizeram seus pais, nem os pais de seus pais; repartirá entre eles a presa e os despojos, e os bens, e formará os seus projetos contra as fortalezas, mas por certo tempo.'),
('acf','dn',11,25,'E suscitará a sua força e a sua coragem contra o rei do sul com um grande exército; e o rei do sul se envolverá na guerra com um grande e mui poderoso exército; mas não subsistirá, porque maquinarão projetos contra ele.'),
('acf','dn',11,26,'E os que comerem os seus alimentos o destruirão; e o exército dele será arrasado, e cairão muitos mortos.'),
('acf','dn',11,27,'Também estes dois reis terão o coração atento para fazerem o mal, e a uma mesma mesa falarão a mentira; mas isso não prosperará, porque ainda verá o fim no tempo determinado.'),
('acf','dn',11,28,'Então tornará para a sua terra com muitos bens, e o seu coração será contra a santa aliança; e fará o que lhe aprouver, e tornará para a sua terra.'),
('acf','dn',11,29,'No tempo determinado tornará a vir em direção do sul; mas não será na última vez como foi na primeira.'),
('acf','dn',11,30,'Porque virão contra ele navios de Quitim, que lhe causarão tristeza; e voltará, e se indignará contra a santa aliança, e fará o que lhe aprouver; voltará e atenderá aos que tiverem abandonado a santa aliança.'),
('acf','dn',11,31,'E braços serão colocados sobre ele, que profanarão o santuário e a fortaleza, e tirarão o sacrifício contínuo, estabelecendo abominação desoladora.'),
('acf','dn',11,32,'E aos violadores da aliança ele com lisonjas perverterá, mas o povo que conhece ao seu Deus se tornará forte e fará proezas.'),
('acf','dn',11,33,'E os entendidos entre o povo ensinarão a muitos; todavia cairão pela espada, e pelo fogo, e pelo cativeiro, e pelo roubo, por muitos dias.'),
('acf','dn',11,34,'E, caindo eles, serão ajudados com pequeno socorro; mas muitos se ajuntarão a eles com lisonjas.'),
('acf','dn',11,35,'E alguns dos entendidos cairão, para serem provados, purificados, e embranquecidos, até ao fim do tempo, porque será ainda para o tempo determinado.'),
('acf','dn',11,36,'E este rei fará conforme a sua vontade, e levantar-se-á, e engrandecer-se-á sobre todo deus; e contra o Deus dos deuses falará coisas espantosas, e será próspero, até que a ira se complete; porque aquilo que está determinado será feito.'),
('acf','dn',11,37,'E não terá respeito ao Deus de seus pais, nem terá respeito ao amor das mulheres, nem a deus algum, porque sobre tudo se engrandecerá.'),
('acf','dn',11,38,'Mas em seu lugar honrará a um deus das forças; e a um deus a quem seus pais não conheceram honrará com ouro, e com prata, e com pedras preciosas, e com coisas agradáveis.'),
('acf','dn',11,39,'Com o auxílio de um deus estranho agirá contra as poderosas fortalezas; aos que o reconhecerem multiplicará a honra, e os fará reinar sobre muitos, e repartirá a terra por preço.'),
('acf','dn',11,40,'E, no fim do tempo, o rei do sul lutará com ele, e o rei do norte se levantará contra ele com carros, e com cavaleiros, e com muitos navios; e entrará nas suas terras e as inundará, e passará.'),
('acf','dn',11,41,'E entrará na terra gloriosa, e muitos países cairão, mas da sua mão escaparão estes: Edom e Moabe, e os chefes dos filhos de Amom.'),
('acf','dn',11,42,'E estenderá a sua mão contra os países, e a terra do Egito não escapará.'),
('acf','dn',11,43,'E apoderar-se-á dos tesouros de ouro e de prata e de todas as coisas preciosas do Egito; e os líbios e os etíopes o seguirão.'),
('acf','dn',11,44,'Mas os rumores do oriente e do norte o espantarão; e sairá com grande furor, para destruir e extirpar a muitos.'),
('acf','dn',11,45,'E armará as tendas do seu palácio entre o mar grande e o monte santo e glorioso; mas chegará ao seu fim, e não haverá quem o socorra.'),
('acf','dn',12,1,'E naquele tempo se levantará Miguel, o grande príncipe, que se levanta a favor dos filhos do teu povo, e haverá um tempo de angústia, qual nunca houve, desde que houve nação até àquele tempo; mas naquele tempo livrar-se-á o teu povo, todo aquele que for achado escrito no livro.'),
('acf','dn',12,2,'E muitos dos que dormem no pó da terra ressuscitarão, uns para vida eterna, e outros para vergonha e desprezo eterno.'),
('acf','dn',12,3,'Os que forem sábios, pois, resplandecerão como o fulgor do firmamento; e os que a muitos ensinam a justiça, como as estrelas sempre e eternamente.'),
('acf','dn',12,4,'E tu, Daniel, encerra estas palavras e sela este livro, até ao fim do tempo; muitos correrão de uma parte para outra, e o conhecimento se multiplicará.'),
('acf','dn',12,5,'Então eu, Daniel, olhei, e eis que estavam em pé outros dois, um deste lado, à beira do rio, e o outro do outro lado, à beira do rio.'),
('acf','dn',12,6,'E ele disse ao homem vestido de linho, que estava sobre as águas do rio: Quando será o fim destas maravilhas?'),
('acf','dn',12,7,'E ouvi o homem vestido de linho, que estava sobre as águas do rio, o qual levantou ao céu a sua mão direita e a sua mão esquerda, e jurou por aquele que vive eternamente que isso seria para um tempo, tempos e metade do tempo, e quando tiverem acabado de espalhar o poder do povo santo, todas estas coisas serão cumpridas.'),
('acf','dn',12,8,'Eu, pois, ouvi, mas não entendi; por isso eu disse: Senhor meu, qual será o fim destas coisas?'),
('acf','dn',12,9,'E ele disse: Vai, Daniel, porque estas palavras estão fechadas e seladas até ao tempo do fim.'),
('acf','dn',12,10,'Muitos serão purificados, e embranquecidos, e provados; mas os ímpios procederão impiamente, e nenhum dos ímpios entenderá, mas os sábios entenderão.'),
('acf','dn',12,11,'E desde o tempo em que o sacrifício contínuo for tirado, e posta a abominação desoladora, haverá mil duzentos e noventa dias.'),
('acf','dn',12,12,'Bem-aventurado o que espera e chega até mil trezentos e trinta e cinco dias.'),
('acf','dn',12,13,'Tu, porém, vai até ao fim; porque descansarás, e te levantarás na tua herança, no fim dos dias.')
